        #region gGSTNValidation(TextBox TXTBOX, KeyPressEventArgs e)
        public bool gGSTNValidation(TextBox TXTBOX, KeyPressEventArgs e)
        {
            //-- AMIPG3783G
            //-- 19AAHHR0653K1ZT || 11CALP15144D1DW
            //---------------------------------------------------------
            if (TXTBOX.SelectionStart >= 0 && TXTBOX.SelectionStart <= 1) //-- NUMERIC
            {
                if (Convert.ToInt64(e.KeyChar) == 8)
                    return true;
                else if (Convert.ToInt64(e.KeyChar) < 48 || Convert.ToInt64(e.KeyChar) > 57)
                    return false;
            }
            //else if (TXTBOX.SelectionStart >= 2 && TXTBOX.SelectionStart <= 6) //-- ALPHABETS
            else if (TXTBOX.SelectionStart >= 2 && TXTBOX.SelectionStart <= 5) //-- ALPHABETS //-- 2018/12/22
            {
                if (Convert.ToInt64(e.KeyChar) == 8)
                    return true;
                else if (Convert.ToInt64(e.KeyChar) < 65 || Convert.ToInt64(e.KeyChar) > 122)
                    return false;
            }
            else if (TXTBOX.SelectionStart >= 6 && TXTBOX.SelectionStart <= 6) //-- NUMERIC
            {
                if (cmnService.J_IsAlphaNumericString(e.KeyChar.ToString()) == false)
                {
                    return false;
                }
            }
            else if (TXTBOX.SelectionStart >= 7 && TXTBOX.SelectionStart <= 10) //-- NUMERIC
            {
                if (Convert.ToInt64(e.KeyChar) == 8)
                    return true;
                else if (Convert.ToInt64(e.KeyChar) < 48 || Convert.ToInt64(e.KeyChar) > 57)
                    return false;
            }
            else if (TXTBOX.SelectionStart >= 11 && TXTBOX.SelectionStart <= 11) //-- ALPHABET
            {
                if (Convert.ToInt64(e.KeyChar) == 8)
                    return true;
                else if (Convert.ToInt64(e.KeyChar) < 65 || Convert.ToInt64(e.KeyChar) > 122)
                    return false;
            }
            else if (TXTBOX.SelectionStart >= 12 && TXTBOX.SelectionStart <= 12) //-- NUMERIC
            {
                //if (Convert.ToInt64(e.KeyChar) == 8)
                //    return true;
                //else if (Convert.ToInt64(e.KeyChar) < 48 || Convert.ToInt64(e.KeyChar) > 57)
                //    return false;
                if (Convert.ToInt64(e.KeyChar) == 8)
                    return true;
                else if (Convert.ToInt64(e.KeyChar) < 65 || Convert.ToInt64(e.KeyChar) > 122)
                {
                    if (Convert.ToInt64(e.KeyChar) < 48 || Convert.ToInt64(e.KeyChar) > 57)
                        return false;
                }
                else if (Convert.ToInt64(e.KeyChar) < 48 || Convert.ToInt64(e.KeyChar) > 57)
                {
                    if (Convert.ToInt64(e.KeyChar) < 65 || Convert.ToInt64(e.KeyChar) > 122)
                        return false;
                }
                else
                    return false;
            }
            else if (TXTBOX.SelectionStart >= 13 && TXTBOX.SelectionStart <= 13) //-- ALPHABET ("Z")
            {
                //if (Convert.ToInt64(e.KeyChar) == 8)
                //    return true;
                //else if (Convert.ToInt64(e.KeyChar) == 90)
                //    return true;
                //else if (Convert.ToInt64(e.KeyChar) == 122)
                //    return true;
                //else
                //    return false;
                if (Convert.ToInt64(e.KeyChar) == 8)
                    return true;
                else if (Convert.ToInt64(e.KeyChar) < 65 || Convert.ToInt64(e.KeyChar) > 122)
                {
                    if (Convert.ToInt64(e.KeyChar) < 48 || Convert.ToInt64(e.KeyChar) > 57)
                        return false;
                }
                else if (Convert.ToInt64(e.KeyChar) < 48 || Convert.ToInt64(e.KeyChar) > 57)
                {
                    if (Convert.ToInt64(e.KeyChar) < 65 || Convert.ToInt64(e.KeyChar) > 122)
                        return false;
                }
                else
                    return false;
            }
            else if (TXTBOX.SelectionStart >= 14 && TXTBOX.SelectionStart <= 14)
            {
                if (Convert.ToInt64(e.KeyChar) == 8)
                    return true;
                else if (Convert.ToInt64(e.KeyChar) < 65 || Convert.ToInt64(e.KeyChar) > 122)
                {
                    if (Convert.ToInt64(e.KeyChar) < 48 || Convert.ToInt64(e.KeyChar) > 57)
                        return false;
                }
                else if (Convert.ToInt64(e.KeyChar) < 48 || Convert.ToInt64(e.KeyChar) > 57)
                {
                    if (Convert.ToInt64(e.KeyChar) < 65 || Convert.ToInt64(e.KeyChar) > 122)
                        return false;
                }
                else
                    return false;
            }
            else
                if (Convert.ToInt64(e.KeyChar) != 8)
                    return false;

            return true;
        }
