        {
            strSQL = "SELECT  BASIC_INFO_ID " +
                    " FROM    TRN_BASIC_INFO " +
                    " WHERE   ASST_ID    =  " + FYID + " " +
                    " AND     QTR        = '" + Qtr + "'" +
                    " AND     COMPANY_ID =  " + CompanyID + " " +
                    " AND     FORM_NO    = '" + cmnService.J_ReplaceQuote(FormNo) + "'";

            return cmnService.J_NullToZero(dmlService.J_ExecSqlReturnScalar(command, strSQL));
