        #region T_ReturnQuarterStartDate
        public string T_ReturnQuarterStartDate(string Qtr, string FinancialYear)
        {
            if (Qtr == "Q1")
                return "01/04/" + cmnService.J_Left(FinancialYear,4);
            else if (Qtr == "Q2")
                return "01/07/" + cmnService.J_Left(FinancialYear, 4);
            else if (Qtr == "Q3")
                return "01/10/" + cmnService.J_Left(FinancialYear, 4);
            else //if (Qtr == "Q4")
                return "01/01/" + (cmnService.J_ReturnInt32Value(cmnService.J_Left(FinancialYear, 4)) + 1);
        }
        #endregion

        #region T_ReturnQuarterEndDate
        public string T_ReturnQuarterEndDate(string Qtr, string FinancialYear)
        {
            if (Qtr == "Q1")
                return "30/06/" + cmnService.J_Left(FinancialYear, 4);
            else if (Qtr == "Q2")
                return "30/09/" + cmnService.J_Left(FinancialYear, 4);
            else if (Qtr == "Q3")
                return "31/12/" + cmnService.J_Left(FinancialYear, 4);
            else //if (Qtr == "Q4")
                return "31/03/" + (cmnService.J_ReturnInt32Value(cmnService.J_Left(FinancialYear, 4)) + 1);
        }
        #endregion

        #region T_WriteField [ OVERLOADED METHOD ]

        #region T_WriteField [1]
        public string T_WriteField(string str)
        {
            return str.Trim() + "^";
        }
        #endregion

        #region T_WriteField [2]
        public string T_WriteField(string str, string strFormat)
        {
            return string.Format("{0:" + strFormat + "}",Convert.ToDouble(str.Trim() == "" ? "0" : str.Trim())) + "^";
        }
        #endregion

        #endregion

        #region T_WriteBlankField
        public string T_WriteBlankField(int intOccurence, string strRepeatCharacter)
        {
            string strReturn = "";

            if (intOccurence == 0) return "";

            for (int i = 1; i <= intOccurence; i++)
                strReturn = strReturn + strRepeatCharacter;
            return strReturn;
        }
        #endregion

        #region J_IsProcessOpen
        public bool J_IsProcessOpen(string ProcessName)
        {
            foreach (Process process in Process.GetProcesses())
                if (process.ProcessName.Contains(ProcessName))
                    return true;
            return false;
        }
        #endregion

