        #region J_ConvertToIntDDMMYYYY [2]
        public string J_ConvertToIntDDMMYYYY(string date)
        {
            if (date == "" || date == null) return "";
            //return Convert.ToInt32(date.Substring(6, 4) + date.Substring(3, 2) + date.Substring(0, 2));
            return Convert.ToString(date.Substring(0, 2) + date.Substring(3, 2) + date.Substring(6, 4));
        }
