        #region T_CheckPROXY
        public bool T_CheckPROXY()
        {
            try
            {
                if (System.Net.WebRequest.DefaultWebProxy.GetProxy(new System.Uri("http://www.tdsman.com")).ToString() == "http://www.tdsman.com/")
                    return false;
                else
                {
                    if (TDSMAN.T_ProxySettings == T_YES_NO.YES)
                    {
                        if (T_ConnectWebProxy() == true)
                        {
                            if (T_ConnectFileTransferProxy() == true)
                                // A proxy is in use
                                return true;
                            else
                                return false;
                            // A proxy is in use
                            //return true;
                        }
                        else
                            return false;
                    }
                    else
                    {
                        TrnProxySettings TrnProxySettings = new TrnProxySettings();
                        TrnProxySettings.ShowDialog();
                        return false;
                    }
                }
            }
            catch (Exception ERR)
            {
                return false; // host not reachable.
            }
        }
        #endregion

        #region T_ConnectWebProxy
        public bool T_ConnectWebProxy()
        {
            try
            {
                //HttpWebRequest webRequest = WebRequest.Create(uirTradeStream) as HttpWebRequest;
                //webRequest.Proxy = WebRequest.DefaultWebProxy;
                //webRequest.Credentials = new NetworkCredential("user", "password", "domain");
                //webRequest.Proxy.Credentials = new NetworkCredential("user", "password", "domain");
                //@@@@@@@@@@@@@@@@@
                WebProxy proxyObject = new WebProxy("http://" + TDSMAN.T_ProxyAddress + "/", cmnService.J_ReturnInt32Value(TDSMAN.T_ProxyPort));
                //
                if (TDSMAN.T_ProxyUsername != "")
                    proxyObject.Credentials = new NetworkCredential(TDSMAN.T_ProxyUsername, TDSMAN.T_ProxyPassword);
                else
                    proxyObject.UseDefaultCredentials = true;

                //
                WebRequest req = WebRequest.Create("http://www.tdsman.com");
                req.Credentials = new NetworkCredential(TDSMAN.T_ProxyUsername, TDSMAN.T_ProxyPassword);
                req.Proxy.Credentials = new NetworkCredential(TDSMAN.T_ProxyUsername, TDSMAN.T_ProxyPassword);
                req.Proxy = proxyObject;
                return true;
            }
            catch (Exception ERR)
            {
                return false; // host not reachable.
            }
        }
        #endregion

        #region T_ConnectFileTransferProxy
        public bool T_ConnectFileTransferProxy()
        {
            try
            {
                WebProxy proxyObject = new WebProxy("http://" + TDSMAN.T_ProxyAddress + "/", cmnService.J_ReturnInt32Value(TDSMAN.T_ProxyPort));
                //
                if (TDSMAN.T_ProxyUsername != "")
                    proxyObject.Credentials = new NetworkCredential(TDSMAN.T_ProxyUsername, TDSMAN.T_ProxyPassword);
                else
                    proxyObject.UseDefaultCredentials = true;
                //
                WebRequest req = WebRequest.Create("http://www.tdsman.com");
                //req.Credentials = new NetworkCredential(TDSMAN.HOST_USER_NAME, TDSMAN.HOST_PASSWORD);
                //req.Proxy.Credentials = new NetworkCredential(TDSMAN.HOST_USER_NAME, TDSMAN.HOST_PASSWORD);
                req.Proxy = proxyObject;
                return true;
            }
            catch (Exception ERR)
            {
                return false; // host not reachable.
            }
        }
        #endregion

