        #region T_DateDiff
        public double T_DateDiff(T_DATE_DIFF DATE_DIFF, System.DateTime startDate, System.DateTime endDate)
        {
            double diff = 0;
            System.TimeSpan TS = new System.TimeSpan(endDate.Ticks - startDate.Ticks);
            
            if(DATE_DIFF == T_DATE_DIFF.YEAR)
                diff = Convert.ToDouble(TS.TotalDays / 365);
            else if (DATE_DIFF == T_DATE_DIFF.MONTH)
                diff = Convert.ToDouble((TS.TotalDays / 365) * 12);
            else if (DATE_DIFF == T_DATE_DIFF.DAY)
                diff = Convert.ToDouble(TS.TotalDays);
            else if (DATE_DIFF == T_DATE_DIFF.HOUR)
                diff = Convert.ToDouble(TS.TotalHours);
            else if (DATE_DIFF == T_DATE_DIFF.MINUTE)
                diff = Convert.ToDouble(TS.TotalMinutes);
            else if (DATE_DIFF == T_DATE_DIFF.SECOND)
                diff = Convert.ToDouble(TS.TotalSeconds);

            return diff;
        }
        #endregion



        #region INSERT_UPDATE_ACCESS_DATETIME
        public bool T_Insert_Update_Access_Datetime(IDbCommand command, long BasicInfoBatchHeaderId, bool Correction)
        {
            try
            {
                //--
                if (BasicInfoBatchHeaderId > 0)
                {
                    if (Correction == false)
                    {
                        strSQL = "SELECT  COUNT(*) " +
                                " FROM    TRN_BASIC_INFO " +
                                " WHERE   BASIC_INFO_ID    =  " + BasicInfoBatchHeaderId;
                        if (cmnService.J_NullToZero(dmlService.J_ExecSqlReturnScalar(command, strSQL)) > 0)
                        {
                            strSQL = "SELECT  COUNT(*) " +
                                    " FROM    TRN_CHALLAN " +
                                    " WHERE   BASIC_INFO_ID    =  " + BasicInfoBatchHeaderId;
                            if (cmnService.J_NullToZero(dmlService.J_ExecSqlReturnScalar(command, strSQL)) > 0)
                            {
                                strSQL = "UPDATE TRN_BASIC_INFO SET LAST_ACCESS_DATETIME = " + cmnService.J_DateOperator() + J_ReturnServerDateTimeMMDDYYYYHHMMSS() + cmnService.J_DateOperator() + " WHERE BASIC_INFO_ID =  " + BasicInfoBatchHeaderId;
                                if (dmlService.J_ExecSql(strSQL) == false)
                                    return false;
                                else
                                    return true;
                            }
                        }
                        else
                            return false;
                    }
                    else if (Correction == true)
                    {
                        strSQL = "SELECT  COUNT(*) " +
                                " FROM    COR_HDR_BATCH " +
                                " WHERE   BATCH_HEADER_ID =  " + BasicInfoBatchHeaderId;
                        if (cmnService.J_NullToZero(dmlService.J_ExecSqlReturnScalar(command, strSQL)) > 0)
                        {
                            strSQL = "UPDATE COR_HDR_BATCH SET LAST_ACCESS_DATETIME = " + cmnService.J_DateOperator() + J_ReturnServerDateTimeMMDDYYYYHHMMSS() + cmnService.J_DateOperator() + " WHERE BATCH_HEADER_ID =  " + BasicInfoBatchHeaderId;
                            if (dmlService.J_ExecSql(strSQL) == false)
                                return false;
                            else
                                return true;
                        }
                        else
                            return false;
                    }
                }
                //--
                return true;
            }
            catch (Exception err)
            {
                cmnService.J_UserMessage(err.Message);
                return false;
            }
        }
        #endregion

