                            strSQL = "UPDATE COR_HDR_BATCH SET PREDICT_DEFAULTS_ACCESS_DATETIME = " + cmnService.J_DateOperator() + J_ReturnServerDateTimeMMDDYYYYHHMMSS() + cmnService.J_DateOperator() + ", PREDICT_DEFAULTS_STATUS = " + DefaultStatus + " WHERE BATCH_HEADER_ID =  " + BasicInfoBatchHeaderId;
                            if (dmlService.J_ExecSql(strSQL) == false)
                                return false;
                            else
                                return true;
                        }
                        else
                            return false;
                    }
                }
                //--
                return true;
            }
            catch (Exception err)
            {
                cmnService.J_UserMessage(err.Message);
                return false;
            }
