        #region REPLACE SPECIAL CHARACTERS

        #region T_ReplaceSpecialCharacters

        public string T_ReplaceSpecialCharacters(string StrText, T_Datatype DataType)
        {
            StringBuilder sb = new StringBuilder();

            switch (DataType)
            {
                case T_Datatype.Currency:
                    foreach (char ch in StrText)
                    {
                        if ((ch >= '0' && ch <= '9') || (ch == '.'))
                            sb.Append(ch);
                        else
                            continue;
                    }
                    break;
                
                case T_Datatype.Date:
                    foreach (char ch in StrText)
                    {
                        if ((ch >= '0' && ch <= '9') ||
                            (ch == '/' || ch == ':' || ch == ' ' || ch == '-' || ch == ',') ||
                            (ch >= 'A' && ch <= 'z'))
                            sb.Append(ch);
                        else
                            continue;
                    }
                    break;

                case T_Datatype.Numeric:
                    foreach (char ch in StrText)
                    {
                        if ((ch >= '0' && ch <= '9'))
                            sb.Append(ch);
                        else
                            continue;
                    }
                    break;

                case T_Datatype.Text:
                    foreach (char ch in StrText)
                    {
                        if (((int)ch >= 32 && (int)ch <= 126))
                            sb.Append(ch);
                        else
                            continue;
                    }
                    break;
            }

            if (sb != null)
                return sb.ToString();
            else
                return "";
        }
        #endregion

        #region T_ReplaceSpecialCharacters

        public string T_ReplaceSpecialCharacters(string StrText, string StrReplaceText)
        {
            string[] chars = new string[] { ",", ".", "/", "!", "@", "#", "$", "%", "^", "&", "*", "'", "\"", ";", "_", "(", ")", ":", "|", "[", "]" };

            for (int i = 0; i < chars.Length; i++)
            {
                if (StrText.Contains(chars[i]))
                {
                    StrText = StrText.Replace(chars[i], StrReplaceText);
                }
            }
            return StrText;
        }
        #endregion

        #region RemoveSpecialCharacters
        //http://stackoverflow.com/questions/1120198/most-efficient-way-to-remove-special-characters-from-string
        public string RemoveSpecialCharacters(string str)
        {
            //return Regex.Replace(str, "[^a-zA-Z0-9_.]+", "", RegexOptions.Compiled);
            return Regex.Replace(str, "[^a-zA-Z0-9_.\x20]", "", RegexOptions.Compiled);
        }
        #endregion

        #endregion

        #region SplitWords
        static string[] SplitWords(string s)
        {
            //
            // Split on all non-word characters.
            // ... Returns an array of all the words.
            //
            return Regex.Split(s, @"\W+");
            // @      special verbatim string syntax
            // \W+    one or more non-word characters together
        }
        #endregion

        #region REPLACE Ampersand
        public string T_ReplaceAmpersand(string StrText)
        {
            return StrText.Replace("&", "&&");
        }
        #endregion

        #region Detect caret
        public bool T_DetectCaret(string StrText, string FindChar)
        {
            if (StrText.IndexOf(FindChar) < 0)
                return false;
            //
            return true;
        }
        #endregion

        #region T_CheckJREInstalled
        public bool T_CheckJREInstalled()
        {
            try
            {
                Process p = new Process();
                p.StartInfo.UseShellExecute = false;
                p.StartInfo.RedirectStandardOutput = true;
                p.StartInfo.RedirectStandardError = true;
                p.StartInfo.CreateNoWindow = true;
                p.StartInfo.FileName = "java";
                p.StartInfo.Arguments = "-version";
                p.Start();
                string output = p.StandardOutput.ReadToEnd();
                string error = p.StandardError.ReadToEnd();
                p.WaitForExit();
                return true;
            }
            catch //(Exception err_handler)
            {
                //cmnService.J_UserMessage(err_handler.Message);
                //cmnService.J_UserMessage("JAVA is not installed or not correctly installed.. Pls Re-install it..");
                return false;
            }
        }
