        #region T_CheckSameFAYear

        #region T_CheckSameFAYear(string Date1, string Date2)
        public bool T_CheckSameFAYear(string Date1, string Date2)
        {
            try
            {
                string strDate1 = "SELECT ASST_ID " +
                                  "FROM   MST_ASSESSMENT " +
                                  "WHERE  " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(Date1) + cmnService.J_DateOperator() + " " +
                                  "       BETWEEN START_DATE AND END_DATE";
                
                string strDate2 = "SELECT ASST_ID " +
                                  "FROM   MST_ASSESSMENT " +
                                  "WHERE  " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(Date2) + cmnService.J_DateOperator() + " " +
                                  "       BETWEEN START_DATE AND END_DATE";

                if (Convert.ToInt32(dmlService.J_ReturnId(strDate1)) == Convert.ToInt32(dmlService.J_ReturnId(strDate2)))
                    return true;
                else
                    return false;
            }
            catch
            {
                return false;
            }
        }
