        #region DATE_METHODS

            #region GetFirstDayOfMonth(DateTime dtDate)
            /// <summary>
            /// Get the first day of the month for
            /// any full date submitted
            /// </summary>
            /// <param name="dtDate"></param>
            /// <returns></returns>
            public DateTime GetFirstDayOfMonth(DateTime dtDate)
            {
                // set return value to the first day of the month
                // for any date passed in to the method

                // create a datetime variable set to the passed in date
                DateTime dtFrom = dtDate;

                // remove all of the days in the month
                // except the first day and set the
                // variable to hold that date
                dtFrom = dtFrom.AddDays(-(dtFrom.Day - 1));

                // return the first day of the month
                return dtFrom;
            }
            #endregion

            #region GetFirstDayOfMonth(int iMonth)
            /// <summary>
            /// Get the first day of the month for a
            /// month passed by it's integer value
            /// </summary>
            /// <param name="iMonth"></param>
            /// <returns></returns>
            public DateTime GetFirstDayOfMonth(int iMonth)
            {
                // set return value to the last day of the month
                // for any date passed in to the method

                // create a datetime variable set to the passed in date
                DateTime dtFrom = new DateTime(DateTime.Now.Year, iMonth, 1);

                // remove all of the days in the month
                // except the first day and set the
                // variable to hold that date
                dtFrom = dtFrom.AddDays(-(dtFrom.Day - 1));

                // return the first day of the month
                return dtFrom;
            }
            #endregion


            #region GetFirstDayOfMonth(int iMonth, int Year)
            /// <summary>
            /// Get the first day of the month for a
            /// month passed by it's integer value
            /// </summary>
            /// <param name="iMonth"></param>
            /// <returns></returns>
            public DateTime GetFirstDayOfMonth(int iMonth, int Year)
            {
                // set return value to the last day of the month
                // for any date passed in to the method

                // create a datetime variable set to the passed in date
                DateTime dtFrom = new DateTime(Year, iMonth, 1);

                // remove all of the days in the month
                // except the first day and set the
                // variable to hold that date
                dtFrom = dtFrom.AddDays(-(dtFrom.Day - 1));

                // return the first day of the month
                return dtFrom;
            }
            #endregion

            #region GetLastDayOfMonth(DateTime dtDate)
            /// <summary>
            /// Get the last day of the month for any
            /// full date
            /// </summary>
            /// <param name="dtDate"></param>
            /// <returns></returns>
            public DateTime GetLastDayOfMonth(DateTime dtDate)
            {
                // set return value to the last day of the month
                // for any date passed in to the method

                // create a datetime variable set to the passed in date
                DateTime dtTo = dtDate;

                // overshoot the date by a month
                dtTo = dtTo.AddMonths(1);

                // remove all of the days in the next month
                // to get bumped down to the last day of the
                // previous month
                dtTo = dtTo.AddDays(-(dtTo.Day));

                // return the last day of the month
                return dtTo;
            }
            #endregion

            #region GetLastDayOfMonth(int iMonth, int Year)
            /// <summary>
            /// Get the last day of a month expressed by it's
            /// integer value
            /// </summary>
            /// <param name="iMonth"></param>
            /// <returns></returns>
            public DateTime GetLastDayOfMonth(int iMonth, int Year)
            {

                // set return value to the last day of the month
                // for any date passed in to the method

                // create a datetime variable set to the passed in date
                DateTime dtTo = new DateTime(Year, iMonth, 1);

                // overshoot the date by a month
                dtTo = dtTo.AddMonths(1);

                // remove all of the days in the next month
                // to get bumped down to the last day of the
                // previous month
                dtTo = dtTo.AddDays(-(dtTo.Day));

                // return the last day of the month
                return dtTo;

            }

            #endregion

            #region GetLastDayOfMonth(int iMonth)
            /// <summary>
            /// Get the last day of a month expressed by it's
            /// integer value
            /// </summary>
            /// <param name="iMonth"></param>
            /// <returns></returns>
            public DateTime GetLastDayOfMonth(int iMonth)
            {

                // set return value to the last day of the month
                // for any date passed in to the method

                // create a datetime variable set to the passed in date
                DateTime dtTo = new DateTime(DateTime.Now.Year, iMonth, 1);

                // overshoot the date by a month
                dtTo = dtTo.AddMonths(1);

                // remove all of the days in the next month
                // to get bumped down to the last day of the
                // previous month
                dtTo = dtTo.AddDays(-(dtTo.Day));

                // return the last day of the month
                return dtTo;

            }
            #endregion

