                            //
                            //--
                            #region UPDATE as per MST_REASON
                            strSQL = "CREATE TABLE TEMP_CORR_REASON(DEDUCTEE_DETAIL_ID NUMBER DEFAULT 0, REASON_ID NUMBER DEFAULT 0)";
                            dmlService.J_ExecSql(strSQL);
                            //--
                            strSQL = "INSERT INTO TEMP_CORR_REASON(DEDUCTEE_DETAIL_ID, REASON_ID) " +
                                     "SELECT COR_HDR_DEDUCTEE_DETAILS.HDR_DEDUCTEE_DETAIL_ID, " +
                                     "       MST_REASON.REASON_ID " +
                                     "FROM ((COR_HDR_DEDUCTEE_DETAILS " +
                                     "INNER JOIN COR_HDR_BATCH " +
                                     "ON    COR_HDR_DEDUCTEE_DETAILS.BATCH_HEADER_ID    = COR_HDR_BATCH.BATCH_HEADER_ID) " +
                                     "INNER JOIN MST_REASON " +
                                     "ON    COR_HDR_BATCH.FORM_NO                       = MST_REASON.FORM_NO " +
                                     "AND   COR_HDR_DEDUCTEE_DETAILS.NON_DEDUCTION_FLAG = MST_REASON.REASON)";
                            dmlService.J_ExecSql(strSQL);
                            //--
                            strSQL = "UPDATE COR_HDR_DEDUCTEE_DETAILS " +
                                     "INNER JOIN TEMP_CORR_REASON " +
                                     "ON     COR_HDR_DEDUCTEE_DETAILS.HDR_DEDUCTEE_DETAIL_ID = TEMP_CORR_REASON.DEDUCTEE_DETAIL_ID " +
                                     "SET    COR_HDR_DEDUCTEE_DETAILS.REASON_ID             = TEMP_CORR_REASON.REASON_ID";
                            dmlService.J_ExecSql(strSQL);
                            //--
                            //strSQL = "DROP TABLE TEMP_CORR_REASON";
                            //dmlService.J_ExecSql(strSQL);
                            //--
                            #endregion
                        }
