                            strSQL = "CREATE TABLE TEMP_CORR_REASON(DEDUCTEE_DETAIL_ID NUMBER, REASON_ID NUMBER)";
                            dmlService.J_ExecSql(strSQL);
                            //--
                            strSQL = "INSERT INTO TEMP_CORR_REASON(DEDUCTEE_DETAIL_ID, REASON_ID) " +
                                     "SELECT COR_TRN_DEDUCTEE_DETAILS.TRN_DEDUCTEE_DETAIL_ID, " +
                                     "       MST_REASON.REASON_ID " +
                                     "FROM ((COR_TRN_DEDUCTEE_DETAILS " +
                                     "INNER JOIN COR_HDR_BATCH " +
                                     "ON    COR_TRN_DEDUCTEE_DETAILS.BATCH_HEADER_ID    = COR_HDR_BATCH.BATCH_HEADER_ID) " +
                                     "INNER JOIN MST_REASON " +
                                     "ON    COR_HDR_BATCH.FORM_NO                       = MST_REASON.FORM_NO " +
                                     "AND   COR_TRN_DEDUCTEE_DETAILS.NON_DEDUCTION_FLAG = MST_REASON.REASON)";
                            dmlService.J_ExecSql(strSQL);
                            //--
                            strSQL = "UPDATE COR_TRN_DEDUCTEE_DETAILS " +
                                     "INNER JOIN TEMP_CORR_REASON " +
                                     "ON     COR_TRN_DEDUCTEE_DETAILS.HDR_DEDUCTEE_DETAIL_ID = TEMP_CORR_REASON.DEDUCTEE_DETAIL_ID " +
                                     "SET    COR_TRN_DEDUCTEE_DETAILS.REASON_ID              = TEMP_CORR_REASON.REASON_ID " +
                                     "WHERE  COR_TRN_DEDUCTEE_DETAILS.REASON_ID              = 0 ";
                            dmlService.J_ExecSql(strSQL);
                            //--
                            strSQL = "DROP TABLE TEMP_CORR_REASON";
                            dmlService.J_ExecSql(strSQL);
                            //--
                            #endregion
                        }
