                            dmlService.J_ExecSql(strSQL);
                            //
                            #region UPDATE EXISTING RECORDS
                            strSQL = @"UPDATE (((TRN_NSDL_DOWNLOAD 
                                INNER JOIN TRN_CHALLAN 
                                ON     TRN_NSDL_DOWNLOAD.CHALLAN_NO     = TRN_CHALLAN.CHALLAN_NO)
                                INNER JOIN TRN_BASIC_INFO
                                ON     TRN_CHALLAN.BASIC_INFO_ID        = TRN_BASIC_INFO.BASIC_INFO_ID)
                                INNER JOIN MST_COMPANY
                                ON     TRN_BASIC_INFO.COMPANY_ID        = MST_COMPANY.COMPANY_ID)
                                SET    TRN_NSDL_DOWNLOAD.CHALLAN_SRL_NO = TRN_CHALLAN.SL_NO 
                                WHERE  TRN_NSDL_DOWNLOAD.BSR_CODE       = TRN_CHALLAN.BSR_CODE
                                AND    TRN_NSDL_DOWNLOAD.DEPOSIT_DATE   = TRN_CHALLAN.DEPOSIT_DATE
                                AND    MST_COMPANY.TAN_NO               = TRN_NSDL_DOWNLOAD.TAN_NO
                                AND    TRN_BASIC_INFO.ASST_ID           = TRN_NSDL_DOWNLOAD.ASST_ID
                                AND    TRN_BASIC_INFO.QTR               = TRN_NSDL_DOWNLOAD.QTR
                                AND    TRN_BASIC_INFO.FORM_NO           = TRN_NSDL_DOWNLOAD.FORM_NO
                                AND    TRN_NSDL_DOWNLOAD.CHALLAN_SRL_NO = 0
                                AND    TRN_CHALLAN.BOOK_ENTRY           = 0";
                            dmlService.J_ExecSql(strSQL);
                            //
                            strSQL = @"UPDATE (((TRN_NSDL_DOWNLOAD 
                                INNER JOIN TRN_CHALLAN 
                                ON     TRN_NSDL_DOWNLOAD.CHALLAN_NO     = TRN_CHALLAN.TRANSFER_VOUCHER_NO)
                                INNER JOIN TRN_BASIC_INFO
                                ON     TRN_CHALLAN.BASIC_INFO_ID        = TRN_BASIC_INFO.BASIC_INFO_ID)
                                INNER JOIN MST_COMPANY
                                ON     TRN_BASIC_INFO.COMPANY_ID        = MST_COMPANY.COMPANY_ID)
                                SET    TRN_NSDL_DOWNLOAD.CHALLAN_SRL_NO = TRN_CHALLAN.SL_NO 
                                WHERE  TRN_NSDL_DOWNLOAD.BSR_CODE       = TRN_CHALLAN.BSR_CODE
                                AND    TRN_NSDL_DOWNLOAD.DEPOSIT_DATE   = TRN_CHALLAN.DEPOSIT_DATE
                                AND    MST_COMPANY.TAN_NO               = TRN_NSDL_DOWNLOAD.TAN_NO
                                AND    TRN_BASIC_INFO.ASST_ID           = TRN_NSDL_DOWNLOAD.ASST_ID
                                AND    TRN_BASIC_INFO.QTR               = TRN_NSDL_DOWNLOAD.QTR
                                AND    TRN_BASIC_INFO.FORM_NO           = TRN_NSDL_DOWNLOAD.FORM_NO
                                AND    TRN_NSDL_DOWNLOAD.CHALLAN_SRL_NO = 0
