        #region T_CheckEmailFormat

        public bool T_CheckEmailFormat(string Email)
        {
            if (Email != "")
            {
                if (Email.Contains("@") == false)
                {
                    cmnService.J_UserMessage("Email should have atleast one '@'");
                    return false;
                }
                //--
                if (Email.Contains(".") == false)
                {
                    cmnService.J_UserMessage("Email should have atleast one '.'");
                    return false;
                }
                //--
                if (Email.StartsWith("@") == true)
                {
                    cmnService.J_UserMessage("'@' should be preceded by atleast one character.");
                    return false;
                }
                //
                if (Email.EndsWith("@") == true)
                {
                    cmnService.J_UserMessage("'@' should be succeeded by atleast one character.");
                    return false;
                }
                //--
                if (Email.StartsWith(".") == true)
                {
                    cmnService.J_UserMessage("'.' should be preceded by atleast one character.");
                    return false;
                }
                //
                if (Email.EndsWith(".") == true)
                {
                    cmnService.J_UserMessage("'.' should be succeeded by atleast one character.");
                    return false;
                }
                //--
                if (Email.Substring(Email.IndexOf("@"), (Email.Trim().Length - Email.Trim().IndexOf("@"))).Contains(".") == false)
                {
                    cmnService.J_UserMessage("At least one '.' should come after '@'");
                    return false;
                }
                //-- 2017/04/17
                if (Regex.Matches(Email, "@").Count > 1)
                {
                    cmnService.J_UserMessage("'@' can't be twice in a email.");
                    return false;
                }
                //--
                if (Email.Substring(Email.Trim().IndexOf("@") + 1, 1) == ".")
                {
                    cmnService.J_UserMessage("Invalid Email");
                    return false;
                }
                //
                return true;
            }
            return false;
        }


