        #region T_GenerateOutputFile
        public string T_GenerateOutputFile(string CompanyName, string FinancialYear, string Qtr, string FormNo, long CompanyID, GenerateOutputFile GenerateOutputFile)
        {
            string OutputFile = "";
            int intSpacePosition = 0;
            int intCounter = 0;
            string strFilePrefix = "";
            //
            
            if (GenerateOutputFile == GenerateOutputFile.Regular)
            {
                OutputFile = cmnService.J_Mid(CompanyName, 0, 1);
                //
                intSpacePosition = CompanyName.IndexOf(" ");
                //
                if (intSpacePosition == 0)
                    OutputFile = OutputFile + "A";
                else
                    OutputFile = OutputFile + cmnService.J_Mid(CompanyName, intSpacePosition + 1, 1);
                // 2011-06-22
                if (OutputFile.Trim().Length == 1)
                    OutputFile = OutputFile.Trim() + "A";
                //
                //strSQL = "SELECT COUNT(*) AS COUNT_INPUT_FILE_NAME " +
                //"     FROM   TRN_FILE_GENERATION_LOG," +
                //"            TRN_BASIC_INFO," +
                //"            MST_COMPANY " +
                //"     WHERE  TRN_FILE_GENERATION_LOG.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID " +
                //"     AND    TRN_BASIC_INFO.COMPANY_ID             = MST_COMPANY.COMPANY_ID " +
                //"     AND    INPUT_FILE_NAME                      LIKE '" + OutputFile + "%' " +
                //"     AND    MST_COMPANY.COMPANY_NAME             <> '" + CompanyName + "'";
                ////
                //intCounter = Convert.ToInt32(dmlService.J_ExecSqlReturnScalar(dmlService.J_pCommand, strSQL)) + 1;
                ////
                //OutputFile = OutputFile + intCounter;
                //         
            }
            else if (GenerateOutputFile == GenerateOutputFile.Correction)
            {
                OutputFile = "CR"; 
                 //
            }
            //--
            strSQL = "SELECT COUNT(*) AS COUNT_INPUT_FILE_NAME " +
                "     FROM   TRN_FILE_GENERATION_LOG," +
                "            TRN_BASIC_INFO," +
                "            MST_COMPANY " +
                "     WHERE  TRN_FILE_GENERATION_LOG.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID " +
                "     AND    TRN_BASIC_INFO.COMPANY_ID             = MST_COMPANY.COMPANY_ID " +
                "     AND    INPUT_FILE_NAME                      LIKE '" + OutputFile + "%' " +
                "     AND    TRN_BASIC_INFO.COMPANY_NAME          <> '" + CompanyName + "'";
                //"     AND    MST_COMPANY.COMPANY_NAME             <> '" + CompanyName + "'";
            //intCounter = Convert.ToInt32(dmlService.J_ExecSqlReturnScalar(dmlService.J_pCommand, strSQL)) + 1;
            ////
            //OutputFile = OutputFile + intCounter;
            //
            strFilePrefix = Convert.ToString(dmlService.J_ExecSqlReturnScalar(dmlService.J_pCommand, "SELECT INPUT_FILE_NAME_PREFIX FROM MST_ASSESSMENT WHERE FA_YEAR = '" + FinancialYear + "'"));
            //
            OutputFile = OutputFile + strFilePrefix;
            //
            if (FormNo == T_FormNo.F27EQ)
                OutputFile = OutputFile + cmnService.J_Right(FormNo, 2);
            else
                OutputFile = OutputFile + cmnService.J_Left(FormNo, 2);
            //
            OutputFile = OutputFile + Qtr;
            //-- Anik on 2014/01/24
            OutputFile = T_ReplaceSpecialCharacters(OutputFile,"Q");
            //
            return OutputFile;
        }
        #endregion

        #region T_GenerateDataGridViewSelectedItem
        public string T_GenerateDataGridViewSelectedItem(DataGridView dataGridView, int Column)
        {
            string strItem = "";
            if (dataGridView.RowCount > 0)
            {
                foreach (DataGridViewRow row in dataGridView.Rows)
                    if (row.Cells[0].Value != null && (bool)row.Cells[0].Value == true)
                    {
                        if (row.Cells[Column].Value != "")
                            strItem = strItem + "," + row.Cells[Column].Value.ToString();
                    }

                if (strItem.Length > 0)
                    strItem = cmnService.J_Mid(strItem, 1, strItem.Length - 1);
            }
            return strItem;
        }
        #endregion

        #region POPULATE LIST BOX
        public bool T_PopulateListBox(IDbCommand command, string SqlText, ref CheckedListBox checkedlistbox)
        {
            IDataReader reader = null;

            try
            {
                if (command == null)
                    reader = dmlService.J_ExecSqlReturnReader(SqlText);
                else if (command != null)
                    reader = dmlService.J_ExecSqlReturnReader(command, SqlText);

                if (reader == null)
                {
                    reader.Close();
                    reader.Dispose();
                    return false;
                }

                //cmnService.J_ClearComboBox(ref combobox, DefaultText, ComboBoxDefaultText, J_ComboBoxSelectedIndex.NO);
                checkedlistbox.Items.Clear();

                while (reader.Read())
                    //listbox.Items.Add(new Listbo (reader.GetString(1).ToString(), Convert.ToInt32(reader.GetValue(0))));
                    checkedlistbox.Items.Add(reader.GetString(1).ToString());

                reader.Close();
                reader.Dispose();

                return true;
            }
            catch
            {
                reader.Close();
                reader.Dispose();

                //dmlService.J_CloseConnection();
                //commonservice.J_UserMessage("Connection Failed", MessageBoxIcon.Stop);
                return false;
            }
        }
        #endregion

