        #region T_UpdateSrlNo
        public bool T_UpdateSrlNo(IDbCommand Command, long DeletedSrlNo, long UniqueValue, Updt_SrlNo ChlnDed)
        {
            try
            {

                if (ChlnDed == Updt_SrlNo.ChlnSrlNo)
                {
                    strSQL = "UPDATE TRN_CHALLAN " +
                             "SET    SL_NO = SL_NO - 1 " +
                             "WHERE  SL_NO > " + DeletedSrlNo + " " +
                             "AND    BASIC_INFO_ID = " + UniqueValue;
                }
                else if (ChlnDed == Updt_SrlNo.DeducteeSrlNo)
                {
                    strSQL = "UPDATE TRN_DEDUCTEE_DETAILS " +
                             "SET    SL_NO = SL_NO - 1 " +
                             "WHERE  SL_NO > " + DeletedSrlNo + " " +
                             "AND    CHALLAN_ID = " + UniqueValue;
                }
                else if (ChlnDed == Updt_SrlNo.SalaryDetailSrlNo)
                {
                    strSQL = "UPDATE TRN_SALARY_DETAILS " +
                             "SET    SL_NO = SL_NO - 1 " +
                             "WHERE  SL_NO > " + DeletedSrlNo + " " +
                             "AND    BASIC_INFO_ID = " + UniqueValue;
                }

                if (dmlService.J_ExecSql(Command, strSQL) == false)
                    return false;

                return true;
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
                return false;
            }
        }
        #endregion

        //Added by Indrajit on 13-02-2013 == FOR MS-ACCESS ONLY
        #region T_UpdateSrlNo[2]
        public bool T_UpdateSrlNo(IDbCommand Command, long UniqueValue, Updt_SrlNo ChlnDed)
        {
            if (ChlnDed == Updt_SrlNo.ChlnSrlNo)
            {
                strSQL = "UPDATE TRN_CHALLAN " +
                         "INNER  JOIN " +
                         "      (SELECT DCOUNT('CHALLAN_ID','TRN_CHALLAN','CHALLAN_ID <= ' & T.CHALLAN_ID & ' and  BASIC_INFO_ID = " + UniqueValue + "') AS NEW_SL_NO," +
                         "              CHALLAN_ID," +
                         "              BASIC_INFO_ID " +
                         "       FROM TRN_CHALLAN AS T " +
                         "       WHERE BASIC_INFO_ID = " + UniqueValue + ") AS T_NEW_SL_NO " +
                         "ON  (TRN_CHALLAN.BASIC_INFO_ID = T_NEW_SL_NO.BASIC_INFO_ID) " +
                         "AND (TRN_CHALLAN.CHALLAN_ID = T_NEW_SL_NO.CHALLAN_ID) " +
                         "SET TRN_CHALLAN.SL_NO = T_NEW_SL_NO.NEW_SL_NO";
            }
            else if (ChlnDed == Updt_SrlNo.DeducteeSrlNo)
            {
                strSQL = "UPDATE TRN_DEDUCTEE_DETAILS " +
                         "INNER  JOIN " +
                         "      (SELECT DCOUNT('DEDUCTEE_DETAIL_ID','TRN_DEDUCTEE_DETAILS','DEDUCTEE_DETAIL_ID <= ' & T.DEDUCTEE_DETAIL_ID & ' and  CHALLAN_ID = " + UniqueValue + "') AS NEW_SL_NO," +
                         "              DEDUCTEE_DETAIL_ID," +
                         "              CHALLAN_ID " +
                         "       FROM TRN_DEDUCTEE_DETAILS AS T " +
                         "       WHERE CHALLAN_ID = " + UniqueValue + ") AS T_NEW_SL_NO " +
                         "ON  (TRN_DEDUCTEE_DETAILS.CHALLAN_ID = T_NEW_SL_NO.CHALLAN_ID) " +
                         "AND (TRN_DEDUCTEE_DETAILS.DEDUCTEE_DETAIL_ID = T_NEW_SL_NO.DEDUCTEE_DETAIL_ID) " +
                         "SET TRN_DEDUCTEE_DETAILS.SL_NO = T_NEW_SL_NO.NEW_SL_NO";
            }
            else if (ChlnDed == Updt_SrlNo.SalaryDetailSrlNo)
            {
                strSQL = "UPDATE TRN_SALARY_DETAILS " +
                         "INNER  JOIN " +
                         "      (SELECT DCOUNT('SALARY_DETAILS_ID','TRN_SALARY_DETAILS','SALARY_DETAILS_ID <= ' & T.SALARY_DETAILS_ID & ' and  BASIC_INFO_ID = " + UniqueValue + "') AS NEW_SL_NO," +
                         "              SALARY_DETAILS_ID," +
                         "              BASIC_INFO_ID " +
                         "       FROM TRN_SALARY_DETAILS AS T " +
                         "       WHERE BASIC_INFO_ID = " + UniqueValue + ") AS T_NEW_SL_NO " +
                         "ON  (TRN_SALARY_DETAILS.BASIC_INFO_ID = T_NEW_SL_NO.BASIC_INFO_ID) " +
                         "AND (TRN_SALARY_DETAILS.SALARY_DETAILS_ID = T_NEW_SL_NO.SALARY_DETAILS_ID) " +
                         "SET TRN_SALARY_DETAILS.SL_NO = T_NEW_SL_NO.NEW_SL_NO";
            }

            if (dmlService.J_ExecSql(Command, strSQL) == false)
                return false;
            else
                return true;
        }
        #endregion
        
