        #region T_LoadLicensedMainForm
        public void T_LoadLicensedMainForm()
        {
            //--
            string strSerial_No = cmnService.J_GetRegistryKeyValue(T_pCompanyName + "\\" + this.GetRegistryFolder(),
                                                                   T_RegistrationInfo.Serial_No.ToString());
            //
            string strReg_Date = cmnService.J_GetRegistryKeyValue(T_pCompanyName + "\\" + this.GetRegistryFolder(),
                                                                               T_RegistrationInfo.Reg_Date.ToString());
            //
            string strActivationNo = cmnService.J_GetRegistryKeyValue(T_pCompanyName + "\\" + this.GetRegistryFolder(),
                                                                   T_RegistrationInfo.Activ_Code.ToString());
            //
            //MessageBox.Show("9.1");    
            if (TDSMAN.T_ClientServerMachine == T_CLIENT_SERVER_MACHINE.CLIENT_MACHINE)
            {
                if (strSerial_No == "")
                {
                    SysRegistration SysRegistration = new SysRegistration();
                    SysRegistration.ShowDialog();
                    return;
                }
                else
                {
                    //--
                    #region SERVER LOCATION
                    if (cmnService.J_IsFileExist(Application.StartupPath + "/" + J_Var.J_pXmlConnectionFileName) == false)
                    {
                        //MessageBox.Show(Application.StartupPath + "/" + J_Var.J_pXmlConnectionFileName);
                        dmlService.Dispose();
                        //cmnService.J_UserMessage("Database file does not exist.\nPlease select the database location", MessageBoxIcon.Exclamation);
                        //--
                        //SysSelectServerDatabase frm = new SysSelectServerDatabase();
                        //frm.ShowDialog();
                        //frm.Dispose();
                        SysServerDisconnected SysServerDisconnected = new SysServerDisconnected();
                        SysServerDisconnected.StartPosition = FormStartPosition.CenterScreen;
                        SysServerDisconnected.ShowDialog();
                        //--
                        return;
                    }
                    //----------------------------------------------------------------------------------
                    if (dmlService.J_ValidateConnection() == false)
                    {
                        //MessageBox.Show("dmlService.J_ValidateConnection");
                        dmlService.Dispose();
                        //cmnService.J_UserMessage("Invalid database.\nPlease check the database", MessageBoxIcon.Exclamation);
                        //--
                        //SysSelectServerDatabase frm = new SysSelectServerDatabase();
                        //frm.ShowDialog();
                        //frm.Dispose();
                        SysServerDisconnected SysServerDisconnected = new SysServerDisconnected();
                        SysServerDisconnected.StartPosition = FormStartPosition.CenterScreen;
                        SysServerDisconnected.ShowDialog();
                        //--
                        return;
                    }
                    //----------------------------------------------------------------------------------
                    if (dmlService.J_IsDatabaseObjectExist("MST_SETUP") == false)
                    {
                        dmlService.Dispose();
                        cmnService.J_UserMessage("Invalid database structure.\nPlease check the database", MessageBoxIcon.Exclamation);
                        //--
                        //SysSelectServerDatabase frm = new SysSelectServerDatabase();
                        //frm.ShowDialog();
                        //frm.Dispose();
                        //--
                        return;
                    }
                    #endregion
                    //--
                    #region XML FILE CONTAINING RANDOM NUMBER
                    //-- GET XML FILE LOCATION
                    DataSet dsXML;
                    dsXML = dmlService.J_ConvertXmlToDataSet(Application.StartupPath + "/" + J_Var.J_pXmlConnectionFileName);
                    if (dsXML == null)
                        return;
                    string XMLFilePath = "";
                    //-- 2021/03/11
                    if (TDSMAN.T_pEditionType == T_EDITION_TYPE.STANDARD_EDITION || 
                        TDSMAN.T_pEditionType == T_EDITION_TYPE.PROFESSIONAL_EDITION ||
                        TDSMAN.T_pEditionType == T_EDITION_TYPE.COMMERCIAL_LAW_HOUSE)
                        XMLFilePath = cmnService.J_Decode(dsXML.Tables[0].Rows[0][cmnService.J_Encode("DATABASENAME")].ToString());
                    else
                        XMLFilePath = cmnService.J_Decode(dsXML.Tables[0].Rows[0][cmnService.J_Encode("SERVERPATH")].ToString());                    
                    //--
                    if (File.Exists(Path.Combine(XMLFilePath, TDSMAN.T_XmlConnectionFileNameServer)))
                    {
                        //-- GET CLIENT'S RANDOM NUMBER FROM REGISTRY
                        string strRandomNumber = cmnService.J_GetRegistryKeyValue(T_pCompanyName + "\\" + T_pPackageName,
                                                                                T_RegistrationInfo.Activ_Code.ToString());
                        //--
                        XmlDocument XMLDoc = new XmlDocument();
                        XMLDoc.Load(Path.Combine(XMLFilePath, TDSMAN.T_XmlConnectionFileNameServer));
                        //
                        XmlNodeList xnList = XMLDoc.GetElementsByTagName(T_XML.NODE);
                        //
                        int i = 0;
                        //
                        foreach (XmlNode xn in xnList)
                        {
                            if (strRandomNumber == cmnService.J_Decode(xn[T_XML.MACHINENO].InnerText))
                                i = i + 1;
                        }
                        //--
                        if (i == 0)
                        {
                            cmnService.J_UserMessage("This machine has been detached from the server.\n To use this machine again, re-register the software with the server.");
                            //-- DELETE REGISTRY DETAILS
                            RegistryKey registryKey = Registry.CurrentUser.OpenSubKey(TDSMAN.T_pCompanyName + "\\" + TDSMAN.T_pPackageName);
                            //
                            if (registryKey != null)
                            {
                                Registry.CurrentUser.DeleteSubKeyTree(TDSMAN.T_pCompanyName + "\\" + TDSMAN.T_pPackageName);
                            }
                            //--
                            return;
                        }
                        //--
                        #region SERVER'S VERSION
                        //-- GET SERVER'S VERSION
                        System.Diagnostics.FileVersionInfo fileVersionInfo = System.Diagnostics.FileVersionInfo.GetVersionInfo(Path.Combine(Application.StartupPath, J_Var.J_pProjectName + ".EXE"));
                        double ClientVersion = Convert.ToDouble(fileVersionInfo.FileMajorPart + "." + fileVersionInfo.FileMinorPart);
                        double ServerVersion = Convert.ToDouble(GetServerVersion());
                        //
                        if (ServerVersion > 0)
                        {
                            if (ClientVersion > ServerVersion)
                            {
                                cmnService.J_UserMessage("SERVER application is of the previous version.\n Kindly update the SERVER application.");
                                return;
                            }
                            else if (ClientVersion < ServerVersion)
                            {
                                if (cmnService.J_UserMessage("This application file is of the previous version.\n Click on 'Yes' to update the file now or click 'No' to exit the software.", MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
                                {
                                    //    //if (File.Exists(Application.StartupPath + "/" + TDSMAN.T_pLoadBeforeUpdaterApplication) == true)
                                    //    if (File.Exists(Path.Combine(Application.StartupPath, "eLicensedUpdateApplication.EXE")) == true)
                                    //    {
                                    //        TDSMAN.MDIExit = true;
                                    //        //
                                    //        //--
                                    //        //Application.Exit();
                                    //        //
                                    //        UtUpdateApplicationUpdate objUpdateUpdaterexe = new UtUpdateApplicationUpdate();
                                    //        objUpdateUpdaterexe.ShowDialog();
                                    //        return;
                                    //    }
                                    //}
                                    //else
                                    //    return;
                                    if (this.T_CheckServerTDSMAN() == true)
                                    {
                                        //checking if the latest updator file exists
                                        if (File.Exists(Path.Combine(Application.StartupPath, TDSMAN.T_pLicensedUpdateApplication)) == false)
                                        {
                                            UtUpdateApplicationUpdate objUpdateUpdaterexe = new UtUpdateApplicationUpdate();
                                            objUpdateUpdaterexe.ShowDialog();
                                        }
                                        else
                                        {
                                            //if file exists

                                            //chekcing the version of the file
                                            FileVersionInfo fileVersionInfoU = FileVersionInfo.GetVersionInfo(Path.Combine(Application.StartupPath, TDSMAN.T_pLicensedUpdateApplication));
                                            double dblUpdatatorexeVersion = Convert.ToDouble(fileVersionInfoU.FileMajorPart + "." + fileVersionInfoU.FileMinorPart);

                                            //now checking the latest update available and downloading the same
                                            if (Registration.Get_Latest_Updater_version(dblUpdatatorexeVersion) == true)
                                            {
                                                UtUpdateApplicationUpdate objUpdateUpdaterexe = new UtUpdateApplicationUpdate();
                                                objUpdateUpdaterexe.ShowDialog();
                                            }
                                        }
                                    }
                                    //--
                                    //Creating a File with Version and Financial Year
                                    StreamWriter writer = new StreamWriter(Path.Combine(Application.StartupPath, "TempUpdate.txt"));

                                    writer.WriteLine(TDSMAN.T_pVersionType.ToString());
                                    writer.WriteLine(TDSMAN.T_pPackageFAYear.ToString());
                                    writer.WriteLine(TDSMAN.T_pEditionType.ToString());
                                    writer.WriteLine(TDSMAN.T_ClientServerMachine.ToString()); //-- ANIK 2015-01-30
                                    writer.WriteLine(System.IntPtr.Size.ToString());           //-- ANIK 2021-02-05

                                    writer.Flush();
                                    writer.Dispose();
                                    writer.Close();
                                    //--
                                    if (File.Exists(Application.StartupPath + "/" + TDSMAN.T_pLicensedUpdateApplication) == true)
                                    {
                                        dmlService.Dispose();
                                        //this.Close();
                                        //this.Dispose();
                                        //J_Var.frmMain.Close();
                                        //J_Var.frmMain.Dispose();
                                        TDSMAN.MDIExit = true;
                                        Application.Exit();
                                        Process.Start(Application.StartupPath + "/" + TDSMAN.T_pLicensedUpdateApplication);
                                    }
                                }
                            }
                        }
                        else
                        {
                            //cmnService.J_UserMessage("Due to some techinical error the server version is not getting accessed.\n Kindly call us on 033-22623535/64596006 for further assistance.");
                            cmnService.J_UserMessage("Due to some techinical error the server version is not getting accessed.\n Kindly call us on 033-22875500/+91-33-40845500/9836490007 for further assistance.");
                            return;
                        }
                        #endregion
                        //--
                        #region SERVER'S EDITION
                        //--
                        TDSMAN.T_pEditionType = cmnService.J_ReturnInt16Value(GetServerEdition()) ;
                        //--
                        #endregion
                    }
                    #endregion
                    //--
                    this.GetMachineID();
                    this.GetSetup();
                    this.SET_TEMP_TABLES();
                    //--   
                    if (Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT PASSWD FROM MST_SETUP WHERE SETUPID =" + TDSMAN.T_MACHINE_ID)) != "")
                    {
                        CmnLogin frm = new CmnLogin();
                        frm.ShowDialog();
                        frm.Dispose();
                        return;
                    }
                    else
                    {
                        J_Var.frmMain = new mdiTDSMAN();
                        J_Var.frmMain.ShowDialog();
                        return;
                    }
                }
            }
            else
            {
                //MessageBox.Show("9.2");    
                //if no value is found in registry then showing registration module
                if (strActivationNo == "")
                {
                    if (TDSMAN.T_pEditionType == T_EDITION_TYPE.COMMERCIAL_LAW_HOUSE)
                    {
                        SysTrialRegistration SysRegistration = new SysTrialRegistration();
                        SysRegistration.ShowDialog();
                    }
                    else
                    {
                        SysRegistration SysRegistration = new SysRegistration();
                        SysRegistration.ShowDialog();
                    }
                    return;
                }
                //
                //MessageBox.Show("9.3");   
                strReg_Date = string.Format("{0:dd/MM/yyyy}", Convert.ToDateTime(strReg_Date));
                //checking the configuration no. of the registered machine
                string strConfigurationNo = T_GenerateConfigNo(strReg_Date);
                //-- verifying if the stored activation number is same as the actual activation num as per configuration number
                if (strActivationNo != T_GenerateActivationNumber(strConfigurationNo, TDSMAN.T_pPackageFAYear.ToString()))
                {
                    //--
                    #region GetConnectedExternalDrives
                    List<string> externalDevices = TDSMAN.GetConnectedExternalDrives();
                    if (externalDevices.Count > 0)
                    {
                        //////Console.WriteLine("External devices detected:");
                        foreach (string device in externalDevices)
                        {
                            Console.WriteLine(device);
                        }
                        // Display warning to user (you may replace this with a UI message box)
                        //////MessageBox.Show(
                        //////    "Please remove any external USB drives or pen drives before proceeding with the update.",
                        //////    "External Drive Detected",
                        //////    MessageBoxButtons.OK,
                        //////    MessageBoxIcon.Warning
                        //////);
                        cmnService.J_UserMessage("It seems you have external Pen Drive/Hard Drive attached.\nPlease remove and start the software again.", MessageBoxIcon.Stop);
                        return;

                        // Exit or pause update logic here
                    }
                    #endregion
                    //MessageBox.Show("9.31");   
                    //-- 2014-06-16 ; ANIK GHOSH ; for config no. variations
                    bool blnAllowDiffHDD = false;
                    //--
                    blnAllowDiffHDD = AllowInstallation(strSerial_No, TDSMAN.T_pPackageFAYear.ToString(), TDSMAN.T_pEditionType, strConfigurationNo);
                    //--
                    //FOR WINDOWS-8 PROBLEM (FLUCTUATING HARD DISK NUMBER)
                    if (strConfigurationNo.IndexOf("TM99") > -1 || GetHardDiskSignatureId().IndexOf("TM99") > -1 || blnAllowDiffHDD == true)
                    {
                        if (Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT PASSWD FROM MST_SETUP WHERE SETUPID =" + TDSMAN.T_MACHINE_ID)) != "")
                        {
                            CmnLogin frm = new CmnLogin();
                            frm.ShowDialog();
                            frm.Dispose();
                        }
                        else
                        {
                            J_Var.frmMain = new mdiTDSMAN();
                            J_Var.frmMain.ShowDialog();
                        }
                        //-- SHREY @ 2014-01-29
                        return;
                    }
                    //--

                    if (TDSMAN.T_pEditionType == T_EDITION_TYPE.COMMERCIAL_LAW_HOUSE)
                    {
                        SysTrialRegistration SysRegistration = new SysTrialRegistration();
                        SysRegistration.ShowDialog();
                    }
                    else
                    {
                        SysRegistration SysRegistration = new SysRegistration();
                        SysRegistration.ShowDialog();
                    }
                    return;
                }
                else
                {
                    //MessageBox.Show("9.32");   
                    if (Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT PASSWD FROM MST_SETUP WHERE SETUPID =" + TDSMAN.T_MACHINE_ID)) != "")
                    {
                        CmnLogin frm = new CmnLogin();
                        frm.ShowDialog();
                        frm.Dispose();
                        return;
                    }
                    else
                    {
                        //MessageBox.Show("9.33");   
                        //
                        J_Var.frmMain = new mdiTDSMAN();
                        //MessageBox.Show("9.34");
                        J_Var.frmMain.ShowDialog();
                        //MessageBox.Show("9.35");  
                        return;
                    }
                }
            }
        }
