        #region T_LoadTrialMainForm
        public void T_LoadTrialMainForm()
        {
            string strTrialVersionRegistryPath = this.GetRegistryFolder() + "(Trial)";
            //
            T_pTrialRandomNumber = cmnService.J_GetRegistryKeyValue(T_pCompanyName + "\\" + strTrialVersionRegistryPath,
                                                                   T_RegistrationInfo.Serial_No.ToString());
            //
            if (T_pTrialRandomNumber == "")
            {
                // FIRST TIME EXE STARTED
                //T_pTrialRunningTime = 0;
                //
                cmnService.J_CreateRegistryKey(T_pCompanyName);
                cmnService.J_CreateRegistryKey(T_pCompanyName, strTrialVersionRegistryPath);
                // SET SERIAL NO
                T_pTrialRandomNumber = T_GenerateRandomNumbers();

                cmnService.J_CreateRegistryKey(T_pCompanyName, strTrialVersionRegistryPath,
                                                T_RegistrationInfo.Serial_No.ToString(), T_pTrialRandomNumber);
