                SysTrialRegistration SysTrialRegistration = new SysTrialRegistration();
                SysTrialRegistration.ShowDialog();
                return;
                //
            }
            else
            {
                // NOT FIRST TIME EXE STARTED
                //T_pTrialRunningTime = 1;
                //
                string strActivationNo = cmnService.J_GetRegistryKeyValue(T_pCompanyName + "\\" + strTrialVersionRegistryPath,
                                                                       T_RegistrationInfo.Activ_Code.ToString());
