                if (strActivationNo == "")
                {
                    //
                    SysTrialRegistration SysTrialRegistration = new SysTrialRegistration();
                    SysTrialRegistration.ShowDialog();
                    return;
                    //
                }
                else
                {
                    //
                    try
                    {
                        if (T_CheckInternetConnectivty() == true)
                        {
                            Registration.Update_Trial_Counter(cmnService.J_ReturnInt32Value(cmnService.J_GetRegistryKeyValue(T_pCompanyName + "\\" + strTrialVersionRegistryPath,
                                                                       T_RegistrationInfo.Activ_Code.ToString())));
                        }
                    }
                    catch
                    {

                    }
                    //
                    //if (T_CheckDatabaseCompatibility() == false)
                    //{
                    //    cmnService.J_UserMessage("Invalid database.\nPlease check the database");
                    //    return;
                    //}
                    //-- 2016/01/20
                    if (Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT PASSWD FROM MST_SETUP WHERE SETUPID =" + TDSMAN.T_MACHINE_ID)) != "")                    
                    {
                        CmnLogin frm = new CmnLogin();
                        frm.ShowDialog();
                        frm.Dispose();
                    }
                    else if (J_Var.J_pLoginScreen == J_LoginScreen.NO)
                    {
                        J_Var.frmMain = new mdiTDSMAN();
                        J_Var.frmMain.ShowDialog();
                    }
                    //
                }
            }

        }
