        #region T_GeneratePassword
        public string T_GeneratePassword(string strCurrentDate)
        {
            //
            char[] charArray = strCurrentDate.ToCharArray();
            Array.Reverse(charArray);
            return new string(charArray);
            //
        }
        #endregion

        #region T_GenerateActivationNumber
        public string T_GenerateActivationNumber(string ConfigurationNumber, string Version)
        {
            try
            {
                string strConfigNo = "";
                string strConfigNoAscii = "";
                    
                
                string strF2Date = "";
                string strDate = "";
                string strL2Date = "";
                string strHDDNo = "";
                string strF2HDD = "";
                string strL2HDD = "";
                // REPLACE "-"
                ConfigurationNumber = ConfigurationNumber.Replace("-", "");
                // DATE CONVERSION
                strDate = cmnService.J_Left(ConfigurationNumber, 4) + cmnService.J_Right(ConfigurationNumber, 4);
                strDate = Convert.ToString(cmnService.J_ReturnInt16Value(cmnService.J_Left(strDate, 2)) +
                                           cmnService.J_ReturnInt16Value(strDate.Substring(2, 2)) +
                                           cmnService.J_ReturnInt16Value(cmnService.J_Right(strDate, 4)));
                strF2Date = cmnService.J_Left(strDate, 2);
                strL2Date = cmnService.J_Right(strDate, 2);
                // HDD CONVERSION
                strHDDNo = ConfigurationNumber.Substring(4, (ConfigurationNumber.Length - 8));
                strF2HDD = cmnService.J_Left(strHDDNo, 2).ToUpper();
                strL2HDD = cmnService.J_Right(strHDDNo, 2).ToUpper();
                //
                strConfigNo = strF2Date + strL2HDD + strF2HDD + strL2Date + Version;
                //
                foreach (char c in strConfigNo)
                {
                    strConfigNoAscii = strConfigNoAscii + (int)(c);
                }

                return strConfigNoAscii;

            }
            catch
            {
                return "";
            }
        }
        #endregion

        #region T_CheckDatabaseCompatibility
        // SHREY [2011-03-25]
        public bool T_CheckDatabaseCompatibility()
        {
            #region LICENSED_VERSION
            if (T_pVersionType == T_VERSION_TYPE.LICENSED_VERSION && T_ClientServerMachine == T_CLIENT_SERVER_MACHINE.SERVER_MACHINE)
            {
                //SELECTTING THE MAXIMUM FA_YEAR IN THE DATABASE

                strSQL = "SELECT TOP 1 FA_YEAR " +
                         "FROM   MST_ASSESSMENT " +
                         "ORDER BY ASST_ID DESC";

                string FinancialYear = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                FinancialYear = cmnService.J_Left(FinancialYear, 2) + cmnService.J_Right(FinancialYear, 2);
                string strEXEFAYear = "20" + T_pPackageFAYear;

                //CHECKING IF THE DATABASE FINANCIAL YEAR IS NOT GREATER THAN THE EXE FINANCIAL YEAR
                if (Convert.ToInt32(strEXEFAYear) < Convert.ToInt32(FinancialYear))
                    return false;
                
                //NOW IF THE FINANCIAL YEAR IS LESS THAN EXE FINANCIAL YEAR 
                //THEN ADDING THE NEW FINANCIAL YEARS IN THE DB

                while (Convert.ToInt32(strEXEFAYear) > Convert.ToInt32(FinancialYear))
                {
                    string strAsstid = "";
                    string strAsstYear = "";
                    string strFaYear = "";
                    string strInputFilePrefix = "";
                    string strStartDateFaYear = "";
                    string strEndDateFaYear = "";
                    string strLastDatePaymentFaYear = "";
                    string strFVUVersion = "";
                    //
                    FinancialYear = Convert.ToString((Convert.ToInt32(FinancialYear) + 1));

                    strAsstYear = FinancialYear + "-" + cmnService.J_Right(Convert.ToString((Convert.ToInt32(FinancialYear) + 1)), 2);
                    strFaYear = Convert.ToString((Convert.ToInt32(FinancialYear) - 1)) + "-" + cmnService.J_Right(FinancialYear, 2);

                    strStartDateFaYear = "01/04/" + Convert.ToString(Convert.ToInt32(FinancialYear) - 1);
                    strEndDateFaYear = "31/03/" + FinancialYear;
                    strLastDatePaymentFaYear = "30/05/" + FinancialYear;

                    strInputFilePrefix = Convert.ToString((char)(Convert.ToInt32(cmnService.J_Right(FinancialYear, 2)) - 8/*A is for FA Year 2007-08*/ + 65));

                    strSQL = " SELECT MAX(ASST_ID) FROM MST_ASSESSMENT";
                    strAsstid = Convert.ToString(Convert.ToInt32(dmlService.J_ExecSqlReturnScalar(strSQL)) + 1);

                    strSQL = @"INSERT INTO MST_ASSESSMENT (
                               ASST_ID, 
                               ASST_YEAR, 
                               FA_YEAR, 
                               START_DATE, 
                               END_DATE, 
                               LAST_DATE_OF_PAYMENT, 
                               FVU_VERSION, 
                               INPUT_FILE_NAME_PREFIX,
                               VISIBILITY_FLAG,
                               VISIBILITY_AADHAAR_RETURN_FLAG,
                               SD_US_16_IA_LIMIT)" + //-- 2019/04/03
                             @" VALUES ( " + strAsstid + "," +
                             " '" + strAsstYear + "'," +
                             " '" + strFaYear + "'," +
                             " " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(strStartDateFaYear) + cmnService.J_DateOperator() + "," +
                             " " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(strEndDateFaYear) + cmnService.J_DateOperator() + "," +
                             " " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(strLastDatePaymentFaYear) + cmnService.J_DateOperator() + "," +
                             " ''," + /* INSERTING FVU_VERSION AS BLANK AS IT WILL BE MODIFIED LATER */
                             " '" + strInputFilePrefix + "', " +
                             "0," + 
                             "1,0)";

                    dmlService.J_ExecSql(strSQL);

                    T_UpdateFVUVersion();
                }
                //--
                strSQL = " UPDATE MST_ASSESSMENT SET VISIBILITY_FLAG = 0";
                dmlService.J_ExecSql(strSQL);
                //-- 2019/04/03
                strSQL = "UPDATE MST_ASSESSMENT SET SD_US_16_IA_LIMIT = 40000 WHERE ASST_ID >= 14";
                dmlService.J_ExecSql(strSQL);
                //-- 2019/06/29
                strSQL = "UPDATE MST_ASSESSMENT SET SD_US_16_IA_LIMIT = 50000 WHERE ASST_ID >= 15";
                dmlService.J_ExecSql(strSQL);
                //-- 2026/06/30
                strSQL = "UPDATE MST_ASSESSMENT SET SD_US_16_IA_LIMIT = 75000 WHERE ASST_ID >= 20";
                dmlService.J_ExecSql(strSQL);
                strSQL = "UPDATE MST_ASSESSMENT SET FLAG_26_27_ONWARDS = 1 WHERE ASST_ID >= 22";
                dmlService.J_ExecSql(strSQL);
            }
            #endregion
            //--
            #region TRIAL_VERSION
            else if (T_pVersionType == T_VERSION_TYPE.TRIAL_VERSION)
            {
                strSQL = "SELECT FA_YEAR FROM MST_ASSESSMENT WHERE ASST_ID = (SELECT MAX(ASST_ID) FROM MST_ASSESSMENT)";
                //
                string FinancialYear = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                FinancialYear = cmnService.J_Left(FinancialYear, 2) + cmnService.J_Right(FinancialYear, 2);
                string strEXEFAYear = "20" + T_pPackageFAYear;

                if (strEXEFAYear == FinancialYear)
                {
                    //NOW MAKING ONLY 1ST 2 FINANCIAL YEAR VISIBLE

                    strSQL = "UPDATE MST_ASSESSMENT SET VISIBILITY_FLAG = 1 WHERE ASST_ID NOT IN (SELECT TOP 2 ASST_ID FROM MST_ASSESSMENT ORDER BY ASST_ID DESC)";
                    dmlService.J_ExecSql(dmlService.J_pCommand, strSQL);
                    //
                    strSQL = "UPDATE MST_ASSESSMENT SET VISIBILITY_FLAG = 0 WHERE ASST_ID IN (SELECT TOP 2 ASST_ID FROM MST_ASSESSMENT ORDER BY ASST_ID DESC)";
                    dmlService.J_ExecSql(dmlService.J_pCommand, strSQL);
                }
                else
                    return false;
            }
            #endregion
            //--
            #region PUBLICATION_HOUSE_VERSION
            else if (T_pVersionType == T_VERSION_TYPE.PUBLICATION_HOUSE_VERSION)
            {
                strSQL = "SELECT FA_YEAR FROM MST_ASSESSMENT WHERE ASST_ID = (SELECT MAX(ASST_ID) FROM MST_ASSESSMENT)";
                //
                string FinancialYear = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                FinancialYear = cmnService.J_Left(FinancialYear, 2) + cmnService.J_Right(FinancialYear, 2);
                string strEXEFAYear = "20" + T_pPackageFAYear;

                if (strEXEFAYear == FinancialYear)
                {
                    //NOW MAKING ONLY 1ST 2 FINANCIAL YEAR VISIBLE

                    strSQL = "UPDATE MST_ASSESSMENT SET VISIBILITY_FLAG = 1 WHERE ASST_ID NOT IN (SELECT TOP 2 ASST_ID FROM MST_ASSESSMENT ORDER BY ASST_ID DESC)";
                    dmlService.J_ExecSql(dmlService.J_pCommand, strSQL);
                    //
                    strSQL = "UPDATE MST_ASSESSMENT SET VISIBILITY_FLAG = 0 WHERE ASST_ID IN (SELECT TOP 2 ASST_ID FROM MST_ASSESSMENT ORDER BY ASST_ID DESC)";
                    dmlService.J_ExecSql(dmlService.J_pCommand, strSQL);
                }
                else
                    return false;
            }
            #endregion
            //--
            return true;

        }

        #endregion

