                dt = cn.GetSchema("tables");
                for (int i = 0; i <= dt.Rows.Count - 1; i++)
                {
                    if ("'" + TableName.Trim().ToUpper() + "$'" == Convert.ToString(dt.Rows[i]["TABLE_NAME"]).Trim().ToUpper())
                    {
                        dt.Dispose();
                        //cn.Dispose();
                        return true;
                    }
                }
