                    && ColumnName.Trim().ToUpper() == Convert.ToString(dt.Rows[i]["COLUMN_NAME"]).Trim().ToUpper())
                    {
                        dt.Dispose();
                        //cn.Dispose();
                        return true;
                    }
                }
            }
