        #region T_IsDatabaseObjectExistConn [2]
        public bool T_IsDatabaseObjectExistConn(string TableName, string ColumnName, string ConnectionString)// OleDbConnection cn)
        {
            DataTable dt;
            OleDbConnection cn = new OleDbConnection(ConnectionString);
            cn.Open();
            //
            if (cn.State == ConnectionState.Closed)
                cn.Open();
            //--
            if (TableName != null && ColumnName == null)
            {
                dt = cn.GetSchema("tables");
                for (int i = 0; i <= dt.Rows.Count - 1; i++)
                {
                    if (TableName.Trim().ToUpper() == Convert.ToString(dt.Rows[i]["TABLE_NAME"]).Trim().ToUpper())
                    {
                        dt.Dispose();
                        //cn.Dispose();
                        return true;
                    }
                }
            }
            else if (TableName != null && ColumnName != null)
            {
                dt = cn.GetSchema("Columns");
                for (int i = 0; i <= dt.Rows.Count - 1; i++)
                {
                    if (TableName.Trim().ToUpper() == Convert.ToString(dt.Rows[i]["TABLE_NAME"]).Trim().ToUpper()
                    && ColumnName.Trim().ToUpper() == Convert.ToString(dt.Rows[i]["COLUMN_NAME"]).Trim().ToUpper())
                    {
                        dt.Dispose();
                        //cn.Dispose();
                        return true;
                    }
                }
                dt.Dispose();
            }
            //
            cn.Dispose();
            return false;
        }
