        #region Is64Bit
        //http://www.dreamincode.net/code/snippet4273.htm
        public bool Is64Bit()
        {
            bool is64 = false;

            //check if the 32 bit program files folder exists
            if (string.IsNullOrEmpty(Environment.GetEnvironmentVariable("ProgramFiles(x86)")))
            {
                //not found so return true
                is64 = true;
            }

            //use Reflection to see if running in 32-bit mode
            if (is64 == false)
            {
                //loop through all the loaded assemblies looking for 64-bit framework
                foreach (Assembly assembly in AppDomain.CurrentDomain.GetAssemblies())
                {
                    //look for the 64-bit framework
                    if (assembly.Location.ToLower().Contains("framework64"))
                    {
                        //found it so must be 64-bit OS
                        is64 = true;
                        break;
                    }

                }
            }
            //made it this far so it's a 32-bit OS
            return is64;
        }
        #endregion

        #region DeleteRegistry
        public void DeleteRegistry()
        {
            // {55AF868E-FDAC-47F5-AABA-3E9E2100134D}
            //
            //TO REMOVE THE UNINSTALL OPTION FROM THE CONTROL PANEL FOR TDSMAN

            RegistryKey registryKey = Registry.LocalMachine.OpenSubKey("SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\{55AF868E-FDAC-47F5-AABA-3E9E2100134D}");
            //
            if (registryKey == null)
            {
                return;
            }
            Registry.LocalMachine.DeleteSubKeyTree("SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\{55AF868E-FDAC-47F5-AABA-3E9E2100134D}");
        }
        #endregion

        #region CreateUninstallRegistry
        public void CreateUninstallRegistry()
        {
            // {55AF868E-FDAC-47F5-AABA-3E9E2100134D}
