            RegistryKey registryKey = Registry.LocalMachine.OpenSubKey("SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\{55AF868E-FDAC-47F5-AABA-3E9E2100134D}");
            //
            if (registryKey != null)
            {
                return;
            }
            Registry.LocalMachine.CreateSubKey("SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\{55AF868E-FDAC-47F5-AABA-3E9E2100134D}");
        }
