        #region GetHardDiskSignatureId
        public string GetHardDiskSignatureId()
        {
            try
            {
                string strHDSignature = "";
                //
                ManagementClass mc = new System.Management.ManagementClass("Win32_DiskDrive");
                ManagementObjectCollection moc = mc.GetInstances();
                //
                foreach (ManagementObject mo in moc)
                {
                    try
                    {
                        strHDSignature = mo["Signature"].ToString().Trim();
                    }
                    catch
                    {
                        strHDSignature = "";
                    }

                    if (strHDSignature == "")
                        continue;
                    else
                        break;
                }

                //Added by Shrey Kejriwal on 01/08/2012
                
                //Checking the length of Hard Disk No as Activation Number is not generated for Hard disk length = 1
                if (strHDSignature.Length == 1)
                {
                    //IF THE HARD DISK NO IS OF SINGLE DIGIT THEN ADDING FEW MORE DIGITS TO IT
                    //strHDSignature = strHDSignature + "TM99";
                    if (strHDSignature == "0")
                        strHDSignature = "TM9999";
                    else
                        //IF THE HARD DISK NO IS OF SINGLE DIGIT THEN ADDING FEW MORE DIGITS TO IT
                        strHDSignature = strHDSignature + "TM99";
                }
                else if (strHDSignature == "")
                {
                    //IF THE HARD DISK SIGNATURE IS BLANK THEN CREATING A CUSTOM HARD DISK NO
                    strHDSignature = "TM9999";
                }
                return strHDSignature;
            }
            catch
            {
                //RETURNING A CUSTOM HARD DISK NO WHERE HARD DISK NO IS NOT CREATED
                return "TM9999";
            }
        }
        #endregion

        #region GetHardDiskSerialNo
        //Added by Anik  on 12/03/2025
        public string GetHardDiskSerialNo()
        {
            string strHDSerialNumber = "";
            try
            {
                //
                ManagementClass mc = new System.Management.ManagementClass("Win32_DiskDrive");
                ManagementObjectCollection moc = mc.GetInstances();
                //
                foreach (ManagementObject mo in moc)
                {
                    try
                    {
                        strHDSerialNumber = mo["SerialNumber"].ToString().Trim();
                        break;
                    }
                    catch
                    {
                        strHDSerialNumber = "";
                    }

                    if (strHDSerialNumber == "")
                        continue;
                    else
                        break;
                }
                return strHDSerialNumber.Replace("-", "").Replace("_", "");
            }
            catch
            {
                //Checking if Hard Disk serial Number returns blank...
                if (strHDSerialNumber.Trim() == "")
                {
                    ProcessStartInfo psi = new ProcessStartInfo
                    {
                        FileName = "powershell",
                        Arguments = "-Command \"Get-PhysicalDisk | Select-Object -ExpandProperty SerialNumber\"",
                        RedirectStandardOutput = true,
                        UseShellExecute = false,
                        CreateNoWindow = true
                    };
                    Process process = new Process { StartInfo = psi };
                    process.Start();
                    //string result = process.StandardOutput.ReadToEnd();
                    string firstSerial = "";
                    while (!process.StandardOutput.EndOfStream)
                    {
                        firstSerial = process.StandardOutput.ReadLine().Trim();
                        if (!string.IsNullOrEmpty(firstSerial))
                            break;
                    }
                    process.WaitForExit();
                    //
                    strHDSerialNumber = firstSerial.Trim();
                }
                return strHDSerialNumber.Replace("-", "").Replace("_", "");
            }
            //}
            //catch
            //{
            //    //RETURNING A CUSTOM HARD DISK NO WHERE HARD DISK NO IS NOT CREATED
            //    return "TM9999";
            //}
        }
        #endregion

        #region J_IsApplicationOpen
        public static Process J_IsApplicationOpen()
        // Returns a System.Diagnostics.Process pointing to
        // a pre-existing process with the same name as the
        // current one, if any; or null if the current process
        // is unique.
        {
            Process curr = Process.GetCurrentProcess();
            Process[] procs = Process.GetProcessesByName(curr.ProcessName);
            foreach (Process p in procs)
            {
                if ((p.Id != curr.Id) &&
                (p.MainModule.FileName == curr.MainModule.FileName))
                {
                    return p;
                    //p.Start();
                }
            }
            return null;
        }
        #endregion

