        #region T_GetUninstallCode()
        public string T_GetUninstallCode()
        {
            string T_pCompanyName = "PDS Infotech";
            //
            string strReg_Date = cmnService.J_GetRegistryKeyValue(T_pCompanyName + "\\" + this.GetRegistryFolder(),
                                                                           T_RegistrationInfo.Reg_Date.ToString());

            string strActivationNo = cmnService.J_GetRegistryKeyValue(T_pCompanyName + "\\" + this.GetRegistryFolder(),
                                                                   T_RegistrationInfo.Activ_Code.ToString());

            if (strReg_Date != "" && strActivationNo != "")
            {
                //
                string strConfigurationNo = T_GenerateConfigNo(strReg_Date);
                //
                return T_GenerateUninstallCode(strConfigurationNo, TDSMAN.T_pPackageFAYear.ToString());
            }
            //
            return "";
        }
        #endregion

        #region T_GenerateUninstallCode
        private string T_GenerateUninstallCode(string ConfigurationNumber, string Version)
        {
            try
            {
                string strF2Date = "";
                string strDate = "";
                string strL2Date = "";
                string strHDDNo = "";
                string strF2HDD = "";
                string strL2HDD = "";
                string strConfigNo = "";
                string strConfigNoAscii = "";
                // REPLACE "-"
                ConfigurationNumber = ConfigurationNumber.Replace("-", "");
                // DATE CONVERSION
                strDate = cmnService.J_Left(ConfigurationNumber, 4) + cmnService.J_Right(ConfigurationNumber, 4);
                strDate = Convert.ToString(Convert.ToInt16(cmnService.J_Left(strDate, 2)) +
                                           Convert.ToInt16(strDate.Substring(2, 2)) +
                                           Convert.ToInt16(cmnService.J_Right(strDate, 4)));
                strF2Date = cmnService.J_Left(strDate, 2);
                strL2Date = cmnService.J_Right(strDate, 2);
                // HDD CONVERSION
                strHDDNo = ConfigurationNumber.Substring(4, (ConfigurationNumber.Length - 8));
                strF2HDD = cmnService.J_Left(strHDDNo, 2).ToUpper();
                strL2HDD = cmnService.J_Right(strHDDNo, 2).ToUpper();
                //
                strConfigNo = strF2Date + strL2HDD + strF2HDD + strL2Date + Version;
                //
                int int1 = 0;
                //
                foreach (char c in strConfigNo)
                {
                    int1 = 0;
                    int1 = ((int)(c)) + 1;
                    strConfigNoAscii = strConfigNoAscii + int1;
                }
                return strConfigNoAscii;
            }
            catch
            {
                return "";
            }
        }
        #endregion

