        #region GetRegistryFolder
        public string GetRegistryFolder()
        {
            string strEditionSuffix = "";
            if (TDSMAN.T_ClientServerMachine != T_CLIENT_SERVER_MACHINE.CLIENT_MACHINE)
            {
                if (TDSMAN.T_pEditionType == T_EDITION_TYPE.PROFESSIONAL_EDITION)
                    strEditionSuffix = "_Pro";
                else if(TDSMAN.T_pEditionType == T_EDITION_TYPE.COMMERCIAL_LAW_HOUSE) //-- 2022/04/11
                    strEditionSuffix = "_Clh";
                else if (TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_EDITION) //-- 2016/01/29
                    strEditionSuffix = "_Ent";
                else if (TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_LITE_EDITION) //-- 2021/01/13
                    strEditionSuffix = "_Ent_lite";
                else if (TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_ULTIMATE_EDITION) //-- 2024/06/06
                    strEditionSuffix = "_Ent_ulti";
            }
            //-- 2015/06/26
            if (TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_EDITION) //-- 2016/01/29
                strEditionSuffix = "_Ent";
            if (TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_LITE_EDITION) //-- 2021/01/13
