                }
                else if (TDSMAN.T_pPackageFAYear == (int)Software_Version.FY2024_25) //-- 2025/02/05
                {
                    T_pPackageName = "TDSMAN" + strEditionSuffix + "(2025-26)";
                }
                else if (TDSMAN.T_pPackageFAYear == (int)Software_Version.FY2025_26) //-- 2026/01/28
                {
                    T_pPackageName = "TDSMAN" + strEditionSuffix + "(2026-27)";
                }
            }
            //--------------------------------------------------
            if (TDSMAN.T_PackageType == T_PACKAGE_TYPE.MULTI_USER)
            {
                if (TDSMAN.T_ClientServerMachine == T_CLIENT_SERVER_MACHINE.CLIENT_MACHINE && cmnService.J_Right(T_pPackageName, 6) != "(Client)")
                    T_pPackageName = T_pPackageName + "(Client)";
                //else if (TDSMAN.T_ClientServerMachine == T_CLIENT_SERVER_MACHINE.SERVER_MACHINE && cmnService.J_Right(T_pPackageName, 6) != "(Server)")
                //    T_pPackageName = T_pPackageName + "(Server)";
            }
            //else if (TDSMAN.T_PackageType == T_PACKAGE_TYPE.SINGLE_USER)
            //{
            //    if (TDSMAN.T_pEditionType == T_EDITION_TYPE.STANDARD_EDITION && cmnService.J_Right(T_pPackageName, 10) != "(Standard)")
            //        T_pPackageName = T_pPackageName + "(Standard)";
            //}
            //----------------------------------------------------  
            if (T_pPackageName.Length > 0)
                return T_pPackageName;
            else
                return "";
        }
