        #region CalculateIncomeTaxAmount
        //Added by Shrey on 30/08/2014
        public double CalculateIncomeTaxAmount_20231121(int AsstId,
                                                string Category,
                                                double TaxableAmount,
                                                string Section115BAC,
                                                out double ECess,
                                                out double Surcharge,
                                                out double TaxCredit,
                                                out double TaxonTotalIncomeB4TaxCredit)
        {

            //INITIALIZE OUT PARAMETERS
            ECess = 0;
            Surcharge = 0;
            TaxCredit = 0;
            TaxonTotalIncomeB4TaxCredit = 0;

            //Not calculating tax for zero income
            if (TaxableAmount <= 0)
                return 0;

            //-- 2020/07/01
            int intSection115BAC = 0;
            if (Section115BAC.ToUpper().ToString() == T_TRUE_FALSE.TRUE.ToString().ToUpper() || Section115BAC == T_YES_NO.YES || Section115BAC == "1")
            {
                intSection115BAC = 1;                
            }

            //DECLARE AND INITIALIZE VARIABLE
            //double dblTaxonTotalIncomeB4TaxCredit = 0;
            double dblTaxonTotalIncome = 0;
            double dblSlabTaxAmtOnTotalIncome = 0;
            double dblAmtDifference = 0;
            double dblEduCessRate = 0;
            double dblCalculateTaxCreditAmt = 0;
            //-- 2015/03/27
            double dblECessRate = 1;
            double dblHigherECessRate = 2;

            //VARIABLE DECLARATION FOR SURCHARGE CALCULATION 
            double dblSurchargeLimitAmount1Cr = 10000000.00;
            double dblSurchargeLimitAmount50L = 5000000.00;
            //-- 2020/05/25
            double dblSurchargeLimitAmount2Cr = 20000000.00;
            double dblSurchargeLimitAmount5Cr = 50000000.00;
            double dblSurchargeLimitAmountExceeds5Cr = 50000000.00;
            //
            double dblExcedAmount = 0.00;
            double dblSurchargeOnTaxAmount = 0.00;
            double dblExcessCalculatedTax = 0.00;
            double dblNetAmount = 0.00;
            double dblTaxRate = 0.00;
            double dblSurchargeRate = 0.10;
            //-------------------------------------------------
            try
            {
                // Steps of Calculation
                // Creating Temporary Table with all Slab rates
                // Storing Tax amounts in Temp table Slab wise
                // Tax Credit calculation
                // Surcharge calculation
                // E cess Calculation

                #region Storing Slab wise Tax in Temporary Table
                //
                dmlService.J_BeginTransaction();
                if (dmlService.J_IsDatabaseObjectExist(TDSMAN.T_tblTEMP_TAX_SLAB_SUMMARY) == true)
                {
                    //DROP TEMPORARY TABLE FOR TAX CALCULATION 
                    strSQL = "DROP TABLE " + TDSMAN.T_tblTEMP_TAX_SLAB_SUMMARY + "";
                    //MessageBox.Show(strSQL);
                    dmlService.J_ExecSql(strSQL);
                }
                //--
                //TEMP TABLE TO STORE SLAB WISE CALCULATED TAX AMOUNT
                //strSQL = "CREATE TABLE " + TDSMAN.T_tblTEMP_TAX_SLAB_SUMMARY + "(" +
                //             "              INCOME_FROM             MONEY  DEFAULT 0, " +
                //             "              INCOME_TO               MONEY  DEFAULT 0, " +
                //             "              TAX_RATE                MONEY  DEFAULT 0, " +
                //             "              SLAB_WISE_TAX_AMOUNT    MONEY  DEFAULT 0, " +
                //             "              EDUCATION_CESS_RATE     MONEY  DEFAULT 0, " +
                //             "              EDUCATION_CESS_AMOUNT   MONEY  DEFAULT 0, " +
                //             "              TAX_CREDIT_RATE         MONEY  DEFAULT 0, " +
                //             "              TAX_CREDIT_MAX_LIMIT    MONEY  DEFAULT 0, " +
                //             "              TAX_CREDIT_AMOUNT       MONEY  DEFAULT 0, " +
                //             "              SURCHARGE_AMOUNT        MONEY  DEFAULT 0) ";
                //--
                strSQL = "CREATE TABLE " + TDSMAN.T_tblTEMP_TAX_SLAB_SUMMARY + "(" +
                             "         " + cmnService.J_GetDataType("INCOME_FROM", J_ColumnType.Double) + "," +
                             "         " + cmnService.J_GetDataType("INCOME_TO", J_ColumnType.Double) + "," +
                             "         " + cmnService.J_GetDataType("TAX_RATE", J_ColumnType.Double) + "," +
                             "         " + cmnService.J_GetDataType("SLAB_WISE_TAX_AMOUNT", J_ColumnType.Double) + "," +
                             "         " + cmnService.J_GetDataType("EDUCATION_CESS_RATE", J_ColumnType.Double) + "," +
                             "         " + cmnService.J_GetDataType("EDUCATION_CESS_AMOUNT", J_ColumnType.Double) + "," +
                             "         " + cmnService.J_GetDataType("TAX_CREDIT_RATE", J_ColumnType.Double) + "," +
                             "         " + cmnService.J_GetDataType("TAX_CREDIT_MAX_LIMIT", J_ColumnType.Double) + "," +
                             "         " + cmnService.J_GetDataType("TAX_CREDIT_AMOUNT", J_ColumnType.Double) + "," +
                             "         " + cmnService.J_GetDataType("SURCHARGE_AMOUNT", J_ColumnType.Double) + ") ";

                dmlService.J_ExecSql(strSQL);
                //MessageBox.Show(strSQL);
                //--
                strSQL = "DELETE FROM " + TDSMAN.T_tblTEMP_TAX_SLAB_SUMMARY + "";
                dmlService.J_ExecSql(strSQL);
                //MessageBox.Show(strSQL);
                //--
                dmlService.J_Commit();
                //--
                //NOW SELECTING APPLICABLE SLABS BASED ON
                //1. INCOME, 2. CATEGORY, 3. ASSESSMENT YEAR
                strSQL = @"SELECT INCOME_FROM, 
                                  INCOME_TO,
                                  TAX_RATE,
                                  EDUCATION_CESS_RATE,
                                  TAX_CREDIT_RATE,
                                  SECTION_115BAC_MARGINAL_RELIEF
                           FROM   MST_INCOME_TAX_SLAB 
                           WHERE  MST_INCOME_TAX_SLAB.CATEGORY   = '" + Category + "' " +
                         @"AND   MST_INCOME_TAX_SLAB.ASST_ID     =  " + AsstId + " " +
                         @"AND   MST_INCOME_TAX_SLAB.INCOME_FROM <  " + TaxableAmount + " " +
                         @"AND   MST_INCOME_TAX_SLAB.SECTION_115BAC_FLAG = " + intSection115BAC + " " + //-- 2020/07/01
                         @"ORDER BY TAX_SLAB_ID";

                DataSet ds;
                ds = dmlService.J_ExecSqlReturnDataSet(strSQL);
                //MessageBox.Show(strSQL);
                // Returning zero Incase no slab is found for the given parameters
                // Possible when category or assessment year is not provided
                if (ds == null || ds.Tables[0].Rows.Count == 0)
                    return 0;

                // Calculating the Tax amount based on each slab rate 
                for (int i = 1; i <= ds.Tables[0].Rows.Count; i++)
                {
                    // Taking the amount on which the current tax will be calculated

                    if (Convert.ToDouble(TaxableAmount) > Convert.ToDouble(ds.Tables[0].Rows[i - 1]["INCOME_TO"]))
                    {
                        // Incase the amount is more than the To Amount of current slab 
                        // then Tax will be calculated on entire bracket (To amount - From amount)
                        dblAmtDifference = Convert.ToDouble(ds.Tables[0].Rows[i - 1]["INCOME_TO"]) - Convert.ToDouble(ds.Tables[0].Rows[i - 1]["INCOME_FROM"]);
                    }
                    else
                    {
                        // Incase the amount is less than the To Amount of current slab 
                        // then Tax will be calculated only on the amount exceeding from amount
                        dblAmtDifference = Convert.ToDouble(TaxableAmount) - Convert.ToDouble(ds.Tables[0].Rows[i - 1]["INCOME_FROM"]);
                    }

                    //Tax on current slab
                    dblSlabTaxAmtOnTotalIncome = Math.Round((dblAmtDifference * Convert.ToDouble(ds.Tables[0].Rows[i - 1]["TAX_RATE"]) / 100), 0, MidpointRounding.AwayFromZero);

                    //Cumulative Tax
                    dblTaxonTotalIncome = dblTaxonTotalIncome + dblSlabTaxAmtOnTotalIncome;

                    // Inserting current slab along with its tax rate in temporary table
                    strSQL = "INSERT INTO " + TDSMAN.T_tblTEMP_TAX_SLAB_SUMMARY + "( " +
                             "       INCOME_FROM, " +
                             "       INCOME_TO, " +
                             "       TAX_RATE, " +
                             "       SLAB_WISE_TAX_AMOUNT) " +
                             "VALUES(" + Convert.ToDouble(ds.Tables[0].Rows[i - 1]["INCOME_FROM"]) + "," +
                             "       " + Convert.ToDouble(ds.Tables[0].Rows[i - 1]["INCOME_TO"]) + "," +
                             "       " + Convert.ToDouble(ds.Tables[0].Rows[i - 1]["TAX_RATE"]) + "," +
                             "       " + Convert.ToDouble(dblSlabTaxAmtOnTotalIncome) + " )";
                    dmlService.J_ExecSql(dmlService.J_pCommand, strSQL);
                }

                TaxonTotalIncomeB4TaxCredit = dblTaxonTotalIncome;

                #endregion

                #region TAX CREDIT CALCULATION

                // Getting amount of Tax Credit as per the applicable slab selected.
                dblCalculateTaxCreditAmt = Convert.ToDouble(ds.Tables[0].Rows[ds.Tables[0].Rows.Count - 1]["TAX_CREDIT_RATE"]);

                // Deducting Tax Credit from the Cumulative tax
                dblTaxonTotalIncome = dblTaxonTotalIncome - dblCalculateTaxCreditAmt;
                //--
                ////////if (dblCalculateTaxCreditAmt > TaxonTotalIncomeB4TaxCredit)
                ////////    TaxonTotalIncomeB4TaxCredit = 0;
                //Out parameter
                TaxCredit = dblCalculateTaxCreditAmt;
                ////-- 2023/11/20
                //TaxonTotalIncomeB4TaxCredit = TaxCredit;

                #endregion

                #region SURCHARGE CALCULATION

                // Applicable Financial Year 2013-14 onwards.
                if (AsstId >= T_FinancialYearID.F2013_14ID)
                {
                    if (AsstId >= T_FinancialYearID.F2017_18ID)
                    {
                        double dblSurchargeLimitAmount = 0;
                        bool blSurcharge = false;
                        //--
                        //if (TaxableAmount > dblSurchargeLimitAmount50L)
                        if (TaxableAmount > dblSurchargeLimitAmount50L && TaxableAmount <= dblSurchargeLimitAmount1Cr) //-- 2017/11/21
                        {
                            blSurcharge = true;
                            dblSurchargeLimitAmount = dblSurchargeLimitAmount50L;
                            dblSurchargeRate = 0.10;
                        }
                        else if (TaxableAmount > dblSurchargeLimitAmount1Cr)
                        {
                            blSurcharge = true;
                            dblSurchargeLimitAmount = dblSurchargeLimitAmount1Cr;
                            dblSurchargeRate = 0.15;
                        }
                        //-- 2020/05/26
                        if (AsstId >= T_FinancialYearID.F2019_20ID)
                        {
                            if (TaxableAmount > dblSurchargeLimitAmount2Cr && TaxableAmount <= dblSurchargeLimitAmount5Cr)
                            {
                                blSurcharge = true;
                                //dblSurchargeLimitAmount = dblSurchargeLimitAmount5Cr;
                                dblSurchargeLimitAmount = dblSurchargeLimitAmount2Cr;
                                dblSurchargeRate = 0.25;
                            }
                            else if (TaxableAmount > dblSurchargeLimitAmount5Cr)
                            {
                                blSurcharge = true;
                                dblSurchargeLimitAmount = dblSurchargeLimitAmount5Cr;
                                dblSurchargeRate = 0.37;
                            }
                        }
                        //--
                        if (blSurcharge == true)
                        {
                            double dblTaxOn1Cr = 0,dblTaxOn2Cr = 0,dblTaxOn5Cr = 0,dblTaxOn10Cr = 0;
                            //--
                            double dblSurchargeRate50L = 0.1, dblSurchargeRate1Cr = 0.15, dblSurchargeRate2Cr = 0.25, dblSurchargeRate5Cr = 0.37;//, dblSurchargeRate10Cr = 0;
                            //--
                            ////-- MARGINAL INCREASE FROM 2CR
                            if (intSection115BAC == 1)
                            {
                                dblTaxOn1Cr = 2737500;
                                dblTaxOn2Cr = 5737500;
                                dblTaxOn5Cr = 14737500;
                            }
                            else
                            {
                                if (Category == "S")
                                {
                                    dblTaxOn1Cr = 2810000;
                                    dblTaxOn2Cr = 5810000;
                                    dblTaxOn5Cr = 14810000;
                                }
                                else if (Category == "O")
                                {
                                    dblTaxOn1Cr = 2800000;
                                    dblTaxOn2Cr = 5800000;
                                    dblTaxOn5Cr = 14800000;
                                }
                                else
                                {
                                    dblTaxOn1Cr = 2812500;
                                    dblTaxOn2Cr = 5812500;
                                    dblTaxOn5Cr = 14812500;
                                }
                            }
                            //--
                            if (TaxableAmount > dblSurchargeLimitAmount5Cr)
                            {
                                //################################################
                                double dblSurchargeOn1Cr = Math.Round((dblTaxOn1Cr * dblSurchargeRate50L), 0, MidpointRounding.AwayFromZero);
                                //--
                                double dblSurchargeOn2Cr = Math.Round((dblTaxOn2Cr * dblSurchargeRate1Cr), 0, MidpointRounding.AwayFromZero);
                                //--
                                double dblSurchargeOn5Cr = Math.Round((dblTaxOn5Cr * dblSurchargeRate2Cr), 0, MidpointRounding.AwayFromZero);
                                //--
                                double dblAmountExceed5Cr = TaxableAmount - dblSurchargeLimitAmount5Cr;
                                //
                                double dblTaxExceedAmount = Math.Round((0.3 * dblAmountExceed5Cr), 0, MidpointRounding.AwayFromZero);
                                //
                                double dblExpectedSurchargeOnTaxAmount5Cr = Math.Round((dblSurchargeRate * (dblTaxExceedAmount + dblTaxOn5Cr)), 0, MidpointRounding.AwayFromZero);
                                //
                                double dblTotalExpectedTax = dblExpectedSurchargeOnTaxAmount5Cr + dblTaxonTotalIncome;
                                //###############################################################################
                                double dblDiffPrevSlab = (dblTaxonTotalIncome + dblExpectedSurchargeOnTaxAmount5Cr) - ((dblTaxOn5Cr + dblSurchargeOn5Cr));
                                //// -----------------------------------------------
                                if (dblDiffPrevSlab > dblAmountExceed5Cr)
                                    Surcharge = dblExpectedSurchargeOnTaxAmount5Cr - (dblDiffPrevSlab - dblAmountExceed5Cr);
                                else
                                    Surcharge = Math.Round((dblSurchargeRate * dblTaxonTotalIncome), 0, MidpointRounding.AwayFromZero);
                            }
                            else if (TaxableAmount > dblSurchargeLimitAmount2Cr)
                            {
                                //################################################
                                double dblSurchargeOn1Cr = Math.Round((dblTaxOn1Cr * dblSurchargeRate50L), 0, MidpointRounding.AwayFromZero);
                                //--
                                double dblSurchargeOn2Cr = Math.Round((dblTaxOn2Cr * dblSurchargeRate1Cr), 0, MidpointRounding.AwayFromZero);
                                //
                                double dblAmountExceed2Cr = TaxableAmount - dblSurchargeLimitAmount2Cr;
                                //
                                double dblTaxExceedAmount = Math.Round((0.3 * dblAmountExceed2Cr), 0, MidpointRounding.AwayFromZero);
                                //
                                double dblExpectedSurchargeOnTaxAmount2Cr = Math.Round((dblSurchargeRate * (dblTaxExceedAmount + dblTaxOn2Cr)), 0, MidpointRounding.AwayFromZero);
                                //
                                double dblTotalExpectedTax = dblExpectedSurchargeOnTaxAmount2Cr + dblTaxonTotalIncome;
                                //###############################################################################
                                double dblDiffPrevSlab = (dblTaxonTotalIncome + dblExpectedSurchargeOnTaxAmount2Cr) -((dblTaxOn2Cr + dblSurchargeOn2Cr));
                                //// -----------------------------------------------
                                if (dblDiffPrevSlab > dblAmountExceed2Cr)   
                                    Surcharge = dblExpectedSurchargeOnTaxAmount2Cr - (dblDiffPrevSlab - dblAmountExceed2Cr);
                                else
                                    Surcharge = Math.Round((dblSurchargeRate * dblTaxonTotalIncome), 0, MidpointRounding.AwayFromZero);

                            }
                            else if (TaxableAmount > dblSurchargeLimitAmount1Cr)
                            {
                                //################################################                                
                                double dblSurchargeOn1Cr = Math.Round((dblTaxOn1Cr * dblSurchargeRate50L), 0, MidpointRounding.AwayFromZero);
                                //
                                double dblAmountExceed1Cr = TaxableAmount - dblSurchargeLimitAmount1Cr;
                                //
                                double dblTaxExceedAmount = Math.Round((0.3 * dblAmountExceed1Cr), 0, MidpointRounding.AwayFromZero);
                                //
                                double dblExpectedSurchargeOnTaxAmount1Cr = Math.Round((dblSurchargeRate * (dblTaxExceedAmount + dblTaxOn1Cr)), 0, MidpointRounding.AwayFromZero);
                                //
                                double dblTotalExpectedTax = dblExpectedSurchargeOnTaxAmount1Cr + dblTaxonTotalIncome;
                                //###############################################################################
                                double dblDiffPrevSlab =(dblTaxonTotalIncome + dblExpectedSurchargeOnTaxAmount1Cr) - (dblTaxOn1Cr + dblSurchargeOn1Cr);
                                //// -----------------------------------------------
                                if(dblDiffPrevSlab > dblAmountExceed1Cr)
                                    Surcharge = dblExpectedSurchargeOnTaxAmount1Cr - (dblDiffPrevSlab - dblAmountExceed1Cr);
                                else
                                    Surcharge = Math.Round((dblSurchargeRate * dblTaxonTotalIncome), 0, MidpointRounding.AwayFromZero);
                            }
                            else
                            {
                                dblSurchargeOnTaxAmount = Math.Round((dblSurchargeRate * dblTaxonTotalIncome), 0, MidpointRounding.AwayFromZero);
                                // -----------------------------------------------
                                // Amount Exceeding 1 crore (Surcharge Limit Amount)
                                dblExcedAmount = TaxableAmount - dblSurchargeLimitAmount;
                                // Tax rate on income above 1 crore as per slab
                                dblTaxRate = Convert.ToDouble(ds.Tables[0].Rows[ds.Tables[0].Rows.Count - 1]["TAX_RATE"]);
                                // Tax Already charged on income Exceeding 1 crore
                                dblExcessCalculatedTax = Math.Round(((dblTaxRate / 100) * dblExcedAmount), 0, MidpointRounding.AwayFromZero);
                                //Net Exceeding amount 
                                dblNetAmount = dblExcedAmount - dblExcessCalculatedTax;
                                // -----------------------------------------------
                                // Surcharge will be minimum value of Amount Exceeding or Surcharge calculation
                                if (dblNetAmount >= dblSurchargeOnTaxAmount)
                                    Surcharge = dblSurchargeOnTaxAmount;
                                else
                                    Surcharge = dblNetAmount;
                            }
                        }
                    }
                    else
                    {
                        if (TaxableAmount > dblSurchargeLimitAmount1Cr)
                        {
                            //-- ANIK @ 2015/04/18
                            if (AsstId >= T_FinancialYearID.F2015_16ID)
                            {
                                if (AsstId >= T_FinancialYearID.F2016_17ID) //-- 2016/04/25.
                                {
                                    dblSurchargeRate = 0.15;
                                }
                                else
                                    dblSurchargeRate = 0.12;
                            }
                            // Surcharge = 10 % of Tax & cannot exceed Amount Exceeding 1 crore

                            // -----------------------------------------------
                            // -- Calculating Surcharge on Tax
                            // -----------------------------------------------
                            //dblSurchargeOnTaxAmount = Math.Round((0.10 * dblTaxonTotalIncome), 0);
                            //-- ANIK @ 2015/04/18
                            dblSurchargeOnTaxAmount = Math.Round((dblSurchargeRate * dblTaxonTotalIncome), 0, MidpointRounding.AwayFromZero);
                            // -----------------------------------------------
                            // -----------------------------------------------
                            // -- Calculating Amount Exceeding 1 crore
                            // -----------------------------------------------
                            // Amount Exceeding 1 crore (Surcharge Limit Amount)
                            dblExcedAmount = TaxableAmount - dblSurchargeLimitAmount1Cr;

                            // Tax rate on income above 1 crore as per slab
                            dblTaxRate = Convert.ToDouble(ds.Tables[0].Rows[ds.Tables[0].Rows.Count - 1]["TAX_RATE"]);

                            // Tax Already charged on income Exceeding 1 crore
                            dblExcessCalculatedTax = Math.Round(((dblTaxRate / 100) * dblExcedAmount), 0, MidpointRounding.AwayFromZero);

                            //Net Exceeding amount 
                            dblNetAmount = dblExcedAmount - dblExcessCalculatedTax;

                            // -----------------------------------------------

                            // Surcharge will be minimum value of Amount Exceeding or Surcharge calculation

                            if (dblNetAmount >= dblSurchargeOnTaxAmount)
                                Surcharge = dblSurchargeOnTaxAmount;
                            else
                                Surcharge = dblNetAmount;
                        }
                    }
                }
                //-----------------------------------------------------------
                //-----------------------------------------------------------
                #endregion

                #region EDUCATIONAL CESS CALCULATION

                //Getting Applicable Cess rate
                //dblEduCessRate = Convert.ToDouble(ds.Tables[0].Rows[ds.Tables[0].Rows.Count - 1]["EDUCATION_CESS_RATE"]); //-- 2015/03/27

                //ECess = Math.Round((dblTaxonTotalIncome + Surcharge) * dblEduCessRate / 100);
                //ECess = Math.Round((dblTaxonTotalIncome + Surcharge) * dblHigherECessRate / 100, 0, MidpointRounding.AwayFromZero);
                //ECess = ECess + Math.Round((dblTaxonTotalIncome + Surcharge) * dblECessRate / 100, 0, MidpointRounding.AwayFromZero);
                //-- 2018/06/07
                if (AsstId >= T_FinancialYearID.F2018_19ID)
                {
                    dblECessRate = 4;
                    ECess = Math.Round((dblTaxonTotalIncome + Surcharge) * dblECessRate / 100, 0, MidpointRounding.AwayFromZero); //-- 2018/06/07
                }
                else
                {
                    //dblECessRate = 3; dblHigherECessRate = 1;
                    ECess = Math.Round((dblTaxonTotalIncome + Surcharge) * dblHigherECessRate / 100, 0, MidpointRounding.AwayFromZero); //-- 2018/05/18
                    ECess = ECess + Math.Round((dblTaxonTotalIncome + Surcharge) * dblECessRate / 100, 0, MidpointRounding.AwayFromZero); //-- 2018/05/18
                }
                //
                //ECess = Math.Round(ECess, 0, MidpointRounding.AwayFromZero); //-- 2018/05/18
                if (ECess < 0)
                    ECess = 0;
                #endregion

                #region Updating Surcharge, Cess in temp Table and adding other slabs

                // Now updating tax credit, Surcharge & Cess amount in Temporary table 
                strSQL = "UPDATE " + TDSMAN.T_tblTEMP_TAX_SLAB_SUMMARY + " " +
                         "SET SURCHARGE_AMOUNT       = " + Surcharge + ", " +
                         "    EDUCATION_CESS_AMOUNT  = " + ECess + ", " +
                         "    TAX_CREDIT_AMOUNT      = " + dblCalculateTaxCreditAmt;

                dmlService.J_ExecSql(strSQL);

                // Adding left over slabs in Temp Table
                strSQL = @"INSERT INTO " + TDSMAN.T_tblTEMP_TAX_SLAB_SUMMARY + "( " +
                          "       INCOME_FROM, " +
                          "       INCOME_TO, " +
                          "       TAX_RATE, " +
                          "       EDUCATION_CESS_RATE) " +
                          "SELECT INCOME_FROM, " +
                          "       INCOME_TO, " +
                          "       TAX_RATE, " +
                          "       EDUCATION_CESS_RATE " +
                          "FROM   MST_INCOME_TAX_SLAB " +
                          "WHERE  MST_INCOME_TAX_SLAB.CATEGORY    = '" + Category + "' " +
                          "AND   MST_INCOME_TAX_SLAB.ASST_ID      =  " + AsstId + " " +
                          "AND   MST_INCOME_TAX_SLAB.INCOME_FROM >=  " + TaxableAmount + " " + 
                          "AND   MST_INCOME_TAX_SLAB.SECTION_115BAC_FLAG = " + intSection115BAC + " " + //-- 2020/07/01

       dmlService.J_ExecSql(strSQL);

                #endregion

                return dblTaxonTotalIncome;
            }
            catch (Exception err)
            {
                cmnService.J_UserMessage(err.Message);
                return 0;
            }
        }

