        #region CalculateIncomeTaxAmount
        //27/04/2024
        public double CalculateIncomeTaxAmount(int AsstId,
                                                string Category,
                                                double TaxableAmount,
                                                string Section115BAC,
                                                out double ECess,
                                                out double Surcharge,
                                                out double TaxCredit,
                                                out double TaxonTotalIncomeB4TaxCredit)
        {

            //INITIALIZE OUT PARAMETERS
            ECess = 0;
            Surcharge = 0;
            TaxCredit = 0;
            TaxonTotalIncomeB4TaxCredit = 0;


            //Not calculating tax for zero income
            if (TaxableAmount <= 0)
                return 0;

            //-- 2020/07/01
            int intSection115BAC = 0;
            if (Section115BAC.ToUpper().ToString() == T_TRUE_FALSE.TRUE.ToString().ToUpper() || Section115BAC == T_YES_NO.YES || Section115BAC == "1")
            {
                intSection115BAC = 1;
            }

            //DECLARE AND INITIALIZE VARIABLE
            //double dblTaxonTotalIncomeB4TaxCredit = 0;
            double dblTaxonTotalIncome = 0;
            double dblSlabTaxAmtOnTotalIncome = 0;
            double dblAmtDifference = 0;
            double dblEduCessRate = 0;
            double dblCalculateTaxCreditAmt = 0;
            //-- 2015/03/27
            double dblECessRate = 1;
            double dblHigherECessRate = 2;

            //VARIABLE DECLARATION FOR SURCHARGE CALCULATION 
            double dblSurchargeLimitAmount1Cr = 10000000.00;
            double dblSurchargeLimitAmount50L = 5000000.00;
            //-- 2020/05/25
            double dblSurchargeLimitAmount2Cr = 20000000.00;
            double dblSurchargeLimitAmount5Cr = 50000000.00;
            double dblSurchargeLimitAmountExceeds5Cr = 50000000.00;
            //-- 2024/01/15

            //
            double dblExcedAmount = 0.00;
            double dblSurchargeOnTaxAmount = 0.00;
            double dblExcessCalculatedTax = 0.00;
            double dblNetAmount = 0.00;
            double dblTaxRate = 0.00;
            double dblSurchargeRate = 0.10;
            //-------------------------------------------------
            try
            {
                // Steps of Calculation
                // Creating Temporary Table with all Slab rates
                // Storing Tax amounts in Temp table Slab wise
                // Tax Credit calculation
                // Surcharge calculation
                // E cess Calculation

                #region Storing Slab wise Tax in Temporary Table
                //
                dmlService.J_BeginTransaction();
                if (dmlService.J_IsDatabaseObjectExist(TDSMAN.T_tblTEMP_TAX_SLAB_SUMMARY) == true)
                {
                    //DROP TEMPORARY TABLE FOR TAX CALCULATION 
                    strSQL = "DROP TABLE " + TDSMAN.T_tblTEMP_TAX_SLAB_SUMMARY + "";
                    //MessageBox.Show(strSQL);
                    dmlService.J_ExecSql(strSQL);
                }
                //--
                //TEMP TABLE TO STORE SLAB WISE CALCULATED TAX AMOUNT
                //strSQL = "CREATE TABLE " + TDSMAN.T_tblTEMP_TAX_SLAB_SUMMARY + "(" +
                //             "              INCOME_FROM             MONEY  DEFAULT 0, " +
                //             "              INCOME_TO               MONEY  DEFAULT 0, " +
                //             "              TAX_RATE                MONEY  DEFAULT 0, " +
                //             "              SLAB_WISE_TAX_AMOUNT    MONEY  DEFAULT 0, " +
                //             "              EDUCATION_CESS_RATE     MONEY  DEFAULT 0, " +
                //             "              EDUCATION_CESS_AMOUNT   MONEY  DEFAULT 0, " +
                //             "              TAX_CREDIT_RATE         MONEY  DEFAULT 0, " +
                //             "              TAX_CREDIT_MAX_LIMIT    MONEY  DEFAULT 0, " +
                //             "              TAX_CREDIT_AMOUNT       MONEY  DEFAULT 0, " +
                //             "              SURCHARGE_AMOUNT        MONEY  DEFAULT 0) ";
                //--
                strSQL = "CREATE TABLE " + TDSMAN.T_tblTEMP_TAX_SLAB_SUMMARY + "(" +
                             "         " + cmnService.J_GetDataType("INCOME_FROM", J_ColumnType.Double) + "," +
                             "         " + cmnService.J_GetDataType("INCOME_TO", J_ColumnType.Double) + "," +
                             "         " + cmnService.J_GetDataType("TAX_RATE", J_ColumnType.Double) + "," +
                             "         " + cmnService.J_GetDataType("SLAB_WISE_TAX_AMOUNT", J_ColumnType.Double) + "," +
                             "         " + cmnService.J_GetDataType("EDUCATION_CESS_RATE", J_ColumnType.Double) + "," +
                             "         " + cmnService.J_GetDataType("EDUCATION_CESS_AMOUNT", J_ColumnType.Double) + "," +
                             "         " + cmnService.J_GetDataType("TAX_CREDIT_RATE", J_ColumnType.Double) + "," +
                             "         " + cmnService.J_GetDataType("TAX_CREDIT_MAX_LIMIT", J_ColumnType.Double) + "," +
                             "         " + cmnService.J_GetDataType("TAX_CREDIT_AMOUNT", J_ColumnType.Double) + "," +
                             "         " + cmnService.J_GetDataType("SURCHARGE_AMOUNT", J_ColumnType.Double) + "," +
                             "         " + cmnService.J_GetDataType("AMOUNT_TAX", J_ColumnType.Double) + "," +
                             "         " + cmnService.J_GetDataType("SECTION_115BAC_MARGINAL_RELIEF", J_ColumnType.Integer) + ") ";

                dmlService.J_ExecSql(strSQL);
                //MessageBox.Show(strSQL);
                //--
                strSQL = "DELETE FROM " + TDSMAN.T_tblTEMP_TAX_SLAB_SUMMARY + "";
                dmlService.J_ExecSql(strSQL);
                //MessageBox.Show(strSQL);
                //--
                dmlService.J_Commit();
                //--
                //NOW SELECTING APPLICABLE SLABS BASED ON
                //1. INCOME, 2. CATEGORY, 3. ASSESSMENT YEAR
                strSQL = @"SELECT INCOME_FROM, 
                                  INCOME_TO,
                                  TAX_RATE,
                                  EDUCATION_CESS_RATE,
                                  TAX_CREDIT_RATE,
                                  SECTION_115BAC_MARGINAL_RELIEF
                           FROM   MST_INCOME_TAX_SLAB 
                           WHERE  MST_INCOME_TAX_SLAB.CATEGORY   = '" + Category + "' " +
                         @"AND   MST_INCOME_TAX_SLAB.ASST_ID     =  " + AsstId + " " +
                         @"AND   MST_INCOME_TAX_SLAB.INCOME_FROM <  " + TaxableAmount + " " +
                         @"AND   MST_INCOME_TAX_SLAB.SECTION_115BAC_FLAG = " + intSection115BAC + " " + //-- 2020/07/01
                         @"ORDER BY TAX_SLAB_ID";

                DataSet ds;
                ds = dmlService.J_ExecSqlReturnDataSet(strSQL);
                //MessageBox.Show(strSQL);
                // Returning zero Incase no slab is found for the given parameters
                // Possible when category or assessment year is not provided
                if (ds == null || ds.Tables[0].Rows.Count == 0)
                    return 0;

                // Calculating the Tax amount based on each slab rate 
                for (int i = 1; i <= ds.Tables[0].Rows.Count; i++)
                 {
                    // Taking the amount on which the current tax will be calculated
                    if (Convert.ToDouble(TaxableAmount) > Convert.ToDouble(ds.Tables[0].Rows[i - 1]["INCOME_TO"]))
                    {
                        // Incase the amount is more than the To Amount of current slab 
                        // then Tax will be calculated on entire bracket (To amount - From amount)
                        dblAmtDifference = Convert.ToDouble(ds.Tables[0].Rows[i - 1]["INCOME_TO"]) - Convert.ToDouble(ds.Tables[0].Rows[i - 1]["INCOME_FROM"]);
                    }
                    else
                    {
                        // Incase the amount is less than the To Amount of current slab 
                        // then Tax will be calculated only on the amount exceeding from amount
                        dblAmtDifference = Convert.ToDouble(TaxableAmount) - Convert.ToDouble(ds.Tables[0].Rows[i - 1]["INCOME_FROM"]);
                    }

                    //Tax on current slab
                    dblSlabTaxAmtOnTotalIncome = Math.Round((dblAmtDifference * Convert.ToDouble(ds.Tables[0].Rows[i - 1]["TAX_RATE"]) / 100), 0, MidpointRounding.AwayFromZero);
                    //-- 2023/11/21
                    if (i == ds.Tables[0].Rows.Count)
