                TaxCredit = 0;

                // ======================================================
                // OLD REGIME
                // ======================================================
                if (intSection115BAC == 0)
                {
                    // AY 2014-15 onwards Section 87A introduced
                    if (AsstId >= T_FinancialYearID.F2014_15ID &&
                        AsstId <= T_FinancialYearID.F2016_17ID)
                    {
                        // Rebate ₹2,000 up to ₹5L
                        if (TaxableAmount <= 500000)
                            TaxCredit = Math.Min(taxBeforeRebate, 2000);
                    }
                    else if (AsstId >= T_FinancialYearID.F2017_18ID &&
                             AsstId <= T_FinancialYearID.F2018_19ID)
                    {
                        // Rebate ₹2,500 up to ₹3.5L
                        if (TaxableAmount <= 350000)
                            TaxCredit = Math.Min(taxBeforeRebate, 2500);
                    }
                    else if (AsstId >= T_FinancialYearID.F2019_20ID)
                    {
                        // Rebate ₹12,500 up to ₹5L
                        if (TaxableAmount <= 500000)
                            TaxCredit = Math.Min(taxBeforeRebate, 12500);
                    }
                }

                // ======================================================
                // NEW REGIME (115BAC)
                // ======================================================
                else
                {
                    // AY 2021-22 to AY 2023-24
                    if (AsstId >= T_FinancialYearID.F2021_22ID &&
                        AsstId <= T_FinancialYearID.F2023_24ID)
                    {
                        // ₹5L limit, ₹12,500 rebate
                        if (TaxableAmount <= 500000)
                            TaxCredit = Math.Min(taxBeforeRebate, 12500);
                    }

                    // AY 2024-25 (FY 2023-24)
                    else if (AsstId == T_FinancialYearID.F2024_25ID)
                    {
                        if (TaxableAmount <= 700000)
                        {
                            TaxCredit = taxBeforeRebate;
                        }
                        else
                        {
                            double excessIncome = TaxableAmount - 700000;
                            TaxCredit = Math.Max(0, taxBeforeRebate - excessIncome);
                        }
                    }

                    // AY 2025-26 onwards
                    else if (AsstId >= T_FinancialYearID.F2025_26ID)
                    {
                        if (TaxableAmount <= 1200000)
                        {
                            TaxCredit = Math.Min(taxBeforeRebate, 60000);
                        }
                        else if (TaxableAmount <= 1275000)
                        {
                            double excessIncome = TaxableAmount - 1200000;
                            double relief = taxBeforeRebate - excessIncome;
                            TaxCredit = relief > 0 ? Math.Min(relief, 60000) : 0;
                        }
                        else
                        {
                            TaxCredit = 0;
                        }
                    }
                }

                // Apply rebate
                dblTaxonTotalIncome = taxBeforeRebate - TaxCredit;
                if (dblTaxonTotalIncome < 0)
