                //            // Tax rate on income above 1 crore as per slab
                //            dblTaxRate = Convert.ToDouble(ds.Tables[0].Rows[ds.Tables[0].Rows.Count - 1]["TAX_RATE"]);

                //            // Tax Already charged on income Exceeding 1 crore
                //            dblExcessCalculatedTax = Math.Round(((dblTaxRate / 100) * dblExcedAmount), 0, MidpointRounding.AwayFromZero);

                //            //Net Exceeding amount 
                //            dblNetAmount = dblExcedAmount - dblExcessCalculatedTax;

                //            // -----------------------------------------------

                //            // Surcharge will be minimum value of Amount Exceeding or Surcharge calculation

                //            if (dblNetAmount >= dblSurchargeOnTaxAmount)
                //                Surcharge = dblSurchargeOnTaxAmount;
                //            else
                //                Surcharge = dblNetAmount;
                //        }
                //    }
                //}
                //-----------------------------------------------------------
                //-----------------------------------------------------------
                #endregion

                #region SURCHARGE CALCULATION

                // Applicable Financial Year 2013-14 onwards.
                if (AsstId >= T_FinancialYearID.F2013_14ID)
                {
                    if (AsstId >= T_FinancialYearID.F2017_18ID)
                    {
                        double dblSurchargeLimitAmount = 0;
                        bool blSurcharge = false;
                        //========================================================
                        // DETERMINE SURCHARGE RATE
                        //========================================================

                        if (TaxableAmount > dblSurchargeLimitAmount50L &&
                            TaxableAmount <= dblSurchargeLimitAmount1Cr)
                        {
                            blSurcharge = true;
                            dblSurchargeLimitAmount = dblSurchargeLimitAmount50L;
                            dblSurchargeRate = 0.10;
                        }
                        else if (TaxableAmount > dblSurchargeLimitAmount1Cr)
                        {
                            blSurcharge = true;
                            dblSurchargeLimitAmount = dblSurchargeLimitAmount1Cr;
                            dblSurchargeRate = 0.15;
                        }

                        //-- 2020/05/26
                        if (AsstId >= T_FinancialYearID.F2019_20ID)
                        {
                            if (TaxableAmount > dblSurchargeLimitAmount2Cr &&
                                TaxableAmount <= dblSurchargeLimitAmount5Cr)
                            {
                                blSurcharge = true;
                                dblSurchargeLimitAmount = dblSurchargeLimitAmount2Cr;
                                dblSurchargeRate = 0.25;
                            }
                            else if (TaxableAmount > dblSurchargeLimitAmount5Cr)
                            {
                                blSurcharge = true;
                                dblSurchargeLimitAmount = dblSurchargeLimitAmount5Cr;

                                dblSurchargeRate = 0.37;

                                if (intSection115BAC == 1)
                                    dblSurchargeRate = 0.25;
                            }
                        }

                        //========================================================
                        // SURCHARGE CALCULATION
                        //========================================================

                        if (blSurcharge == true)
                        {
                            double dblTaxOn1Cr = 0;
                            double dblTaxOn2Cr = 0;
                            double dblTaxOn5Cr = 0;

                            double dblSurchargeRate50L = 0.10;
                            double dblSurchargeRate1Cr = 0.15;
                            double dblSurchargeRate2Cr = 0.25;
                            double dblSurchargeRate5Cr = 0.37;

                            //----------------------------------------------------
                            // NEW REGIME MAX SURCHARGE CAP
                            //----------------------------------------------------
                            if (intSection115BAC == 1)
                                dblSurchargeRate5Cr = 0.25;
                            else
                                dblSurchargeRate5Cr = 0.37;

                            //----------------------------------------------------
                            // THRESHOLD TAX VALUES
                            //----------------------------------------------------
                            if (intSection115BAC == 1)
                            {
                                if (AsstId >= T_FinancialYearID.F2025_26ID)
                                {
                                    // FY 2025-26 / AY 2026-27
                                    dblTaxOn1Cr = 2580000;
                                    dblTaxOn2Cr = 5580000;
                                    dblTaxOn5Cr = 14580000;
                                }
                                else
                                {
                                    // OLD NEW REGIME
                                    dblTaxOn1Cr = 2737500;
                                    dblTaxOn2Cr = 5737500;
                                    dblTaxOn5Cr = 14737500;
                                }
                            }
                            else
                            {
                                if (Category == "S")
                                {
                                    dblTaxOn1Cr = 2810000;
                                    dblTaxOn2Cr = 5810000;
                                    dblTaxOn5Cr = 14810000;
                                }
                                else if (Category == "O")
                                {
                                    dblTaxOn1Cr = 2800000;
                                    dblTaxOn2Cr = 5800000;
                                    dblTaxOn5Cr = 14800000;
                                }
                                else
                                {
                                    dblTaxOn1Cr = 2812500;
                                    dblTaxOn2Cr = 5812500;
                                    dblTaxOn5Cr = 14812500;
                                }
                            }

                            //====================================================
                            // ABOVE 5 CRORE
                            //====================================================
                            if (TaxableAmount > dblSurchargeLimitAmount5Cr)
                            {
                                //################################################
                                double dblSurchargeOn5Cr =
                                    Math.Round((dblTaxOn5Cr * dblSurchargeRate2Cr), 0,
                                    MidpointRounding.AwayFromZero);

                                double dblAmountExceed5Cr =
                                    TaxableAmount - dblSurchargeLimitAmount5Cr;

                                double dblTaxExceedAmount =
                                    Math.Round((0.30 * dblAmountExceed5Cr), 0,
                                    MidpointRounding.AwayFromZero);

                                double dblExpectedSurchargeOnTaxAmount5Cr =
                                    Math.Round((dblSurchargeRate *
                                    (dblTaxExceedAmount + dblTaxOn5Cr)), 0,
                                    MidpointRounding.AwayFromZero);

                                double dblDiffPrevSlab =
                                    (dblTaxonTotalIncome +
                                     dblExpectedSurchargeOnTaxAmount5Cr)
                                    -
                                    (dblTaxOn5Cr + dblSurchargeOn5Cr);

                                //-----------------------------------------------

                                if (dblDiffPrevSlab > dblAmountExceed5Cr)
                                    Surcharge =
                                        dblExpectedSurchargeOnTaxAmount5Cr -
                                        (dblDiffPrevSlab - dblAmountExceed5Cr);
                                else
                                    Surcharge =
                                        Math.Round((dblSurchargeRate *
                                        dblTaxonTotalIncome), 0,
                                        MidpointRounding.AwayFromZero);
                            }

                            //====================================================
                            // ABOVE 2 CRORE
                            //====================================================
                            else if (TaxableAmount > dblSurchargeLimitAmount2Cr)
                            {
                                //################################################
                                double dblSurchargeOn2Cr =
                                    Math.Round((dblTaxOn2Cr * dblSurchargeRate1Cr), 0,
                                    MidpointRounding.AwayFromZero);

                                double dblAmountExceed2Cr =
                                    TaxableAmount - dblSurchargeLimitAmount2Cr;

                                double dblTaxExceedAmount =
                                    Math.Round((0.30 * dblAmountExceed2Cr), 0,
                                    MidpointRounding.AwayFromZero);

                                double dblExpectedSurchargeOnTaxAmount2Cr =
                                    Math.Round((dblSurchargeRate *
                                    (dblTaxExceedAmount + dblTaxOn2Cr)), 0,
                                    MidpointRounding.AwayFromZero);

                                double dblDiffPrevSlab =
                                    (dblTaxonTotalIncome +
                                     dblExpectedSurchargeOnTaxAmount2Cr)
                                    -
                                    (dblTaxOn2Cr + dblSurchargeOn2Cr);

                                //-----------------------------------------------

                                if (dblDiffPrevSlab > dblAmountExceed2Cr)
                                    Surcharge =
                                        dblExpectedSurchargeOnTaxAmount2Cr -
                                        (dblDiffPrevSlab - dblAmountExceed2Cr);
                                else
                                    Surcharge =
                                        Math.Round((dblSurchargeRate *
                                        dblTaxonTotalIncome), 0,
                                        MidpointRounding.AwayFromZero);
                            }

                            //====================================================
                            // ABOVE 1 CRORE
                            //====================================================
                            else if (TaxableAmount > dblSurchargeLimitAmount1Cr)
                            {
                                //################################################                                
                                double dblSurchargeOn1Cr =
                                    Math.Round((dblTaxOn1Cr * dblSurchargeRate50L), 0,
                                    MidpointRounding.AwayFromZero);

                                double dblAmountExceed1Cr =
                                    TaxableAmount - dblSurchargeLimitAmount1Cr;

                                double dblTaxExceedAmount =
                                    Math.Round((0.30 * dblAmountExceed1Cr), 0,
                                    MidpointRounding.AwayFromZero);

                                double dblExpectedSurchargeOnTaxAmount1Cr =
                                    Math.Round((dblSurchargeRate *
                                    (dblTaxExceedAmount + dblTaxOn1Cr)), 0,
                                    MidpointRounding.AwayFromZero);

                                double dblDiffPrevSlab =
                                    (dblTaxonTotalIncome +
                                     dblExpectedSurchargeOnTaxAmount1Cr)
                                    -
                                    (dblTaxOn1Cr + dblSurchargeOn1Cr);

                                //-----------------------------------------------

                                if (dblDiffPrevSlab > dblAmountExceed1Cr)
                                    Surcharge =
                                        dblExpectedSurchargeOnTaxAmount1Cr -
                                        (dblDiffPrevSlab - dblAmountExceed1Cr);
                                else
                                    Surcharge =
                                        Math.Round((dblSurchargeRate *
                                        dblTaxonTotalIncome), 0,
                                        MidpointRounding.AwayFromZero);

                                //-----------------------------------------------

                                if (Surcharge < 0)
                                    Surcharge = 0;
                            }

                            //====================================================
                            // ABOVE 50 LAKH
                            //====================================================
                            else
                            {
                                dblSurchargeOnTaxAmount =
                                    Math.Round((dblSurchargeRate *
                                    dblTaxonTotalIncome), 0,
                                    MidpointRounding.AwayFromZero);

                                //-----------------------------------------------
                                // Amount Exceeding 50 lakh
                                //-----------------------------------------------

                                dblExcedAmount =
                                    TaxableAmount - dblSurchargeLimitAmount;

                                dblTaxRate =
                                    Convert.ToDouble(ds.Tables[0]
                                    .Rows[ds.Tables[0].Rows.Count - 1]["TAX_RATE"]);

                                dblExcessCalculatedTax =
                                    Math.Round(((dblTaxRate / 100) *
                                    dblExcedAmount), 0,
                                    MidpointRounding.AwayFromZero);

                                dblNetAmount =
                                    dblExcedAmount - dblExcessCalculatedTax;

                                //-----------------------------------------------

                                if (dblNetAmount >= dblSurchargeOnTaxAmount)
                                    Surcharge = dblSurchargeOnTaxAmount;
                                else
                                    Surcharge = dblNetAmount;
                            }
                        }
                    }
                    else
                    {
                        if (TaxableAmount > dblSurchargeLimitAmount1Cr)
                        {
                            if (AsstId >= T_FinancialYearID.F2015_16ID)
                            {
                                if (AsstId >= T_FinancialYearID.F2016_17ID)
                                    dblSurchargeRate = 0.15;
                                else
                                    dblSurchargeRate = 0.12;
                            }

                            dblSurchargeOnTaxAmount =
                                Math.Round((dblSurchargeRate *
                                dblTaxonTotalIncome), 0,
                                MidpointRounding.AwayFromZero);

                            dblExcedAmount =
                                TaxableAmount - dblSurchargeLimitAmount1Cr;

                            dblTaxRate =
                                Convert.ToDouble(ds.Tables[0]
                                .Rows[ds.Tables[0].Rows.Count - 1]["TAX_RATE"]);

                            dblExcessCalculatedTax =
                                Math.Round(((dblTaxRate / 100) *
                                dblExcedAmount), 0,
                                MidpointRounding.AwayFromZero);

                            dblNetAmount =
                                dblExcedAmount - dblExcessCalculatedTax;

                            if (dblNetAmount >= dblSurchargeOnTaxAmount)
                                Surcharge = dblSurchargeOnTaxAmount;
                            else
                                Surcharge = dblNetAmount;
                        }
                    }
                }

                #endregion

                #region EDUCATIONAL CESS CALCULATION
                //Getting Applicable Cess rate
                //dblEduCessRate = Convert.ToDouble(ds.Tables[0].Rows[ds.Tables[0].Rows.Count - 1]["EDUCATION_CESS_RATE"]); //-- 2015/03/27

                //ECess = Math.Round((dblTaxonTotalIncome + Surcharge) * dblEduCessRate / 100);
                //ECess = Math.Round((dblTaxonTotalIncome + Surcharge) * dblHigherECessRate / 100, 0, MidpointRounding.AwayFromZero);
                //ECess = ECess + Math.Round((dblTaxonTotalIncome + Surcharge) * dblECessRate / 100, 0, MidpointRounding.AwayFromZero);
                //-- 2018/06/07
                if (AsstId >= T_FinancialYearID.F2018_19ID)
                {
                    dblECessRate = 4;
                    //ECess = Math.Round((dblTaxonTotalIncome + Surcharge) * dblECessRate / 100, 0, MidpointRounding.AwayFromZero); //-- 2018/06/07
                    ECess = Math.Round(((TaxonTotalIncomeB4TaxCredit - TaxCredit) + Surcharge) * dblECessRate / 100, 0, MidpointRounding.AwayFromZero); //-- 2018/06/07
                }
                else
                {
                    //dblECessRate = 3; dblHigherECessRate = 1;
                    ECess = Math.Round((dblTaxonTotalIncome + Surcharge) * dblHigherECessRate / 100, 0, MidpointRounding.AwayFromZero); //-- 2018/05/18
                    ECess = ECess + Math.Round((dblTaxonTotalIncome + Surcharge) * dblECessRate / 100, 0, MidpointRounding.AwayFromZero); //-- 2018/05/18
                }
                //
                //ECess = Math.Round(ECess, 0, MidpointRounding.AwayFromZero); //-- 2018/05/18
                if (ECess < 0)
                    ECess = 0;
                #endregion

                #region Updating Surcharge, Cess in temp Table and adding other slabs

                // Now updating tax credit, Surcharge & Cess amount in Temporary table 
                strSQL = "UPDATE " + TDSMAN.T_tblTEMP_TAX_SLAB_SUMMARY + " " +
                         "SET SURCHARGE_AMOUNT       = " + Surcharge + ", " +
                         "    EDUCATION_CESS_AMOUNT  = " + ECess + ", " +
                         //"    TAX_CREDIT_AMOUNT      = " + dblCalculateTaxCreditAmt;
                         "    TAX_CREDIT_AMOUNT      = " + TaxCredit;

                dmlService.J_ExecSql(strSQL);

                // Adding left over slabs in Temp Table
                strSQL = @"INSERT INTO " + TDSMAN.T_tblTEMP_TAX_SLAB_SUMMARY + "( " +
                          "       INCOME_FROM, " +
                          "       INCOME_TO, " +
                          "       TAX_RATE, " +
                          "       EDUCATION_CESS_RATE) " +
                          "SELECT INCOME_FROM, " +
                          "       INCOME_TO, " +
                          "       TAX_RATE, " +
                          "       EDUCATION_CESS_RATE " +
                          "FROM   MST_INCOME_TAX_SLAB " +
                          "WHERE  MST_INCOME_TAX_SLAB.CATEGORY    = '" + Category + "' " +
                          "AND   MST_INCOME_TAX_SLAB.ASST_ID      =  " + AsstId + " " +
                          "AND   MST_INCOME_TAX_SLAB.INCOME_FROM >=  " + TaxableAmount + " " +
                          "AND   MST_INCOME_TAX_SLAB.SECTION_115BAC_FLAG = " + intSection115BAC + " " + //-- 2020/07/01

                dmlService.J_ExecSql(strSQL);

                #endregion

                return dblTaxonTotalIncome;
            }
            catch (Exception err)
            {
                cmnService.J_UserMessage(err.Message);
                return 0;
            }
        }

        #endregion

