        #region CalcTDSRateForNonSalary [1]
        public double CalcTDSRateForNonSalary(int SectionId, string DeducteeDate, string PANNumber, string FormNo, out int IgnoreTaxSlab, out int ComplianceHigherRateFlag)
        {
            return CalcTDSRateForNonSalary(dmlService.J_pCommand, SectionId, DeducteeDate, PANNumber, FormNo, out IgnoreTaxSlab, out ComplianceHigherRateFlag);
        }
        #endregion

        #region CalcTDSRateForNonSalary [2]
        public double CalcTDSRateForNonSalary(IDbCommand command, int SectionId, string DeducteeDate, string PANNumber, string FormNo,  out int IgnoreTaxSlab, out int ComplianceHigherRateFlag)
        {
            IgnoreTaxSlab = 0;
            ComplianceHigherRateFlag = 0;
            try
            {
                //Declaring DataSet and Data Reader
                DataSet ds;

                //Declaring Variables
                double dblTDSRate = 0;
                string strPanType = "";
                //
                //--

                //PAN NUMBER CHECKING 
                if (PANNumber.Length != 10) return 0;

                //SECTION NO CHECKING 
                if (SectionId == 0 ) return 0;

                //DEDUCTEE DATE CHECKING 
                if ((DeducteeDate.Trim() == "/  /") || (dtService.J_IsDateValid(DeducteeDate) == false)) return 0;

                //PAN IS VALID CHECKING 
                if (PANNumber != "")
                {                    
                    if ( dtService.J_ConvertToIntYYYYMMDD(DeducteeDate) < 20210701) //-- 2021/07/09
                        ComplianceHigherRateFlag = 0;
                    else
                        ComplianceHigherRateFlag = Convert.ToInt32(dmlService.J_ExecSqlReturnScalar("SELECT COMPLIANCE_HIGHER_RATE_FLAG FROM MST_DEDUCTEE WHERE DEDUCTEE_PAN ='" + PANNumber + "'"));
                    
                    //if ((PANNumber == "PANNOTAVBL") || (PANNumber == "PANAPPLIED") || (PANNumber == "PANINVALID"))
                    //    strPanType = T_PayeeTypeStructure.NotAvailable;
                    //else if (PANNumber.Substring(3, 1) == "C")
                    //    strPanType = T_PayeeTypeStructure.Company;
                    //else
                    //    strPanType = T_PayeeTypeStructure.NonCompany;
                    if (ComplianceHigherRateFlag > 0)
                        strPanType = T_PayeeTypeStructure.ComplianceHigherRate;
                    //-- ANIK @ 2014-05-24
                    else if ((PANNumber == "PANNOTAVBL") || (PANNumber == "PANAPPLIED") || (PANNumber == "PANINVALID"))
                        strPanType = T_PayeeTypeStructure.NotAvailable;
                    else if (PANNumber.Substring(3, 1) == "P" || PANNumber.Substring(3, 1) == "H")
                        strPanType = T_PayeeTypeStructure.NonCompany;
                    else
                        strPanType = T_PayeeTypeStructure.Company;
                }
                //--
                //FETCH DATA BASED ON SECTION_ID,DEDUCTEE_DATE
                strSQL = @"SELECT  MST_NONSALARY_TAX_SLAB.NONSALARY_TAX_SLAB_ID,
                                   MST_NONSALARY_TAX_SLAB.SECTION_ID,
                                   MST_NONSALARY_TAX_SLAB.FROM_DATE,
                                   MST_NONSALARY_TAX_SLAB.TO_DATE,
                                   MST_NONSALARY_TAX_SLAB.COMPANY_RATE,
                                   MST_NONSALARY_TAX_SLAB.NON_COMPANY_RATE,
                                   MST_NONSALARY_TAX_SLAB.INVALID_PAN_RATE,
                                   MST_NONSALARY_TAX_SLAB.IGNORE_TAX_RATE_FLAG,
                                   MST_NONSALARY_TAX_SLAB.COMPLIANCE_HIGHER_RATE 
                           FROM    MST_NONSALARY_TAX_SLAB, 
                                   MST_SECTION
                         WHERE     MST_NONSALARY_TAX_SLAB.SECTION_ID = MST_SECTION.SECTION_ID 
                         AND       MST_SECTION.SECTION_ID  = " + SectionId + @" 
                         AND       MST_SECTION.FORM_NAME   = '" + FormNo + "' " +
                       @"AND     MST_NONSALARY_TAX_SLAB.FROM_DATE  <= " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(DeducteeDate) + cmnService.J_DateOperator() + " " +
                       @"AND     MST_NONSALARY_TAX_SLAB.TO_DATE    >= " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(DeducteeDate) + cmnService.J_DateOperator() + " ";
                //--
                ds = new DataSet();
                //EXECUTE QUERY STRING FOR FETCHING DATA FROM MST_NONSALARY_TAX_SLAB
                ds = dmlService.J_ExecSqlReturnDataSet(command, strSQL);
                //
                if (ds == null) return 0;
                //
                IgnoreTaxSlab = Convert.ToInt32(ds.Tables[0].Rows[0]["IGNORE_TAX_RATE_FLAG"]);
                //
                for (int i = 1; i <= ds.Tables[0].Rows.Count; i++)
                {
                    if (strPanType == T_PayeeTypeStructure.ComplianceHigherRate)
                        dblTDSRate = Convert.ToDouble(ds.Tables[0].Rows[i - 1]["COMPLIANCE_HIGHER_RATE"]);
                    //--
                    if (dblTDSRate == 0)
                    {
                        if (strPanType == T_PayeeTypeStructure.Company)
                            dblTDSRate = Convert.ToDouble(ds.Tables[0].Rows[i - 1]["COMPANY_RATE"]);
                        else if (strPanType == T_PayeeTypeStructure.NonCompany)
                            dblTDSRate = Convert.ToDouble(ds.Tables[0].Rows[i - 1]["NON_COMPANY_RATE"]);
                        else if (strPanType == T_PayeeTypeStructure.NotAvailable)
                            dblTDSRate = Convert.ToDouble(ds.Tables[0].Rows[i - 1]["INVALID_PAN_RATE"]);
                    }
                }
                //
                TDSMAN.T_NonSalaryTDSRate = dblTDSRate;
                //--
                return dblTDSRate;
            }
            catch
            {
                return 0;
            }
        }
        #endregion

