        #region Insert BookMark Detail  [5]
        public int T_GetBookMarkDetail(IDbCommand command, string OperationMode, int AsstId, string Qtr, string FormName, int CompanyId, long SetupId, out string Quarter, out string CompanyName, out string TAN, out string FormNo, out string FAYear)
        {
            IDataReader drdBookMark = null;
            //--
            string strQueryFilter = "";
            int strAsst_Id = 0;
            long lngNoofRows = 0;
            Quarter = "";
            CompanyName = "";
            FormNo = "";
            FAYear = "";
            TAN = "";
            //--
            try
            {
                //dmlService.J_BeginTransaction();
                //-----------------------
                //Inserting the BookMark
                if (OperationMode == T_TransactionMode.INSERT.ToString())
                {
                    #region INSERT
                    strSQL = @"INSERT INTO MST_BOOKMARK_DETAIL ( 
                                                                    ASST_ID,
                                                                    QUARTER,
                                                                    FORM_NAME,
                                                                    COMPANY_ID,
                                                                    LOG_DATE,
                                                                    SETUPID
                                                                    ) 
                                                        VALUES (" + AsstId + ",'"
                                                                  + Qtr + "','"
                                                                  + FormName + "',"
                                                                  + CompanyId + ","
                                                                  + GetServerDateTime() + ","
                                                                  + SetupId +
                                                               ")";
                    lngNoofRows = dmlService.J_ReturnNoOfRows(dmlService.J_pCommand, "MST_BOOKMARK_DETAIL");
                    if (lngNoofRows > 1)
                    {
                        Debug.Print("More than two records?");
                    }
                    dmlService.J_BeginTransaction();
                    dmlService.J_ExecSql(strSQL);
                    dmlService.J_Commit();
                    #endregion
                }
                else if (OperationMode == T_TransactionMode.UPDATE.ToString())
                {
                    #region UPDATE
                    strSQL = "UPDATE MST_BOOKMARK_DETAIL" +
                         " SET   ASST_ID    = " + AsstId + "," +
                         "       QUARTER    ='" + Qtr + "'," +
                         "       FORM_NAME  ='" + FormName + "'," +
                         "       COMPANY_ID = " + CompanyId + ", " +
                         "       LOG_DATE   = " + GetServerDateTime() + " " +
                         " WHERE FORM_NAME  ='" + FormName + "' " +
                         " AND   SETUPID    = " + SetupId + " ";
                    //strQueryFilter = " WHERE  FORM_NAME= '" + FormName + "' ";
                    //
                    dmlService.J_BeginTransaction();
                    lngNoofRows = dmlService.J_ReturnNoOfRows(dmlService.J_pCommand, "MST_BOOKMARK_DETAIL");
                    if (lngNoofRows > 4)
                    {
                        Debug.Print("More than two records?");
                    }
                    dmlService.J_ExecSql(strSQL);
                    //
                    dmlService.J_Commit();
                    #endregion
                }
                //--------------------------
                //Retrieve the BookMark
                else if (OperationMode == T_TransactionMode.SHOW.ToString())
                {
                    #region SHOW
                    if (FormName == "")
                        strSQL = @"SELECT TOP 1 MST_BOOKMARK_DETAIL.ASST_ID,
                                                MST_ASSESSMENT.FA_YEAR,
                                                MST_BOOKMARK_DETAIL.QUARTER,
                                                MST_BOOKMARK_DETAIL.FORM_NAME,
                                                MST_COMPANY.COMPANY_NAME,
                                                MST_COMPANY.TAN_NO 
                                   FROM         MST_BOOKMARK_DETAIL,
                                                MST_COMPANY,
                                                MST_ASSESSMENT
                                   WHERE        MST_BOOKMARK_DETAIL.COMPANY_ID = MST_COMPANY.COMPANY_ID
                                   AND          MST_BOOKMARK_DETAIL.ASST_ID    = MST_ASSESSMENT.ASST_ID
                                   AND          MST_COMPANY.INACTIVE_FLAG      = 0
                                   ORDER BY     MST_BOOKMARK_DETAIL.LOG_DATE DESC";
                    else
                        strSQL = @"SELECT MST_BOOKMARK_DETAIL.ASST_ID,
                                          '' AS FA_YEAR,
                                          MST_BOOKMARK_DETAIL.QUARTER,
                                          MST_BOOKMARK_DETAIL.FORM_NAME,
                                          MST_BOOKMARK_DETAIL.COMPANY_ID,
                                          MST_COMPANY.COMPANY_NAME,
                                          MST_COMPANY.TAN_NO 
                                  FROM    MST_BOOKMARK_DETAIL,
                                          MST_COMPANY
                                  WHERE   MST_BOOKMARK_DETAIL.FORM_NAME  ='" + FormName + "' " + @"
                                  AND     MST_BOOKMARK_DETAIL.COMPANY_ID = MST_COMPANY.COMPANY_ID 
                                  AND     MST_COMPANY.INACTIVE_FLAG      = 0
                                  AND     MST_BOOKMARK_DETAIL.SETUPID    = " + SetupId;
                    //--
                    drdBookMark = dmlService.J_ExecSqlReturnReader(strSQL);
                    if (drdBookMark == null)
                    {
                        return strAsst_Id;
                    }
                    while (drdBookMark.Read())
                    {
                        strAsst_Id = Convert.ToInt32(drdBookMark["ASST_ID"]);
                        Quarter = Convert.ToString(drdBookMark["QUARTER"]);
                        CompanyName = Convert.ToString(drdBookMark["COMPANY_NAME"]);
                        TAN = Convert.ToString(drdBookMark["TAN_NO"]);
                        FormNo = Convert.ToString(drdBookMark["FORM_NAME"]); ;
                        FAYear = Convert.ToString(drdBookMark["FA_YEAR"]); ;
                    }
                    drdBookMark.Close();
                    drdBookMark.Dispose();
                    #endregion
                }
                return strAsst_Id;
            }
            catch
            {
                return strAsst_Id;
            }
        }
        #endregion 

        

        #region T_LateDeduction
        public void T_LateDeduction(int CompanyId, int AsstId, string Qtr, string FormNo)
        {
            string strQueryString = "";

            string strFieldEmployeeDeducteeName = "";
            string strFieldEmployeeDeducteePAN = "";
            string strFieldEmployeeDeducteeJoinCondition = "";
            string strLastDateCreation = "";
            try
            {
                dmlService.J_BeginTransaction();
                if (dmlService.J_IsDatabaseObjectExist("" + TDSMAN.T_tblTEMP_LATE_DEDUCTION_SUMMARY + "") == true)
                {
                    //--------

                    //DROP TEMPORARY TABLE FOR TAX CALCULATION 
                    strSQL = "DROP TABLE " + TDSMAN.T_tblTEMP_LATE_DEDUCTION_SUMMARY + "";
                    dmlService.J_ExecSql(strSQL);
                }

                //--------
                //TEMP TABLE TO STORE SLAB WISE CALCULATED TAX AMOUNT
                strSQL = "CREATE TABLE " + TDSMAN.T_tblTEMP_LATE_DEDUCTION_SUMMARY + "(" +
                             "              COMPANY_ID              NUMBER   DEFAULT 0, " +
                             "              COMPANY_NAME            TEXT     DEFAULT \"\"," +
                             "              FA_YEAR                 TEXT     DEFAULT \"\"," +
                             "              QUARTER                 TEXT     DEFAULT \"\"," +
                             "              FORM_NO                 TEXT     DEFAULT \"\"," +
                             "              CHALLAN_ID              NUMBER   DEFAULT 0, " +
                             "              CHALLAN_NO              TEXT     DEFAULT 0, " +
                             "              CHALLAN_SL_NO           TEXT     DEFAULT 0, " +
                             "              DEDUCTEE_DETAIL_ID      NUMBER   DEFAULT 0, " +
                             "              DEDUCTEE_SL_NO          NUMBER   DEFAULT 0, " +
                             "              DEDUCTEE_NAME           TEXT     DEFAULT \"\"," +
                             "              DEDUCTEE_PAN            TEXT     DEFAULT \"\"," +
                             "              PAYMENT_AMOUNT          MONEY    DEFAULT 0, " +
                             "              TAX_AMOUNT              MONEY    DEFAULT 0, " +
                             "              TAX_DEPOSITED_AMOUNT    MONEY    DEFAULT 0, " +
                             "              PAYMENT_DATE            DATETIME, " +
                             "              DEDUCTED_DATE           DATETIME, " +
                             "              LAST_DATE               DATETIME, " +
                             "              CHALLAN_DEPOSIT_DATE    DATETIME, " +
                             "              MONTHS_DELAY            NUMBER   DEFAULT 0, " +
                             "              DATE_AFTER_DUE_DATE     NUMBER   DEFAULT 0, " +
                             "              TOTAL_DELAY             NUMBER   DEFAULT 0, " +
                             "              LATE_PAYMENT_INTEREST   MONEY    DEFAULT 0)";

                if (dmlService.J_ExecSql(strSQL) == false) return;
                //
                dmlService.J_Commit();
                //-----

                if (FormNo == T_FormNo.F24Q)
                {
                    strFieldEmployeeDeducteeName = "MST_EMPLOYEE.EMPLOYEE_NAME";
                    strFieldEmployeeDeducteePAN = "MST_EMPLOYEE.EMPLOYEE_PAN";
                    strFieldEmployeeDeducteeJoinCondition = "MST_EMPLOYEE.EMPLOYEE_ID";
                }
                else
                {
                    strFieldEmployeeDeducteeName = "MST_DEDUCTEE.DEDUCTEE_NAME";
                    strFieldEmployeeDeducteePAN = "MST_DEDUCTEE.DEDUCTEE_PAN";
                    strFieldEmployeeDeducteeJoinCondition = "MST_DEDUCTEE.DEDUCTEE_ID";
                }

                //strLastDateCreation = "IIF(MONTH(TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE) = 3, " +
                //                                  "CDATE(" + "\"30\"" + "+" + "RIGHT(CDATE(DATEADD(" + "\"M\"" + ", 1, FORMAT(TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE," + "\"DD/MM/YYYY\"" + "))), 8)), " +
                //                                  "CDATE(" + "\"07\"" + "+" + "RIGHT(CDATE(DATEADD(" + "\"M\"" + ", 1, FORMAT(TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE," + "\"DD/MM/YYYY\"" + "))), 8))  " +
                //                                ")";

                strLastDateCreation = "IIF(MONTH(TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE) = 3, " +
                                          "CDATE(" + "\"30\"" + "+" + "RIGHT(CDATE(DATEADD(" + "\"M\"" + ", 1, " +
                                          cmnService.J_SQLDBFormat("TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + ")), 8)), " +
                                          "CDATE(" + "\"07\"" + "+" + "RIGHT(CDATE(DATEADD(" + "\"M\"" + ", 1, " +
                                          cmnService.J_SQLDBFormat("TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + ")), 8)) " +
                                        ")";

                //                                                       "FORMAT(BASEQUERY.LAST_DATE," + "\"DD/MM/YYYY\"" + ")) < 0 " +
                //strLastDateCreation = "IIF(MONTH(TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE) = 3, " +
                //                  "CDATE(" + "\"30\"" + "+" + "RIGHT(CDATE(DATEADD(" + "\"M\"" + ", 1, "+ dtService.J_ConvertddMMyyyy(  + "))), 8)), " +
                //                  "CDATE(" + "\"07\"" + "+" + "RIGHT(CDATE(DATEADD(" + "\"M\"" + ", 1, "+   + "))), 8))  " +
                //                ")";

                dmlService.J_BeginTransaction();
                //INSERT SCRIPT
                strQueryString = @"INSERT INTO " + TDSMAN.T_tblTEMP_LATE_DEDUCTION_SUMMARY + @"( COMPANY_ID, 
                                                                    COMPANY_NAME,
                                                                    FA_YEAR,
                                                                    QUARTER,
                                                                    FORM_NO,
                                                                    CHALLAN_ID,
                                                                    CHALLAN_NO,
                                                                    CHALLAN_SL_NO,
                                                                    DEDUCTEE_DETAIL_ID,
                                                                    DEDUCTEE_SL_NO,
                                                                    DEDUCTEE_NAME,
                                                                    DEDUCTEE_PAN,
                                                                    PAYMENT_AMOUNT,
                                                                    TAX_AMOUNT,
                                                                    TAX_DEPOSITED_AMOUNT,
                                                                    PAYMENT_DATE,
                                                                    DEDUCTED_DATE,
                                                                    LAST_DATE,
                                                                    CHALLAN_DEPOSIT_DATE,                                                                    
                                                                    MONTHS_DELAY,
                                                                    DATE_AFTER_DUE_DATE,
                                                                    TOTAL_DELAY,
                                                                    LATE_PAYMENT_INTEREST)";
                //---------

                strSQL = "";
                strSQL = @"SELECT    MST_COMPANY.COMPANY_ID,
                                     MST_COMPANY.COMPANY_NAME,
                                     MST_ASSESSMENT.FA_YEAR,
                                     TRN_BASIC_INFO.QTR,
                                     TRN_BASIC_INFO.FORM_NO,
                                     TRN_CHALLAN.CHALLAN_ID,
                                     TRN_CHALLAN.CHALLAN_NO,
                                     TRN_CHALLAN.SL_NO                                      AS CHALLAN_SL_NO,
                                     TRN_DEDUCTEE_DETAILS.DEDUCTEE_DETAIL_ID, 
                                     TRN_DEDUCTEE_DETAILS.SL_NO                             AS DEDUCTEE_SL_NO,  
                                     MST_DEDUCTEE.DEDUCTEE_NAME,  
                                     MST_DEDUCTEE.DEDUCTEE_PAN,   
                                     TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT,
                                     TRN_DEDUCTEE_DETAILS.TAX_AMOUNT,
                                     TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT,
                                     TRN_DEDUCTEE_DETAILS.PAYMENT_DATE,
                                     TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE, " +
                                     strLastDateCreation + "              AS LAST_DATE, " +
                                   " TRN_CHALLAN.DEPOSIT_DATE                               AS CHALLAN_DEPOSIT_DATE, " +
                                   " DATEDIFF(" + "\"M\"," + strLastDateCreation + "," + cmnService.J_SQLDBFormat("TRN_CHALLAN.DEPOSIT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + ")         AS  MONTHS_DELAY, " +
                                   " IIF(DAY(" + cmnService.J_SQLDBFormat("TRN_CHALLAN.DEPOSIT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + " ) > DAY(" + strLastDateCreation + "),1,0)AS DATE_AFTER_DUE_DATE, " +
                                   " 1+ " +
                                   " DATEDIFF(" + "\"M\"," + strLastDateCreation + "," + cmnService.J_SQLDBFormat("TRN_CHALLAN.DEPOSIT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + ") + " +
                                   " IIF(DAY(" + cmnService.J_SQLDBFormat("TRN_CHALLAN.DEPOSIT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + " ) > " +
                                   "     DAY(" + strLastDateCreation + "),1,0) AS  TOTAL_DELAY, " +
                                   " TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT * ( " +
                                   " 1+ " +
                                   " DATEDIFF(" + "\"M\"," + strLastDateCreation + "," + cmnService.J_SQLDBFormat("TRN_CHALLAN.DEPOSIT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + ") + " +
                                   " IIF(DAY(" + cmnService.J_SQLDBFormat("TRN_CHALLAN.DEPOSIT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + " ) > " +
                                   "     DAY(" + strLastDateCreation + "),1,0)) AS  LATE_FEE " +
                         @"FROM      TRN_DEDUCTEE_DETAILS,                         
                                     TRN_CHALLAN, 
                                     TRN_BASIC_INFO, 
                                     MST_DEDUCTEE,
                                     MST_COMPANY, 
                                     MST_ASSESSMENT 
                          WHERE      TRN_DEDUCTEE_DETAILS.PARTY_ID      = MST_DEDUCTEE.DEDUCTEE_ID  
                          AND        TRN_DEDUCTEE_DETAILS.CHALLAN_ID    = TRN_CHALLAN.CHALLAN_ID 
                          AND        TRN_CHALLAN.BASIC_INFO_ID          = TRN_BASIC_INFO.BASIC_INFO_ID  
                          AND        TRN_BASIC_INFO.ASST_ID             = MST_ASSESSMENT.ASST_ID
                          AND        TRN_BASIC_INFO.COMPANY_ID          = MST_COMPANY.COMPANY_ID 
                          AND        TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE IS NOT NULL 
