        #region T_ShortDeduction
        public void T_ShortDeduction(int CompanyId, int AsstId, string Qtr, string FormNo)
        {
            string strQueryString = "";

            string strFieldEmployeeDeducteeName = "";
            string strFieldEmployeeDeducteePAN = "";
            string strFieldEmployeeDeducteeJoinCondition = "";
            string strActualAmtCreation = "";
            try
            {
                dmlService.J_BeginTransaction();
                if (dmlService.J_IsDatabaseObjectExist("" + TDSMAN.T_tblTEMP_SHORT_DEDUCTION_SUMMARY + "") == true)
                {
                    //--------

                    //DROP TEMPORARY TABLE FOR TAX CALCULATION 
                    strSQL = "DROP TABLE " + TDSMAN.T_tblTEMP_SHORT_DEDUCTION_SUMMARY + "";
                    dmlService.J_ExecSql(strSQL);
                }

                //--------
                //TEMP TABLE TO STORE SLAB WISE CALCULATED TAX AMOUNT
                strSQL = "CREATE TABLE " + TDSMAN.T_tblTEMP_SHORT_DEDUCTION_SUMMARY + "(" +
                                                         "              COMPANY_ID             NUMBER   DEFAULT 0, " +
                                                         "              COMPANY_NAME           TEXT     DEFAULT \"\"," +
                                                         "              FA_YEAR                TEXT     DEFAULT \"\"," +
                                                         "              QUARTER                TEXT     DEFAULT \"\"," +
                                                         "              FORM_NO                TEXT     DEFAULT \"\"," +
                                                         "              CHALLAN_ID             NUMBER   DEFAULT 0, " +
                                                         "              CHALLAN_NO             NUMBER   DEFAULT 0, " +
                                                         "              CHALLAN_SL_NO          NUMBER   DEFAULT 0, " +
                                                         "              CHALLAN_DEPOSIT_DATE   DATETIME, " +
                                                         "              DEDUCTEE_DETAIL_ID     NUMBER   DEFAULT 0, " +
                                                         "              DEDUCTEE_ID            NUMBER   DEFAULT 0, " +
                                                         "              DEDUCTEE_SL_NO         NUMBER   DEFAULT 0, " +
                                                         "              DEDUCTEE_NAME          TEXT     DEFAULT 0, " +
                                                         "              DEDUCTEE_PAN           TEXT     DEFAULT 0, " +
                                                         "              PAYMENT_DATE           DATETIME, " +
                                                         "              DEDUCTED_DATE          DATETIME, " +
                                                         "              PAYMENT_AMOUNT         MONEY    DEFAULT 0, " +
                                                         "              CALC_RATE              NUMBER   DEFAULT 0, " +
                                                         "              TAX_DEPOSITED_AMOUNT   MONEY    DEFAULT 0, " +
                                                         "              RATE                   NUMBER   DEFAULT 0, " +
                                                         "              ACTUAL_TAX_AMOUNT      MONEY    DEFAULT 0, " +
                                                         "              REASON                 TEXT     DEFAULT 0, " +
                                                         "              DESCRIPTION            TEXT     DEFAULT 0, " +
                                                         "              SECTION_ID             NUMBER   DEFAULT 0, " +
                                                         "              COMPANY_RATE           NUMBER   DEFAULT 0, " +
                                                         "              NON_COMPANY_RATE       NUMBER   DEFAULT 0, " +
                                                         "              INVALID_PAN_RATE       NUMBER   DEFAULT 0)";

                if (dmlService.J_ExecSql(strSQL) == false) return;
                //
                dmlService.J_Commit();
                //-----

                strFieldEmployeeDeducteeName = "MST_DEDUCTEE.DEDUCTEE_NAME";
                strFieldEmployeeDeducteePAN = "MST_DEDUCTEE.DEDUCTEE_PAN";
                strFieldEmployeeDeducteeJoinCondition = "MST_DEDUCTEE.DEDUCTEE_ID";

                strActualAmtCreation = @"IIF(MST_DEDUCTEE.DEDUCTEE_PAN = 'PANNOTAVBL' 
                                                         OR MST_DEDUCTEE.DEDUCTEE_PAN = 'PANAPPLIED' 
                                                         OR MST_DEDUCTEE.DEDUCTEE_PAN = 'PANINVALID', 
                                                  ROUND((TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT * MST_NONSALARY_TAX_SLAB.INVALID_PAN_RATE ) / 100,0), 
                                                       IIF(MID(MST_DEDUCTEE.DEDUCTEE_PAN, 4, 1) = 'C', 
                                                           ROUND((TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT * MST_NONSALARY_TAX_SLAB.COMPANY_RATE ) / 100,0), 
                                                           ROUND((TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT * MST_NONSALARY_TAX_SLAB.NON_COMPANY_RATE ) / 100,0))
                                                  )";


                dmlService.J_BeginTransaction();
                //--------------------------------------------
                //INSERT SCRIPT
                //--------------------------------------------
                strQueryString = @"INSERT INTO " + TDSMAN.T_tblTEMP_SHORT_DEDUCTION_SUMMARY + @"(COMPANY_ID, 
                                                                            COMPANY_NAME,
                                                                            FA_YEAR,
                                                                            QUARTER,
                                                                            FORM_NO,
                                                                            CHALLAN_ID,
                                                                            CHALLAN_NO,
                                                                            CHALLAN_SL_NO,
                                                                            CHALLAN_DEPOSIT_DATE,
                                                                            DEDUCTEE_DETAIL_ID,
                                                                            DEDUCTEE_ID,
                                                                            DEDUCTEE_SL_NO,
                                                                            DEDUCTEE_NAME,
                                                                            DEDUCTEE_PAN,
                                                                            PAYMENT_DATE,
                                                                            DEDUCTED_DATE,
                                                                            PAYMENT_AMOUNT,
                                                                            CALC_RATE,
                                                                            TAX_DEPOSITED_AMOUNT,
                                                                            RATE,
                                                                            ACTUAL_TAX_AMOUNT,
                                                                            REASON,
                                                                            DESCRIPTION,
                                                                            SECTION_ID,
                                                                            COMPANY_RATE,
                                                                            NON_COMPANY_RATE,
                                                                            INVALID_PAN_RATE)";

                //---------------------------------------------------------
                //----- SHORT DEDUCTION SQL 
                //---------------------------------------------------------
                strSQL = @"            SELECT MST_COMPANY.COMPANY_ID,
                                              MST_COMPANY.COMPANY_NAME,
                                              MST_ASSESSMENT.FA_YEAR,
                                              TRN_BASIC_INFO.QTR,
                                              TRN_BASIC_INFO.FORM_NO,
                                              TRN_DEDUCTEE_DETAILS.CHALLAN_ID, 
                                              TRN_CHALLAN.CHALLAN_NO,
                                              TRN_CHALLAN.SL_NO                                        AS CHALLAN_SL_NO,
                                              TRN_CHALLAN.DEPOSIT_DATE                                 AS CHALLAN_DEPOSIT_DATE, 
                                              TRN_DEDUCTEE_DETAILS.DEDUCTEE_DETAIL_ID,
                                              TRN_DEDUCTEE_DETAILS.PARTY_ID,
                                              TRN_DEDUCTEE_DETAILS.SL_NO                               AS DEDUCTEE_SL_NO," +
                                              strFieldEmployeeDeducteeName + " , " +
                                              strFieldEmployeeDeducteePAN + " , " +
                                            @"TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, 
                                              TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE, 
                                              TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT, 
                                              ROUND(TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT /
                                                    TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT * 100, 2)      AS CALC_RATE, 
                                              TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT, 
                                              IIF(MST_DEDUCTEE.DEDUCTEE_PAN = 'PANNOTAVBL' 
                                                         OR MST_DEDUCTEE.DEDUCTEE_PAN = 'PANAPPLIED' 
                                                         OR MST_DEDUCTEE.DEDUCTEE_PAN = 'PANINVALID', 
                                                  MST_NONSALARY_TAX_SLAB.INVALID_PAN_RATE,  
                                                       IIF(MID(MST_DEDUCTEE.DEDUCTEE_PAN, 4, 1) = 'C', 
                                                           MST_NONSALARY_TAX_SLAB.COMPANY_RATE, 
                                                           MST_NONSALARY_TAX_SLAB.NON_COMPANY_RATE)
                                                  )          AS RATE," +
                                              strActualAmtCreation + "                                  AS ACTUAL_TAX_AMOUNT," +
                                             @"MST_REASON.REASON, 
                                              MST_REASON.DESCRIPTION, 
                                              MST_NONSALARY_TAX_SLAB.SECTION_ID, 
                                              MST_NONSALARY_TAX_SLAB.COMPANY_RATE, 
                                              MST_NONSALARY_TAX_SLAB.NON_COMPANY_RATE, 
                                              MST_NONSALARY_TAX_SLAB.INVALID_PAN_RATE
                                       FROM   TRN_DEDUCTEE_DETAILS, 
                                              MST_DEDUCTEE, 
                                              MST_REASON, 
                                              MST_NONSALARY_TAX_SLAB,
                                              TRN_BASIC_INFO,
                                              TRN_CHALLAN,
                                              MST_COMPANY,
                                              MST_ASSESSMENT
                                       WHERE  TRN_DEDUCTEE_DETAILS.PARTY_ID       = " + strFieldEmployeeDeducteeJoinCondition + "    " +
                                     @"AND    TRN_DEDUCTEE_DETAILS.CHALLAN_ID     = TRN_CHALLAN.CHALLAN_ID                                       
                                       AND    TRN_CHALLAN.BASIC_INFO_ID           = TRN_BASIC_INFO.BASIC_INFO_ID                                       
                                       AND    TRN_DEDUCTEE_DETAILS.REASON_ID      = MST_REASON.REASON_ID 
                                       AND    TRN_DEDUCTEE_DETAILS.SECTION_ID     = MST_NONSALARY_TAX_SLAB.SECTION_ID 
                                       AND    TRN_BASIC_INFO.COMPANY_ID           = MST_COMPANY.COMPANY_ID
                                       AND    TRN_BASIC_INFO.ASST_ID              = MST_ASSESSMENT.ASST_ID 
                                       AND    TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE BETWEEN MST_NONSALARY_TAX_SLAB.FROM_DATE AND MST_NONSALARY_TAX_SLAB.TO_DATE 
                                       AND    TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE IS NOT NULL";
                if (CompanyId > 0)
                    strSQL = strSQL + " AND TRN_BASIC_INFO.COMPANY_ID = " + CompanyId + "  ";
                if (AsstId > 0)
                    strSQL = strSQL + " AND TRN_BASIC_INFO.ASST_ID = " + AsstId + "  ";
                if (Qtr != "")
                    strSQL = strSQL + " AND TRN_BASIC_INFO.QTR = '" + Qtr + "' ";
                if (FormNo != "")
                    strSQL = strSQL + " AND TRN_BASIC_INFO.FORM_NO = '" + FormNo + "' ";

                strSQL = strSQL + @"    AND   TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT < " + strActualAmtCreation +
                                  @"ORDER BY TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE, 
                                             TRN_DEDUCTEE_DETAILS.DEDUCTEE_DETAIL_ID ";

                #region PREVIOUS SQL [COMMENTED CODE ]

                //---------------------------------------------------------
                //            //----- SHORT DEDUCTION SQL 
                //            //---------------------------------------------------------
                //            strSQL = @"SELECT  BASEQUERY.COMPANY_NAME,
                //                               BASEQUERY.FA_YEAR,
                //                               BASEQUERY.QTR,
                //                               BASEQUERY.FORM_NO,
                //                               BASEQUERY.CHALLAN_ID, 
                //                               BASEQUERY.CHALLAN_NO,
                //                               BASEQUERY.PAYMENT_DATE, 
                //                               BASEQUERY.DEDUCTEE_DETAIL_ID, 
                //                               BASEQUERY.DEDUCTEE_SERIAL_NO,                               
                //                               BASEQUERY.PARTY_ID, 
                //                               BASEQUERY.DEDUCTEE_NAME,
                //                               BASEQUERY.DEDUCTED_DATE, 
                //                               BASEQUERY.PAYMENT_AMOUNT, 
                //                               BASEQUERY.REASON, 
                //                               BASEQUERY.DESCRIPTION, 
                //                               BASEQUERY.SECTION_ID, 
                //                               BASEQUERY.COMPANY_RATE, 
                //                               BASEQUERY.NON_COMPANY_RATE, 
                //                               BASEQUERY.INVALID_PAN_RATE, 
                //                               BASEQUERY.TAX_DEPOSITED_AMOUNT,  
                //                               BASEQUERY.DEDUCTEE_PAN,
                //                               BASEQUERY.RATE,
                //                               BASEQUERY.ACTUAL_TAX_AMOUNT
                //                       FROM 
                //                       (
                //                           SELECT MST_COMPANY.COMPANY_ID,
                //                                  MST_COMPANY.COMPANY_NAME,
                //                                  MST_ASSESSMENT.FA_YEAR,
                //                                  TRN_BASIC_INFO.QTR,
                //                                  TRN_BASIC_INFO.FORM_NO,
                //                                  TRN_DEDUCTEE_DETAILS.CHALLAN_ID, 
                //                                  TRN_CHALLAN.CHALLAN_NO,
                //                                  TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, 
                //                                  TRN_DEDUCTEE_DETAILS.DEDUCTEE_DETAIL_ID,
                //                                  TRN_DEDUCTEE_DETAILS.SL_NO                                      AS DEDUCTEE_SERIAL_NO,      
                //                                  TRN_DEDUCTEE_DETAILS.PARTY_ID,
                //                                  TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE, 
                //                                  TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT, 
                //                                  ROUND(TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT /
                //                                        TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT * 100, 2)             AS CALC_RATE, 
                //                                  TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT, 
                //                                  MST_DEDUCTEE.DEDUCTEE_PAN,                              
                //                                  MST_DEDUCTEE.DEDUCTEE_NAME, 
                //                                  IIF(MST_DEDUCTEE.DEDUCTEE_PAN = 'PANNOTAVBL' 
                //                                             OR MST_DEDUCTEE.DEDUCTEE_PAN = 'PANAPPLIED' 
                //                                             OR MST_DEDUCTEE.DEDUCTEE_PAN = 'PANINVALID', 
                //                                      MST_NONSALARY_TAX_SLAB.INVALID_PAN_RATE,  
                //                                           IIF(MID(MST_DEDUCTEE.DEDUCTEE_PAN, 3, 1) = 'C', 
                //                                               MST_NONSALARY_TAX_SLAB.COMPANY_RATE, 
                //                                               MST_NONSALARY_TAX_SLAB.NON_COMPANY_RATE)
                //                                      )          AS RATE, 
                //                                  IIF(MST_DEDUCTEE.DEDUCTEE_PAN = 'PANNOTAVBL' 
                //                                             OR MST_DEDUCTEE.DEDUCTEE_PAN = 'PANAPPLIED' 
                //                                             OR MST_DEDUCTEE.DEDUCTEE_PAN = 'PANINVALID', 
                //                                      ROUND((TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT * MST_TDS_NONSALARY_SLAB.INVALID_PAN_RATE ) / 100,0), 
                //                                           IIF(MID(MST_DEDUCTEE.DEDUCTEE_PAN, 3, 1) = 'C', 
                //                                               ROUND((TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT * MST_TDS_NONSALARY_SLAB.COMPANY_RATE ) / 100,0), 
                //                                               ROUND((TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT * MST_TDS_NONSALARY_SLAB.NON_COMPANY_RATE ) / 100,0))
                //                                      ) AS ACTUAL_TAX_AMOUNT,
                //                                  MST_REASON.REASON, 
                //                                  MST_REASON.DESCRIPTION, 
                //                                  MST_TDS_NONSALARY_SLAB.SECTION_ID, 
                //                                  MST_TDS_NONSALARY_SLAB.COMPANY_RATE, 
                //                                  MST_TDS_NONSALARY_SLAB.NON_COMPANY_RATE, 
                //                                  MST_TDS_NONSALARY_SLAB.INVALID_PAN_RATE
                //                           FROM   TRN_DEDUCTEE_DETAILS, 
