        #region GET DEDUCTED AMOUNT
        //Added by Dhrub on 30/10/2012
        #region T_GetDeductedAmount [1]
        public double T_GetDeductedAmount(string Form, string EmployeeName, string PAN, long CompanyID, out double TaxableAmount)
        {
            return T_GetDeductedAmount(dmlService.J_pCommand, Form, EmployeeName, PAN, CompanyID, out TaxableAmount);
        }
        #endregion

        #region T_GetDeductedAmount [2]
        //Added by Dhrub on 30/10/2012
        public double T_GetDeductedAmount(IDbCommand command, string Form, string EmployeeName, string PAN, long CompanyID, out double TaxableAmount)
        {
            IDataReader drdDeductedAmtRecord = null;
            double dblTaxDepositedAmount=0;

            TaxableAmount = 0;

            // get employee id
            strSQL = @"SELECT EMPLOYEE_ID
                       FROM   MST_EMPLOYEE
                       WHERE  EMPLOYEE_PAN ='" + cmnService.J_ReplaceQuote(PAN) + @"' " + 
                       //AND    EMPLOYEE_NAME='" + cmnService.J_ReplaceQuote(EmployeeName) + @"'
                       @" AND    COMPANY_ID   = " + TDSMAN.T_pCompanyId + @" ";
            long lngEMPLOYEE_ID = cmnService.J_ReturnInt64Value(dmlService.J_ExecSqlReturnScalar(command, strSQL));

            if (lngEMPLOYEE_ID.ToString() == "") return 0;

            if (cmnService.J_ReplaceQuote(EmployeeName)=="" || cmnService.J_ReplaceQuote(PAN)=="") return 0;

            strSQL = @"SELECT " + cmnService.J_SQLDBFormat("SUM(TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT)", J_ColumnType.Double, J_SQLColFormat.NullCheck) + @" AS TAX_DEPOSITED_AMOUNT_T ,
                              " + cmnService.J_SQLDBFormat("SUM(TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT)", J_ColumnType.Double, J_SQLColFormat.NullCheck) + @" AS PAYMENT_AMOUNT_T
                       FROM   TRN_BASIC_INFO,
                              TRN_CHALLAN,
                              TRN_DEDUCTEE_DETAILS,
                              MST_EMPLOYEE
                       WHERE  TRN_BASIC_INFO.BASIC_INFO_ID       = TRN_CHALLAN.BASIC_INFO_ID
                       AND    TRN_CHALLAN.CHALLAN_ID             = TRN_DEDUCTEE_DETAILS.CHALLAN_ID 
                       AND    TRN_DEDUCTEE_DETAILS.PARTY_ID      = MST_EMPLOYEE.EMPLOYEE_ID
                       AND    TRN_BASIC_INFO.COMPANY_ID          = " + T_pCompanyId + @" 
                       AND    TRN_BASIC_INFO.ASST_ID             = " + T_pFinancialYearId + @"
                       AND    TRN_BASIC_INFO.FORM_NO             = '" + Form + @"' "+ @"
                       AND    MST_EMPLOYEE.EMPLOYEE_PAN          = '" + cmnService.J_ReplaceQuote(PAN) + @"'" + @"";
                       //AND    MST_EMPLOYEE.EMPLOYEE_NAME         = '" + cmnService.J_ReplaceQuote(EmployeeName) + @"'                     
                       //AND    MST_EMPLOYEE.EMPLOYEE_ID           = " + lngEMPLOYEE_ID + @"";

            drdDeductedAmtRecord = dmlService.J_ExecSqlReturnReader(strSQL);
            if (drdDeductedAmtRecord == null)
            {
                return 0;
            }
            while (drdDeductedAmtRecord.Read())
            {
                TaxableAmount = Convert.ToDouble(Convert.ToString(drdDeductedAmtRecord["PAYMENT_AMOUNT_T"]));
                dblTaxDepositedAmount= Convert.ToDouble(Convert.ToString(drdDeductedAmtRecord["TAX_DEPOSITED_AMOUNT_T"]));
            }
            drdDeductedAmtRecord.Close();
            drdDeductedAmtRecord.Dispose();
            return dblTaxDepositedAmount;
        }
         #endregion

        #endregion

        #region CalcLastDateofMonth
        public string CalcLastDateofMonth(string InputDate)
        {
            try
            {
                string strLastDate = "";
                //strSQL = @"SELECT  Format(" + cmnService.J_DateOperator() + dtService.J_ConvertddMMyyyy(InputDate) + cmnService.J_DateOperator() + " ," + "\"DD/MM/YYYY\"" + ")AS INPUT_DATE," +
                //                  "DATEADD(" + "\"D\"" + ",-1," + "01 + Format(DATEADD(" + "\"M\"" + ",1," + cmnService.J_DateOperator() + dtService.J_ConvertddMMyyyy(InputDate) + cmnService.J_DateOperator() + ")," + "\"/mm/YYYY\"" + ")) AS  LAST_DATE ";

                //DateTime origDT = Convert.ToDateTime(InputDate);
                //DateTime lastDate = new DateTime(origDT.Year, origDT.Month, 1).AddMonths(1).AddDays(-1);

                DateTime origDT = DateTime.Parse(InputDate);
                DateTime lastDate = new DateTime(origDT.Year, origDT.Month, 1).AddMonths(1).AddDays(-1);
                strLastDate = Convert.ToString(lastDate);
                return strLastDate;
            }
            catch (Exception err)
            {
                cmnService.J_UserMessage(err.Message);
                return "";
            }
        }
        #endregion 

