        #region LockBasicInfoEntry
        public bool LockBasicInfoEntry(string strModule)
        {
            IDataReader drdShowRecord = null;
            string strUserName = ""; string strModuleName = ""; string strLastUpdatedTime = "";
            //long lngInterval = 1; //1 minute interval
            //BasicInfo has entry in TEMP_STACK_BASIC_INFO from last transaction if any...
            strSQL = @"SELECT COUNT(BASIC_INFO_ID) FROM TEMP_STACK_BASIC_INFO 
                       WHERE  BASIC_INFO_ID = " + TDSMAN.T_pBasicInfoId + " " +
                     @"AND    USER_SERIAL   ='" + TDSMAN.T_pProductSerial + "'";
            if (cmnService.J_NullToZero(dmlService.J_ExecSqlReturnScalar(dmlService.J_pCommand, strSQL)) > 0)
            {
                //dmlService.J_BeginTransaction();
                strSQL = @"DELETE FROM TEMP_STACK_BASIC_INFO WHERE USER_SERIAL = '" + TDSMAN.T_pProductSerial + "'";
                dmlService.J_ExecSql(dmlService.J_pCommand, strSQL);
                //dmlService.J_Commit();
            }
            //
            strSQL = @"SELECT COUNT(BASIC_INFO_ID) FROM TEMP_STACK_BASIC_INFO
                       WHERE  BASIC_INFO_ID = " + TDSMAN.T_pBasicInfoId + @"
                       AND    USER_SERIAL  <>'" + TDSMAN.T_pProductSerial + "'";
            //================================
            if (cmnService.J_NullToZero(dmlService.J_ExecSqlReturnScalar(dmlService.J_pCommand, strSQL)) > 0)
            {
                //-- GET LOGGED USER NAME
                #region GET LOGGED USER NAME
                strSQL = @"SELECT   BASIC_INFO_ID,
                                    USER_SERIAL, 
                                    USER_NAME, 
                                    MODULE_NAME, 
                                    LAST_UPDATED_TIME, 
                                    LOGIN_TIME 
                           FROM     TEMP_STACK_BASIC_INFO
                           WHERE    BASIC_INFO_ID = " + TDSMAN.T_pBasicInfoId;
                //
                drdShowRecord = dmlService.J_ExecSqlReturnReader(dmlService.J_pCommand, strSQL);
                if (drdShowRecord == null)
                    return false;
                //
                while (drdShowRecord.Read())
                {
                    strUserName = Convert.ToString(drdShowRecord["USER_NAME"]);
                    strModuleName = Convert.ToString(drdShowRecord["MODULE_NAME"]);
                    strLastUpdatedTime = Convert.ToString(drdShowRecord["LAST_UPDATED_TIME"]);
                }
                drdShowRecord.Close();
                drdShowRecord.Dispose();
                #endregion
                //
//                strSQL = @"SELECT DATEDIFF('n',LAST_UPDATED_TIME,CDATE('" + GetServerDateTime() + @"'))
//                           FROM   TEMP_STACK_BASIC_INFO
//                           WHERE  BASIC_INFO_ID = " + TDSMAN.T_pBasicInfoId;
                if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                    strSQL = @"SELECT DATEDIFF(N,LAST_UPDATED_TIME," + GetServerDateTime() + @")
                           FROM   TEMP_STACK_BASIC_INFO
                           WHERE  BASIC_INFO_ID = " + TDSMAN.T_pBasicInfoId;
                else if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer) if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                        strSQL = @"SELECT DATEDIFF('n',LAST_UPDATED_TIME,CDATE('" + GetServerDateTime() + @"'))
                           FROM   TEMP_STACK_BASIC_INFO
                           WHERE  BASIC_INFO_ID = " + TDSMAN.T_pBasicInfoId;

                if (cmnService.J_NullToZero(dmlService.J_ExecSqlReturnScalar(dmlService.J_pCommand, strSQL)) > (2 * TDSMAN.T_pLockInterval)) //1 minute interval
                {
                    if (cmnService.J_UserMessage("This Return was used by one user. \n " +
                    "Which has not responded, \n " +
                    "Do you want to proceed with his/her \n " +
                    "Return?", MessageBoxButtons.YesNo, MessageBoxIcon.Information) == DialogResult.Yes)
                    {
                        //dmlService.J_BeginTransaction();
                        strSQL = @"DELETE FROM TEMP_STACK_BASIC_INFO WHERE BASIC_INFO_ID = " + TDSMAN.T_pBasicInfoId;
                        dmlService.J_ExecSql(dmlService.J_pCommand, strSQL);
                        //dmlService.J_Commit();
                    }
                    else
                    {
                        return false;
                    }
                }
                else
                {
                    //cmnService.J_UserMessage("Some other User is already working in this Return.", MessageBoxIcon.Information);
                    cmnService.J_UserMessage("Return is already in use. \n User : " +
                    strUserName + " \n Module : " +
                    strModuleName + " \n Logged in since : " +
                    strLastUpdatedTime, MessageBoxIcon.Information);
                    return false;
                }
            }
            //===============================
            //dmlService.J_BeginTransaction();
            //
            strSQL = @"DELETE FROM TEMP_STACK_BASIC_INFO WHERE USER_SERIAL = '" + TDSMAN.T_pProductSerial + "'";
            dmlService.J_ExecSql(dmlService.J_pCommand, strSQL);
            //
            strSQL = @"SELECT COUNT(BASIC_INFO_ID) FROM TEMP_STACK_BASIC_INFO
                       WHERE  BASIC_INFO_ID = " + TDSMAN.T_pBasicInfoId;
            if (cmnService.J_NullToZero(dmlService.J_ExecSqlReturnScalar(dmlService.J_pCommand, strSQL)) == 0)
            {
                strSQL = @"INSERT INTO TEMP_STACK_BASIC_INFO (
                            BASIC_INFO_ID, 
                            USER_SERIAL, 
                            USER_NAME, 
                            MODULE_NAME, 
                            LAST_UPDATED_TIME, 
                            LOGIN_TIME) " +
                         @"VALUES (" + TDSMAN.T_pBasicInfoId + ", " +
                         @" '" + TDSMAN.T_pProductSerial + "'," +
                         @" '" + TDSMAN.T_pProductUser + "'," +
                         @" '" + strModule + "'," +
                         @" " + GetServerDateTime() + "," +
                         @" " + GetServerDateTime() + ")";
                //
                dmlService.J_ExecSql(dmlService.J_pCommand, strSQL);
            }
            else
            {
                strSQL = @"SELECT   BASIC_INFO_ID,
                                    USER_SERIAL, 
                                    USER_NAME, 
                                    MODULE_NAME, 
                                    LAST_UPDATED_TIME, 
                                    LOGIN_TIME 
                           FROM     TEMP_STACK_BASIC_INFO
                           WHERE    BASIC_INFO_ID = " + TDSMAN.T_pBasicInfoId;
                //
                drdShowRecord = dmlService.J_ExecSqlReturnReader(dmlService.J_pCommand, strSQL);
                if (drdShowRecord == null)
                    return false;
                //
                while (drdShowRecord.Read())
                {
                    cmnService.J_UserMessage("Return is already in use. \n User : " +
                    Convert.ToString(drdShowRecord["USER_NAME"]) + " \n Module : " +
                    Convert.ToString(drdShowRecord["MODULE_NAME"]) + " \n Logged in since : " +
                    Convert.ToString(drdShowRecord["LAST_UPDATED_TIME"]), MessageBoxIcon.Information);
                }
                drdShowRecord.Close();
                drdShowRecord.Dispose();
                //dmlService.J_Rollback();
                return false;
            }
            //dmlService.J_Commit();
            return true;
        }
        #endregion

        #region LockBasicInfoEntry - CORRECTION
        public bool LockBasicInfoEntry(string strModule, bool blnCorrection)
        {
            IDataReader drdShowRecord = null;
            string strUserName = ""; string strModuleName = ""; string strLastUpdatedTime = "";
            int intCorrection = 0;
            if (blnCorrection == true)
                intCorrection = 1;
            //long lngInterval = 1; //1 minute interval
            //BasicInfo has entry in TEMP_STACK_BASIC_INFO
            strSQL = @"SELECT COUNT(BASIC_INFO_ID) FROM TEMP_STACK_BASIC_INFO 
                       WHERE  BATCH_ID         = " + TDSMAN.T_pBasicInfoId + @"
                       AND    USER_SERIAL       ='" + TDSMAN.T_pProductSerial + @"'
                       AND    CORRECTION_RETURN = " + intCorrection + @"
                       AND    MODULE_NAME       ='" + strModule + @"'";
            if (cmnService.J_NullToZero(dmlService.J_ExecSqlReturnScalar(dmlService.J_pCommand, strSQL)) > 0)
            {
                //dmlService.J_BeginTransaction();
                strSQL = @"DELETE FROM TEMP_STACK_BASIC_INFO 
                           WHERE  USER_SERIAL    ='" + TDSMAN.T_pProductSerial + @"' 
                           AND    CORRECTION_RETURN = " + intCorrection + @"
                           AND    MODULE_NAME    ='" + strModule + @"'";
                dmlService.J_ExecSql(dmlService.J_pCommand, strSQL);
                //dmlService.J_Commit();
            }
            //
            //Modified by Indrajit on 26-02-2013
            //strSQL = "SELECT COUNT(BASIC_INFO_ID) FROM TEMP_STACK_BASIC_INFO " +
            // "WHERE (BASIC_INFO_ID = " + TDSMAN.T_pBasicInfoId + " " +
            // "OR BASIC_INFO_ID = 0) " +
            // "AND PRINT_USER_SERIAL <> '" + TDSMAN.T_pProductSerial + "'";
            if (TDSMAN.T_pBasicInfoId == 0)
                strSQL = @"SELECT COUNT(BATCH_ID) FROM TEMP_STACK_BASIC_INFO 
                           WHERE  USER_SERIAL       <> '" + TDSMAN.T_pProductSerial + @"' 
                           AND    CORRECTION_RETURN = " + intCorrection + @"
                           AND    MODULE_NAME       ='" + strModule + @"'";
            else
