        #region CheckAdminUser
        public bool CheckAdminUser()
        {
            //bool value to hold our return value
            bool isAdminUser = false;
            //
            try
            {
                if (TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_EDITION || TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_LITE_EDITION || TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_ULTIMATE_EDITION) //-- 2016/01/29 //-- 2021/01/13
                {
                    if (TDSMAN.T_ClientServerMachine == T_CLIENT_SERVER_MACHINE.SERVER_MACHINE)
                        isAdminUser = true;
                    else if (TDSMAN.T_ClientServerMachine == T_CLIENT_SERVER_MACHINE.CLIENT_MACHINE)
                        isAdminUser = false;
                }
                else
                {

                if (cmnService.J_IsFileExist(Path.Combine(Application.StartupPath, Path.ChangeExtension(Path.Combine(Application.StartupPath, J_Var.J_pMsAccessDatabaseName), "ldb"))) == true)
                    isAdminUser = true;
                else
                    isAdminUser = false;
                }
            }
            catch
            {
                isAdminUser = false;
            }
            return isAdminUser;
        }

        #endregion

