        #region RenameDatabase
        public void RenameDatabase(string DataBaseName)
        {
            try
            {
                dmlService.Dispose();
                //--
                if (File.Exists(Path.Combine(Application.StartupPath, DataBaseName)) == true)
                    File.Move(Path.Combine(Application.StartupPath, DataBaseName), Path.Combine(Application.StartupPath, string.Format("{0:ddMMyy}", System.DateTime.Now.Date) + "_" + string.Format("{0:HHmmss}", System.DateTime.Now) + "_TDSMAN.mdb"));
            }
            catch (Exception err)
            {
                //return false;
            }

        }
