        #region GetDatabasePathExists
        public bool GetDatabasePathExists()
        {
            DataSet dtSet = null;
            try
            {
                if (dtSet != null) dtSet.Clear();
                dtSet = dmlService.J_ConvertXmlToDataSet(Application.StartupPath + "/" + J_Var.J_pXmlConnectionFileName);
                if (dtSet == null)
                {
                    dmlService.Dispose();
                    return false;
                }
                //
                string strPath = Path.Combine(cmnService.J_Decode(dtSet.Tables[0].Rows[0][cmnService.J_Encode("DATABASENAME")].ToString()), J_Var.J_pMsAccessDatabaseName);
                if (File.Exists(strPath) == true)
                    return true;
                else
                    return false;
            }
            catch
            {
                return false;
            }
        }
        #endregion

