        #region GetMachineID
        public void GetMachineID()
        {
            DataSet dtSet = null;
            //string ServerName = "";
            string MachineName = "";
            try
            {
                if (TDSMAN.T_ClientServerMachine == T_CLIENT_SERVER_MACHINE.CLIENT_MACHINE)
                {
                    MachineName = cmnService.J_GetRegistryKeyValue(T_pCompanyName + "\\" + this.GetRegistryFolder(), T_RegistrationInfo.Licensee_Name.ToString());
                    //--
                    if (dtSet != null) dtSet.Clear();
                    dtSet = dmlService.J_ConvertXmlToDataSet(Application.StartupPath + "/" + J_Var.J_pXmlConnectionFileName);
                    if (dtSet == null)
                    {
                        dmlService.Dispose();
                        TDSMAN.T_MACHINE_ID = 0;
                    }
                    //
                    string strPath ="";
                    if (TDSMAN.T_PackageType == T_PACKAGE_TYPE.MULTI_USER &&
                        TDSMAN.T_ClientServerMachine == T_CLIENT_SERVER_MACHINE.CLIENT_MACHINE &&
                        (TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_EDITION //-- 2016/01/29
                        || TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_LITE_EDITION
                        || TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_ULTIMATE_EDITION
                        )) //-- 2021/01/13
                    {
                        strPath = cmnService.J_Decode(dtSet.Tables[0].Rows[0][cmnService.J_Encode("SERVERPATH")].ToString());
                    }
                    else
                    {
                    strPath = cmnService.J_Decode(dtSet.Tables[0].Rows[0][cmnService.J_Encode("DATABASENAME")].ToString());
                    }
                    //
                    XmlDocument XMLDoc = new XmlDocument();
                    XMLDoc.Load(strPath + "/" + TDSMAN.T_XmlConnectionFileNameServer);
                    //
                    XmlNodeList xnList = XMLDoc.GetElementsByTagName(T_XML.NODE);
                    //
                    foreach (XmlNode xn in xnList)
                    {
                        if (MachineName.ToUpper() == cmnService.J_Decode(xn[T_XML.MACHINENAME].InnerText).ToUpper())
                        {
                            TDSMAN.T_MACHINE_ID = cmnService.J_ReturnInt32Value(cmnService.J_Decode(xn[T_XML.MACHINENO].InnerText).ToUpper());
                            return;
                        }
                    }
                    //
                    return;
                }
                else if (TDSMAN.T_ClientServerMachine == T_CLIENT_SERVER_MACHINE.SERVER_MACHINE)
                {
                    TDSMAN.T_MACHINE_ID = 1;
                    return;
                }
            }
            catch //(Exception err)
            {
                TDSMAN.T_MACHINE_ID = 0;
                return;
            }
        }
        #endregion

