        #region KillProcess
        public bool KillProcess()
        {
            try
            {
                if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                {
                    SqlConnection cn = new SqlConnection(dmlService.J_pConnectionString);
                    cn.Open();
                    DataTable dt = cn.GetSchema("tables");
                    for (int i = 0; i <= dt.Rows.Count - 1; i++)
                    {
                        if (Convert.ToString(dt.Rows[i]["TABLE_NAME"]).Trim().ToUpper().Substring(0, 4) == "TEMP")
                        {
                            strSQL = "DELETE FROM " + Convert.ToString(dt.Rows[i]["TABLE_NAME"]).Trim();
                            dmlService.J_ExecSql(strSQL, J_SQLType.DDL);
                        }
                    }
                    //
                    dt.Dispose();
                    cn.Dispose();
                    //--
                    cn.Close();
                }
                else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                {
                    OleDbConnection cn = new System.Data.OleDb.OleDbConnection(dmlService.J_pConnectionString);
                    cn.Open();
                    DataTable dt = cn.GetSchema("tables");
                    for (int i = 0; i <= dt.Rows.Count - 1; i++)
                    {
                        if (Convert.ToString(dt.Rows[i]["TABLE_NAME"]).Trim().ToUpper().Substring(0, 4) == "TEMP")
                        {
                            strSQL = "DELETE FROM " + Convert.ToString(dt.Rows[i]["TABLE_NAME"]).Trim();
                            dmlService.J_ExecSql(strSQL, J_SQLType.DDL);
                        }
                    }
                    //
                    dt.Dispose();
                    cn.Dispose();
                    //--
                    //strSQL = "DELETE FROM TRN_STACK_PRINT";
                    //dmlService.J_ExecSql(strSQL, J_SQLType.DDL);
                    //--
                    cn.Close();
                    //
                }
                cmnService.J_UserMessage("All the returns are now unlocked.", MessageBoxIcon.Information);
                return true;
            }
            catch (Exception err)
            {
                cmnService.J_UserMessage(err.Message);
                return false;
            }
        }
        #endregion
        //--
        //TO RUN ANY DOS COMMAND
        //Currently not in use
        #region ExecuteCommandSync
        public string ExecuteCommandSync(string command)
        {
            try
            {
                // create the ProcessStartInfo using "cmd" as the program to be run,
                // and "/c " as the parameters.
                // Incidentally, /c tells cmd that we want it to execute the command that follows,
                // and then exit.
                System.Diagnostics.ProcessStartInfo procStartInfo =
                    new System.Diagnostics.ProcessStartInfo("cmd", "/c " + command);

                // The following commands are needed to redirect the standard output.
                // This means that it will be redirected to the Process.StandardOutput StreamReader.
                procStartInfo.RedirectStandardOutput = true;
                procStartInfo.UseShellExecute = false;
                // Do not create the black window.
                procStartInfo.CreateNoWindow = true;
                // Now we create a process, assign its ProcessStartInfo and start it
                System.Diagnostics.Process proc = new System.Diagnostics.Process();
                proc.StartInfo = procStartInfo;
                proc.Start();
                // Get the output into a string
                string result = proc.StandardOutput.ReadToEnd();
                // Display the command output.

                string[] a = J_Var.J_pDBPath.Split(new string[] { "\\" }, StringSplitOptions.None);
                //MessageBox.Show(result.Substring(16 + 2 + a[2].Trim().Length + 4, 18));

                //NET TIME \\COMPUTERNAME returns as following
                //Current time at \\pds1 is 26/09/2012 2:20 PM
                //
                //The command completed successfully.

                result = result.Substring(16 + 2 + a[2].Trim().Length + 4, 18);
                return result;
            }
            catch (Exception objException)
            {
                cmnService.J_UserMessage(objException.Message);
                return "";
            }
        }
        #endregion

