        #region CreateXMLFileForSERVER
        public void CreateXMLFileForSERVER(string PathWithFileName, string ProductSerialNo, string ProductVersion, string ServerName, string ServerEdition)
        {
            if (File.Exists(PathWithFileName))
            {
                XmlDocument XMLDoc = new XmlDocument();
                XMLDoc.Load(PathWithFileName);
                //
                //XMLDoc.SelectSingleNode("MULTIUSERCONNECTION/SERIAL").InnerText = ProductSerialNo;
                XMLDoc.SelectSingleNode(T_XML.MULTIUSERCONNECTION + "/" + T_XML.SERIAL).InnerText = cmnService.J_Encode(ProductSerialNo);
                XMLDoc.Save(PathWithFileName);
                //
                //XMLDoc.SelectSingleNode("MULTIUSERCONNECTION/VERSION").InnerText = ProductVersion;
                XMLDoc.SelectSingleNode(T_XML.MULTIUSERCONNECTION + "/" + T_XML.VERSION).InnerText = cmnService.J_Encode(ProductVersion);
                XMLDoc.Save(PathWithFileName);
                //
                XMLDoc.SelectSingleNode(T_XML.MULTIUSERCONNECTION + "/" + T_XML.SERVERNAME).InnerText = cmnService.J_Encode(ServerName);
                XMLDoc.Save(PathWithFileName);
                //
                XMLDoc.SelectSingleNode(T_XML.MULTIUSERCONNECTION + "/" + T_XML.SERVEREDITION).InnerText = cmnService.J_Encode(ServerEdition);
                XMLDoc.Save(PathWithFileName);
            }
            else
            {
                //
                File.Create(PathWithFileName).Close();
                //
                XmlDocument XMLDoc = new XmlDocument();
                //XMLDoc.Load(PathWithFileName);
                //
                XmlNode Root = XMLDoc.AppendChild(XMLDoc.CreateElement(T_XML.MULTIUSERCONNECTION));
                XmlNode Child = Root.AppendChild(XMLDoc.CreateElement(T_XML.SERIAL));
                //XmlAttribute ChildAtt = Child.Attributes.Append(XMLDoc.CreateAttribute("Attribute"));
                //ChildAtt.InnerText = "My innertext";
                Child.InnerText = cmnService.J_Encode(ProductSerialNo);
                //
                Child = Root.AppendChild(XMLDoc.CreateElement(T_XML.VERSION));
                Child.InnerText = cmnService.J_Encode(ProductVersion);
                //
                Child = Root.AppendChild(XMLDoc.CreateElement(T_XML.ALLOWEDNODES));
                //Child.InnerText = cmnService.J_Encode("2");
                Child.InnerText = cmnService.J_Encode("0"); //-- 2020/02/05
                //
                Child = Root.AppendChild(XMLDoc.CreateElement(T_XML.SERVERNAME));
                Child.InnerText = cmnService.J_Encode(ServerName);
                //
                Child = Root.AppendChild(XMLDoc.CreateElement(T_XML.SERVEREDITION)); //-- 2015-02-06
                Child.InnerText = cmnService.J_Encode(ServerEdition);
                //
                Child = Root.AppendChild(XMLDoc.CreateElement(T_XML.NODEDETAILS));
                Child.InnerText = "";
                ////
                //XmlNode Child1 = Child.AppendChild(XMLDoc.CreateElement(T_XML.NODE1));
                //XmlNode Child2 = Child1.AppendChild(XMLDoc.CreateElement(T_XML.MACHINENAME));
                //Child2 = Child1.AppendChild(XMLDoc.CreateElement(T_XML.MACHINENO));
                ////
                //Child1 = Child.AppendChild(XMLDoc.CreateElement(T_XML.NODE2));
                //Child2 = Child1.AppendChild(XMLDoc.CreateElement(T_XML.MACHINENAME));
                //Child2 = Child1.AppendChild(XMLDoc.CreateElement(T_XML.MACHINENO));
                //
                XMLDoc.Save(PathWithFileName);
            }
        }
