        #region AllowClientRegistration
        public bool AllowClientRegistration(string PathWithFileName, int AllowedNodes)
        {
            try
            {
                //
                if (File.Exists(PathWithFileName))
                {
                    XmlDocument XMLDoc = new XmlDocument();
                    XMLDoc.Load(PathWithFileName);
                    //
                    int NodesCount = 0;
                    XmlNode Root = XMLDoc.SelectSingleNode(T_XML.MULTIUSERCONNECTION + "/" + T_XML.NODEDETAILS);
                    //
                    NodesCount = Root.ChildNodes.Count;
                    //
                    if (NodesCount >= AllowedNodes)
                        return false;
                    else
                        return true;
                }
                else
                    return false;
            }
            catch
            {
                return false;
            }
        }
