                XMLDoc.Load(PathWithFileName);
                //
                XmlNode Root = XMLDoc.SelectSingleNode(T_XML.MULTIUSERCONNECTION + "/" + T_XML.NODEDETAILS);
                XmlNode Parent = Root.AppendChild(XMLDoc.CreateElement(T_XML.NODE));
