        #region MatchMachineName
        public bool MatchMachineName(string PathWithFileName, string MachineName)
        {
            try
            {
                //
                if (File.Exists(PathWithFileName))
                {
                    XmlDocument XMLDoc = new XmlDocument();
                    XMLDoc.Load(PathWithFileName);
                    //
                    XmlNodeList xnList = XMLDoc.GetElementsByTagName(T_XML.NODE);
                    //
                    foreach (XmlNode xn in xnList)
                    {
                        if (MachineName.ToUpper() == cmnService.J_Decode(xn[T_XML.MACHINENAME].InnerText).ToUpper())
                            return false;
                    }
                    return true;
                    //
                }
                else
                    return false;
            }
            catch
            {
                return false;
