        #region GetServerVersion
        public string GetServerVersion()
        {
            DataSet dtSet = null;
            string ServerVersion = "";
            try
            {
                if (dtSet != null) dtSet.Clear();
                dtSet = dmlService.J_ConvertXmlToDataSet(Application.StartupPath + "/" + J_Var.J_pXmlConnectionFileName);
                if (dtSet == null)
                {
                    dmlService.Dispose();
                    return "";
                }
                //
                string strPath ="";
                if (TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_EDITION || TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_LITE_EDITION || TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_ULTIMATE_EDITION)
                    strPath = cmnService.J_Decode(dtSet.Tables[0].Rows[0][cmnService.J_Encode("SERVERPATH")].ToString());
                else
                    strPath = cmnService.J_Decode(dtSet.Tables[0].Rows[0][cmnService.J_Encode("DATABASENAME")].ToString());
                //
                XmlDocument XMLDoc = new XmlDocument();
                XMLDoc.Load(strPath + "/" + TDSMAN.T_XmlConnectionFileNameServer);
                //
                XmlNode Root = XMLDoc.SelectSingleNode(T_XML.MULTIUSERCONNECTION + "/" + T_XML.VERSION);
                ServerVersion = cmnService.J_Decode(Root.InnerText);

                if (ServerVersion == "")
                    return "0";
                else
                    return ServerVersion;
            }
            catch (Exception err)
            {
                return "";
            }
        }
