        //--
        #region GetServerDateTime 
        //-- 2016/01/29
        public string GetServerDateTime()
        {
            string strServerDT = "";
            if (TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_EDITION || TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_LITE_EDITION || TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_ULTIMATE_EDITION)
            {
                strServerDT= dmlService.J_ReturnServerDate();               
                //
                if (strServerDT == "")
                    strServerDT = "null";
                else
                    strServerDT = cmnService.J_DateOperator() + strServerDT + cmnService.J_DateOperator();
            }
            else
            {
                if (TDSMAN.T_PackageType == T_PACKAGE_TYPE.MULTI_USER)
                {
                    //Added by Indrajit on 26-09-2012 to get SERVER DATETIME
                    //string strServerDT = ExecuteCommandSync("net time \\\\Pds1");
                    //Added by Indrajit on 03-10-2012
                    if (GetServerName() != "")
                        strServerDT = cmnService.J_DateOperator() + RemoteDateTime(GetServerName()) + cmnService.J_DateOperator();

                    if (strServerDT == "")
                        strServerDT = "null";
                    //else
                    //{
                    //    strServerDT = "CDATE('" + strServerDT + "')";
                    //    strServerDT = strServerDT.Replace("AM", "");
                    //    strServerDT = strServerDT.Replace("PM", "");
                    //}
                }
                else if (TDSMAN.T_PackageType == T_PACKAGE_TYPE.SINGLE_USER)
                {
                    if (J_Var.J_pDBPath.Substring(0, 2) == "\\\\")
                    {
                        string svr = J_Var.J_pDBPath.Substring(0, J_Var.J_pDBPath.IndexOf("\\", 2)).Substring(2);
                        strServerDT = RemoteDateTime(svr);
                    }
                    else
                    {
                        strServerDT = DateTime.Now.ToString();
                    }
                    //--
                    if (strServerDT == "")
                        strServerDT = "null";
                    else
                        strServerDT = "CDATE('" + strServerDT + "')";
                }
            }
            //--
            return strServerDT;
        }

        #endregion
        //--
        #region GetServerDate
        //-- 2016/01/29
        public string GetServerDate()
        {
            string strServerDT = "";
            if (TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_EDITION || TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_LITE_EDITION || TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_ULTIMATE_EDITION)
            {
                strServerDT = dmlService.J_ReturnServerDate();
                //
                if (strServerDT == "")
                    strServerDT = "null";
                else
                    strServerDT = cmnService.J_DateOperator() + strServerDT + cmnService.J_DateOperator();
            }
            else
            {
                if (TDSMAN.T_PackageType == T_PACKAGE_TYPE.MULTI_USER)
                {
                    //Added by Indrajit on 26-09-2012 to get SERVER DATETIME
                    //string strServerDT = ExecuteCommandSync("net time \\\\Pds1");
                    //Added by Indrajit on 03-10-2012
                    if (GetServerName() != "")
                        strServerDT = cmnService.J_DateOperator() + RemoteDateTime(GetServerName()) + cmnService.J_DateOperator();

                    if (strServerDT == "")
                        strServerDT = "null";
                    //else
                    //{
                    //    strServerDT = "CDATE('" + strServerDT + "')";
                    //    strServerDT = strServerDT.Replace("AM", "");
                    //    strServerDT = strServerDT.Replace("PM", "");
                    //}
                }
                else if (TDSMAN.T_PackageType == T_PACKAGE_TYPE.SINGLE_USER)
                {
                    if (J_Var.J_pDBPath.Substring(0, 2) == "\\\\")
                    {
                        string svr = J_Var.J_pDBPath.Substring(0, J_Var.J_pDBPath.IndexOf("\\", 2)).Substring(2);
                        strServerDT = RemoteDateTime(svr);
                    }
                    else
                    {
                        strServerDT = DateTime.Now.ToString("dd/MM/yyyy");
                    }
                    //--
                    if (strServerDT == "")
                        strServerDT = "null";
                    else
                        strServerDT = "CDATE('" + strServerDT + "')";
                }
            }
            //--
            return strServerDT;
        }

