        #region T_GenerateRandomNumber
        public string T_GenerateRandomNumber()
        {
            Random rand = new Random((int)DateTime.Now.Ticks);
            int numIterations = 0;
            numIterations = rand.Next(10000000, 99999999);
            return numIterations.ToString();
        }
        #endregion

        #region T_GenerateActivationNumberMU
        public string T_GenerateActivationNumberMU(string SerialNoSU, string SerialNoMU)
        {
            try
            {
                string strConfigNo = "";
                string strConfigNoAscii = "";
                int intConfigNo = 0;
                //
                strConfigNo = SerialNoSU.ToUpper() + "TDSMAN" + SerialNoMU.ToUpper();
                //
                foreach (char c in strConfigNo)
                {
                    //strConfigNoAscii = strConfigNoAscii + (int)(c);
                    intConfigNo = intConfigNo + (int)(c);
                }
                //--
                intConfigNo = intConfigNo * 9999;             //-- decimal to 9999 * X
                strConfigNoAscii = intConfigNo.ToString("X"); //-- decimal to hex converter
                //--               
                return strConfigNoAscii;
            }
            catch
            {
                return "";
            }
        }
