        //-- GetSetup
        #region GetSetup
        public void GetSetup()
        {
            IDataReader drdGetSetup = null;
            //-----------------------------------------------------------
            /* (1) Column Value
             * (2) Column Data Type
             * (3) Replace String
             * (4) Replace String Data Type */
            //-----------------------------------------------------------
            //-----------------------------------------------------------
            try
            {
                //int intCURRENCY_ID = 0;
                //
                //string[,] strShowProxySettingsMatrix = {{"PROXY_SETTINGS = 0", "T", T_YES_NO.NO, "T"},
                //                                      {"PROXY_SETTINGS = 1", "T", T_YES_NO.YES, "T"}};
                //
                strSQL = "SELECT SetupId," +
                    //"            " + cmnService.J_SQLDBFormat(strShowProxySettingsMatrix, J_SQLColFormat.Case_End) + "   AS PROXY_SETTINGS," +
                    "            PROXY_SETTINGS," +
                    "            HOST_ADDRESS," +
                    "            HOST_PORT," +
                    "            HOST_USER_NAME," +
                    "            HOST_PASSWORD," +
                    "            SHOW_BOOKMARK," +
                    "            SHOW_DEDUCTED_DATE," +
                    "            COPY_INTEREST_ALLOCATED," +
                    "            SHOW_NONSALARY_TDS_RATE," +
                    "            SHOW_ALLOCATED_FIELDS, " +
                    "            SHOW_DEDUCTEE_COMPANY_WISE, " +
                    "            PROHIBIT_ZERO_TAX_DEDUCTION, " +
                    "            SHOW_REGULAR_DEDUCTEE_CORRECTION, " +
                    "            ALLOT_AUTOMATIC_REF_NO, " +
                    "            ENABLE_DEDUCTEE_FIRST," +
                    "            BACKUP_REMINDER_DAYS,  " +
                    "            ROUND_OFF_TAXABLE_AMOUNT,  " +
                    "            AUTO_CALCULATE_TDS_RATE,  " +
                    "            SHOW_COLUMNS_FORM16_PARTB,  " +
                    "            ENABLE_LOCK_RETURN,  " +
                    "            ENABLE_REFERENCE_NO,  " +
                    "            SHARE_REFERENCE_NO_F24Q,  " +
                    "            SHARE_REFERENCE_NO_F26Q,  " +
                    "            SHARE_REFERENCE_NO_F27Q,  " +
                    "            EMBEDDED_DEDUCTEE_SEARCH,  " +
                    "            DEDUCTED_DATE_EXCEL," +
                    "            ENABLE_AUTO_POPULATE_DEDUCTEE_CODE, " + //-- Added By Abhishek Dey On 17/04/2018 --" +
                    "            BROWSER_LOGIN_TRACES, " +
                    "            ENABLE_HIDE_PASSWORD, " +
                    "            DEFAULT_MINOR_CODE, " +
                    "            LOAD_SECTION_AUTO, " +
                    "            ENABLE_NSDL_TEXT_CAPS_LOCK," +
                    "            MAX_REC_EXCEL_IMPORT_ALERT," +
                    "            DO_NOT_SHOW_AGAIN_KEYBOARDSHORTCUT_BANNER," +
                    "            SEC194N_EXCESS_1CRORE_EXCEL_IMPORT_OPTION," +
                    "            CERTIFICATE_TDSMAN_FOOTER_ENABLE_OPTION," +
                    "            CERTIFICATE_SECOND_FOOTER_ENABLE_OPTION," +
                    "            CERTIFICATE_SECOND_FOOTER_TEXT," +
                    "            PARTY_SEARCH_PAN_WISE," +
                    "            INCOME_LOSS_HOUSE_PROP_SD_MAX_LIMIT," +
                    "            US_16_EA_SD_MAX_LIMIT," +
                    "            US_16_TE_SD_MAX_LIMIT," +
                    "            US_16_IA_SD_MAX_LIMIT," +
                    "            CVIA_SEC80CCD_1B_SD_MAX_LIMIT," +
                    "            CVIA_SEC80D_SD_MAX_LIMIT," +
                    "            CVIA_SEC80TTA_SD_MAX_LIMIT," +
                    "            CVIA_SEC80D_SD_SENIOR_MAX_LIMIT,  " +
                    "            SHARE_REFERENCE_NO_F27EQ," +
                    "            AUTO_POPULATE_PAID_AMOUNT_TAX_AMOUNT, " +
                    "            IGNORE_MENU_MANAGEMENT_FLAG, " +
                    "            DEFAULT_HOME_DASHBOARD_FLAG, " +
                    "            RETURNS_UNDER_PROCESS_DAYS, " +
                    "            RETURNS_READY_FOR_FILING_DAYS, " +
                    "            FILED_RETURNS_DAYS, " +
                    "            HIDE_SMTP_PASSWORD, " +
                    "            TRIAL_CERTIFICATE_VERIFY_RECORDS, " +
                    "            FETCH_SECTION_FROM_PAN_NAME," +
                    "            ENABLE_PASSWORD_ITPORTALS_MODULE, " +
                    "            FREEZE_CORRECTION_YEARS, " +
                    "            ROUND_OFF_TAXABLE_AMOUNT_26Q_27Q_27EQ, " +
                    "            EXPORT_REPORTS_CSV " +
                    "     FROM   MST_SETUP ";
                //-- 2014/11/14
                if (TDSMAN.T_PackageType == T_PACKAGE_TYPE.MULTI_USER)
                {
                    if (TDSMAN.T_MACHINE_ID > 0)
                        strSQL = strSQL + " WHERE SETUPID = " + TDSMAN.T_MACHINE_ID + " ";
                }
                //--
                //--
                DMLService dmlServiceSetup = new DMLService();
                drdGetSetup = dmlServiceSetup.J_ExecSqlReturnReader(dmlServiceSetup.J_pCommand, strSQL);
                if (drdGetSetup == null)
                    return;
                //--
                while (drdGetSetup.Read())
                {
                    //
                    if (Convert.ToString(drdGetSetup["SHOW_BOOKMARK"]) == "1")
                        TDSMAN.T_pBookMarkOption = true;
                    else
                        TDSMAN.T_pBookMarkOption = false;
                    //
                    if (Convert.ToString(drdGetSetup["SHOW_DEDUCTED_DATE"]) == "1")
                        TDSMAN.T_ShowDeductedDate = true;
                    else
                        TDSMAN.T_ShowDeductedDate = false;
                    //
                    if (Convert.ToString(drdGetSetup["COPY_INTEREST_ALLOCATED"]) == "1")
                        TDSMAN.T_CopyInterestAllocated = true;
                    else
                        TDSMAN.T_CopyInterestAllocated = false;
                    //
                    if (Convert.ToString(drdGetSetup["SHOW_NONSALARY_TDS_RATE"]) == "1")
                        TDSMAN.T_ShowNonSalaryTDSRate = true;
                    else
                        TDSMAN.T_ShowNonSalaryTDSRate = false;
                    //
                    #region PROXY
                    if (Convert.ToString(drdGetSetup["PROXY_SETTINGS"]) == "1")
                    {
                        TDSMAN.T_ProxySettings = T_YES_NO.YES;
                        //
                        TDSMAN.T_ProxyAddress = Convert.ToString(drdGetSetup["HOST_ADDRESS"]);
                        TDSMAN.T_ProxyPort = Convert.ToString(drdGetSetup["HOST_PORT"]);
                        //
                        if (Convert.ToString(drdGetSetup["HOST_USER_NAME"]) != "")
                        {
                            TDSMAN.T_ProxyUsername = Convert.ToString(drdGetSetup["HOST_USER_NAME"]);
                            TDSMAN.T_ProxyPassword = Convert.ToString(drdGetSetup["HOST_PASSWORD"]);
                        }
                    }
                    else
                        TDSMAN.T_ProxySettings = T_YES_NO.NO;
                    #endregion
                    //
                    #region PASSWORD
                    //
                    //TDSMAN.T_Password = Convert.ToString(drdGetSetup["PASSWD"]);
                    //
                    #endregion
                    //
                    if (Convert.ToString(drdGetSetup["SHOW_ALLOCATED_FIELDS"]) == "1")
                        TDSMAN.T_ShowAllocatedFields = true;
                    else
                        TDSMAN.T_ShowAllocatedFields = false;
                    //
                    if (Convert.ToString(drdGetSetup["SHOW_DEDUCTEE_COMPANY_WISE"]) == "1")
                        TDSMAN.T_ShowCompanyWiseDeductee = true;
                    else
                        TDSMAN.T_ShowCompanyWiseDeductee = false;
                    //
                    if (Convert.ToString(drdGetSetup["PROHIBIT_ZERO_TAX_DEDUCTION"]) == "1")
                        TDSMAN.T_ProhibitZeroTaxDeduction = true;
                    else
                        TDSMAN.T_ProhibitZeroTaxDeduction = false;
                    //
                    if (Convert.ToString(drdGetSetup["SHOW_REGULAR_DEDUCTEE_CORRECTION"]) == "1")
                        TDSMAN.T_ShowRegularDeducteeCorrection = true;
                    else
                        TDSMAN.T_ShowRegularDeducteeCorrection = false;
                    //
                    if (Convert.ToString(drdGetSetup["ALLOT_AUTOMATIC_REF_NO"]) == "1")
                        TDSMAN.T_AllotAutomaticRefNo = true;
                    else
                        TDSMAN.T_AllotAutomaticRefNo = false;
                    //
                    if (Convert.ToString(drdGetSetup["ENABLE_DEDUCTEE_FIRST"]) == "1")
                        TDSMAN.T_EnableDeducteeFirst = true;
                    else
                        TDSMAN.T_EnableDeducteeFirst = false;
                    //
                    //-- 2015-07-23 @@ DHRUB
                    if (Convert.ToString(drdGetSetup["AUTO_CALCULATE_TDS_RATE"]) == "1")
                        TDSMAN.T_EnableAutoCalculateTdsRate = true;
                    else
                        TDSMAN.T_EnableAutoCalculateTdsRate = false;
                    //-- 2015/11/16 @ ANIK.G
                    if (Convert.ToString(drdGetSetup["ROUND_OFF_TAXABLE_AMOUNT"]) == "1")
                        TDSMAN.T_EnableRoundOffTaxableAmt = true;
                    else
                        TDSMAN.T_EnableRoundOffTaxableAmt = false;
                    //-- 2016/06/15 @ ANIK.G
                    if (Convert.ToString(drdGetSetup["SHOW_COLUMNS_FORM16_PARTB"]) == "1")
                        TDSMAN.T_ShowColumnsForm16PartB = true;
                    else
                        TDSMAN.T_ShowColumnsForm16PartB = false;
                    ////-- 2016/09/01
                    if (Convert.ToString(drdGetSetup["ENABLE_LOCK_RETURN"]) == "1")
                        TDSMAN.T_EnableLockReturn = true;
                    else
                        TDSMAN.T_EnableLockReturn = false;
                    ////-- 2017/02/11
                    if (Convert.ToString(drdGetSetup["ENABLE_REFERENCE_NO"]) == "1")
                        TDSMAN.T_EnableReferenceNo = true;
                    else
                        TDSMAN.T_EnableReferenceNo = false;
                    ////-- 2017/02/20
                    if (Convert.ToString(drdGetSetup["SHARE_REFERENCE_NO_F24Q"]) == "1")
                        TDSMAN.T_ShareReferenceNoF24Q = true;
                    else
                        TDSMAN.T_ShareReferenceNoF24Q = false;
                    ////-- 2017/02/20
                    if (Convert.ToString(drdGetSetup["SHARE_REFERENCE_NO_F26Q"]) == "1")
                        TDSMAN.T_ShareReferenceNoF26Q = true;
                    else
                        TDSMAN.T_ShareReferenceNoF26Q = false;
                    ////-- 2017/02/20
                    if (Convert.ToString(drdGetSetup["SHARE_REFERENCE_NO_F27Q"]) == "1")
                        TDSMAN.T_ShareReferenceNoF27Q = true;
                    else
                        TDSMAN.T_ShareReferenceNoF27Q = false;
                    ////-- 2021/07/14
                    if (Convert.ToString(drdGetSetup["SHARE_REFERENCE_NO_F27EQ"]) == "1")
                        TDSMAN.T_ShareReferenceNoF27EQ = true;
                    else
                        TDSMAN.T_ShareReferenceNoF27EQ = false;
                    ////-- 2017/05/24
                    if (Convert.ToString(drdGetSetup["EMBEDDED_DEDUCTEE_SEARCH"]) == "1")
                    {
                        TDSMAN.T_EmbedDeducteeSearch = true;
                        TDSMAN.T_DeducteeSearchLikeOperator = "%";
                    }
                    else
                    {
                        TDSMAN.T_EmbedDeducteeSearch = false;
                        TDSMAN.T_DeducteeSearchLikeOperator = "";
                    }
                    ////-- 2017/05/24
                    if (Convert.ToString(drdGetSetup["DEDUCTED_DATE_EXCEL"]) == "1")
                        TDSMAN.T_DeductedDateExcel = true;
                    else
                        TDSMAN.T_DeductedDateExcel = false;
                    //-- Added By Abhishek Dey On 18/04/2018 --
                    if (Convert.ToString(drdGetSetup["ENABLE_AUTO_POPULATE_DEDUCTEE_CODE"]) == "1")
