                    strSQL = "SELECT PRN_NO FROM TRN_BASIC_INFO WHERE COMPANY_ID = " + CompanyId + " AND ASST_ID = " + FAYear + " AND QTR ='" + Qtr + "' AND FORM_NO ='" + FormNo + "' ";
