        //--
        #region ValidatePAN
        public string ValidatePAN(string PAN)
        {
            if (PAN.Trim() == "")
            {
                return "";
            }
            //-----------------------------------------------------------------------
            //-- PAN FORMAT
            //-----------------------------------------------------------------------
            if (PAN.Length != 10)
            {
                return "";
            }
            if (PAN.Trim() == "PANNOTAVBL")
            {
                return "";
            }
            else if (PAN.Trim() == "PANAPPLIED")
            {
                return "";
            }
            else if (PAN.Trim() == "PANNOTREQD")
            {
                return "";
            }
            else
            {
                //---------------------------
                if (cmnService.J_CheckAlphabetsNumeric(cmnService.J_Left(PAN, 5), J_DataType.Character) == false)
                {                    
                    return "";
                }
                //---------------------------
                if (cmnService.J_CheckAlphabetsNumeric(cmnService.J_Mid(PAN, 5, 4), J_DataType.Numeric) == false)
                {
                    return "";
                }
                //---------------------------
                if (cmnService.J_CheckAlphabetsNumeric(cmnService.J_Right(PAN, 1), J_DataType.Character) == false)
                {
                    return "";
                }
            }
            return PAN;
        }
        #endregion
