        #region T_AttachDigitalSignature [1]
        public bool T_AttachDigitalSignature(string InPutPDFFilePath, string OutPutPDFFilePath, string SignatureFilePath, string Password, float x, float y, float x1, float y1, string Reason, bool ReasonVisible, string Contact, bool ContactVisible, string Location, bool LocationVisible, string SignatureType, bool SignatureVisible)
        {
            return T_AttachDigitalSignature(dmlService.J_pCommand, InPutPDFFilePath, OutPutPDFFilePath, SignatureFilePath, Password, x, y, x1, y1, Reason, ReasonVisible, Contact, ContactVisible, Location, LocationVisible, SignatureType, SignatureVisible);
        }
        #endregion

        #region T_AttachDigitalSignature [2]
        public bool T_AttachDigitalSignature(IDbCommand command, string InPutPDFFilePath, string OutPutPDFFilePath, string SignatureFilePath, string Password, float x, float y, float x1, float y1, string Reason, bool ReasonVisible, string Contact, bool ContactVisible, string Location, bool LocationVisible, string SignatureType, bool SignatureVisible)
        {
            bool blnSignatureType = true;

            if (SignatureType == T_DigitalSignatureType.DigitalSignatureCustom)
                blnSignatureType = true;
            else
                blnSignatureType = false;


            if (InPutPDFFilePath == "") return false;
            if (OutPutPDFFilePath == "") return false;

            PdfReader reader = new PdfReader(InPutPDFFilePath);

            MetaData md = new MetaData();
            md.Info = reader.Info;

            //authorBox.Text = md.Author;
            //titleBox.Text = md.Title;
            //subjectBox.Text = md.Subject;
            //kwBox.Text = md.Keywords;
            //creatorBox.Text = md.Creator;
            //prodBox.Text = md.Producer;

            Cert myCert = null;
            try
            {
                myCert = new Cert(SignatureFilePath, Password);
            }
            catch (Exception ex)
            {

                cmnService.J_UserMessage("Exception : " + ex.Message );
                cmnService.J_UserMessage("Enter the correct signature password.", MessageBoxIcon.Information);
                //cmnService.J_UserMessage("Please make sure you entered a valid certificate file and password",MessageBoxIcon.Information);
                //cmnService.J_UserMessage("Exception : " + ex.ToString());
                return false;
            }
            //Adding Meta Datas
            MetaData MyMD = new MetaData();
            //MyMD.Author = authorBox.Text;
            //MyMD.Title = titleBox.Text;
            //MyMD.Subject = subjectBox.Text;
            //MyMD.Keywords = kwBox.Text;
            //MyMD.Creator = creatorBox.Text;
            //MyMD.Producer = prodBox.Text;


            //debug("Signing document ... ");
            PDFSigner pdfs = new PDFSigner(InPutPDFFilePath, OutPutPDFFilePath, myCert, MyMD);
            //pdfs.Sign(Reasontext.Text, Contacttext.Text, Locationtext.Text, SigVisible.Checked);
            //pdfs.Sign(Reasontext.Text, Contacttext.Text, Locationtext.Text, SigVisible.Checked, Convert.ToInt32(X.Text.ToString().Trim()), Convert.ToInt32(Y.Text.ToString().Trim()), Convert.ToInt32(X1.Text.ToString().Trim()), Convert.ToInt32(Y1.Text.ToString().Trim()), checkBox1.Checked, checkBox2.Checked, checkBox3.Checked, radioButton2.Checked);
            pdfs.Sign(Reason, Contact, Location, SignatureVisible, Convert.ToInt32(x), Convert.ToInt32(y), Convert.ToInt32(x1), Convert.ToInt32(y1), ReasonVisible, ContactVisible, LocationVisible, blnSignatureType);

            return true;
        }
        #endregion 
        
