        #region LimitEditions
        public bool LimitEditions(long BasicInfoID, bool ExcelIncremental, bool ManualEntry, bool GenerateReturn, string ExistingTableName, string ExistingColumnName, 
                                                                                                                 string CurrentTableName, string CurrentColumnName)
        {
            try
            {
                //if (cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT ASST_ID FROM TRN_BASIC_INFO WHERE BASIC_INFO_ID =" + BasicInfoID)))
                //    >= T_FinancialYearID.F2014_15ID)
                    //-- 2016/05/03
                if (cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT ASST_ID FROM TRN_BASIC_INFO WHERE BASIC_INFO_ID =" + BasicInfoID)))
                    == cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT MAX(ASST_ID) FROM MST_ASSESSMENT"))))
                {
                    //-- 2015-05-12
                    if (TDSMAN.T_pEditionType == T_EDITION_TYPE.PROFESSIONAL_EDITION)
                        TDSMAN.T_MaxDeducteeDetailsCountEditions = TDSMAN.T_MaxDeducteeDetailsCountProfessional;
                    else if(TDSMAN.T_pEditionType == T_EDITION_TYPE.COMMERCIAL_LAW_HOUSE) //-- 2022/04/11
                        TDSMAN.T_MaxDeducteeDetailsCountEditions = TDSMAN.T_MaxDeducteeDetailsCountClh;
                    else if (TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_EDITION)  //-- 2016/01/29
                        TDSMAN.T_MaxDeducteeDetailsCountEditions = TDSMAN.T_MaxDeducteeDetailsCountEnterprise;
                    else if (TDSMAN.T_pEditionType == T_EDITION_TYPE.STANDARD_EDITION)
                        TDSMAN.T_MaxDeducteeDetailsCountEditions = TDSMAN.T_MaxDeducteeDetailsCountStandard;
                    else if (TDSMAN.T_pEditionType == T_EDITION_TYPE.LITE_EDITION)
                        TDSMAN.T_MaxDeducteeDetailsCountEditions = TDSMAN.T_MaxDeducteeDetailsCountLite;
                    else if (TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_LITE_EDITION)  //-- 2021/01/13
                        TDSMAN.T_MaxDeducteeDetailsCountEditions = TDSMAN.T_MaxDeducteeDetailsCountEnterpriseLite;
                    else if (TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_ULTIMATE_EDITION)  //-- 2024/06/06
                        TDSMAN.T_MaxDeducteeDetailsCountEditions = TDSMAN.T_MaxDeducteeDetailsCountEnterpriseUltimate;

                    //                    
                    long lngExistingRecords = 0;
                    long AssessmentID = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT ASST_ID FROM TRN_BASIC_INFO WHERE BASIC_INFO_ID =" + BasicInfoID)));
                    //--
                    string strFinancialYear = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT MST_ASSESSMENT.FA_YEAR FROM TRN_BASIC_INFO, MST_ASSESSMENT WHERE TRN_BASIC_INFO.ASST_ID = MST_ASSESSMENT.ASST_ID AND BASIC_INFO_ID =" + BasicInfoID));
                    //--
                    //
                    #region GET EXISTING RECORDS
                    //-- DD
                    strSQL = "SELECT COUNT(*) FROM " + ExistingTableName + ", TRN_BASIC_INFO, MST_ASSESSMENT " +
                             "WHERE  " + ExistingTableName + ".BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID " +
                             "AND    TRN_BASIC_INFO.ASST_ID = MST_ASSESSMENT.ASST_ID " +
                             "AND    MST_ASSESSMENT.ASST_ID = " + AssessmentID + " ";
                    //if (ExcelIncremental == false)                    
                    if (ManualEntry == false && ExcelIncremental == false && GenerateReturn == false) //-- ANIK @ 2018/10/03
                        strSQL = strSQL + "AND TRN_BASIC_INFO.BASIC_INFO_ID <> " + BasicInfoID;

                    lngExistingRecords += cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)));
                    //
                    //if (Excel == true) lngExistingRecords = 0;
                    #endregion
                    //--
                    #region GET CURRENT RECORDS
                    long lngCurrentRecords = 0;
                    if (CurrentTableName != "")
                    {
                        strSQL = "SELECT COUNT(*) FROM " + CurrentTableName;
                        lngCurrentRecords = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)));
                    }
                    #endregion
                    //--
                    long lngTotalRecords = lngExistingRecords + lngCurrentRecords;
                    if (ManualEntry == true)
                        lngTotalRecords = lngTotalRecords + 1;
                    //--
                    if (TDSMAN.T_pVersionType == T_VERSION_TYPE.LICENSED_VERSION)
                    {
                        #region PROFESSIONAL_EDITION
                        if (TDSMAN.T_pEditionType == T_EDITION_TYPE.PROFESSIONAL_EDITION)
                        {
                            if (lngTotalRecords > TDSMAN.T_MaxDeducteeDetailsCountEditions)
                            {
                                TrnTrialMessageBox TrialMessageBox = new TrnTrialMessageBox();
                                TrialMessageBox.StartPosition = FormStartPosition.CenterScreen;
                                TrialMessageBox.lnkOrderNow.Visible = false;
                                TrialMessageBox.lblMessage1.Text = "You are using the Professional version.";
                                TrialMessageBox.lblMessage2.Text = "It supports only upto " + TDSMAN.T_MaxDeducteeDetailsCountEditions + " records.";
                                ////if (ManualEntry == true)
                                ////{
                                ////    //TrialMessageBox.lblMessage1.Text = TDSMAN.T_MaxDeducteeDetailsCountEditions + " record limit reached!";
                                ////    //TrialMessageBox.lblMessage1.Text = "You are using the Professional version.";
                                ////    //TrialMessageBox.lblMessage2.Text = "No more deductee records can be added for FY 2014-15 as the Professional Edition edition supports only " + TDSMAN.T_MaxDeducteeDetailsCountEditions + " records.";
                                ////    //TrialMessageBox.lblMessage2.Text = "No more deductee records can be added for FY " + strFinancialYear + " as the Professional Edition edition supports only " + TDSMAN.T_MaxDeducteeDetailsCountEditions + " records.";
                                ////    TrialMessageBox.lblMessage2.Text = "It supports only upto " + TDSMAN.T_MaxDeducteeDetailsCountEditions + " records.";
                                ////}
