                                    TrialMessageBox.lblMessage2.Text = "Enterprise (ultimate) Edition supports only " + TDSMAN.T_MaxDeducteeDetailsCountEditions + "  deductee records. Importing this file will exceed the allowed number of deductee records.";
                                }
                                TrialMessageBox.Show();
                                return false;
                            }
                        }
                        #endregion
                        //--
                        #region ENTERPRISE_LITE_EDITION
                        else if (TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_LITE_EDITION)  //-- 2021/01/13
                        {
                            if (lngTotalRecords > TDSMAN.T_MaxDeducteeDetailsCountEditions)
                            {
                                TrnTrialMessageBox TrialMessageBox = new TrnTrialMessageBox();
                                TrialMessageBox.StartPosition = FormStartPosition.CenterScreen;
                                TrialMessageBox.lnkOrderNow.Visible = false;
                                if (ManualEntry == true)
                                {
                                    //TrialMessageBox.lblMessage1.Text = TDSMAN.T_MaxDeducteeDetailsCountEditions + " record limit reached!";
                                    TrialMessageBox.lblMessage1.Text = "You are using the Enterprise (Lite) version.";
                                    //TrialMessageBox.lblMessage2.Text = "No more deductee records can be added for FY 2014-15 as the Enterprise Edition edition supports only " + TDSMAN.T_MaxDeducteeDetailsCountEditions + " records.";
                                    //TrialMessageBox.lblMessage2.Text = "No more deductee records can be added for FY " + strFinancialYear + " as the Enterprise (lite) Edition edition supports only " + TDSMAN.T_MaxDeducteeDetailsCountEditions + " records.";
                                    TrialMessageBox.lblMessage2.Text = "It supports only upto " + TDSMAN.T_MaxDeducteeDetailsCountEditions + " records.";
                                }
                                else if (GenerateReturn == true)
                                {
                                    //TrialMessageBox.lblMessage1.Text = TDSMAN.T_MaxDeducteeDetailsCountEditions + " record limit reached!";
                                    TrialMessageBox.lblMessage1.Text = "You are using the Enterprise (Lite) version.";
                                    //TrialMessageBox.lblMessage2.Text = "No more deductee records can be added for FY 2014-15 as the Standard Edition edition supports only " + TDSMAN.T_MaxDeducteeDetailsCountEditions + " records.";
                                    //TrialMessageBox.lblMessage2.Text = "No more deductee records can be added for FY " + strFinancialYear + " as the Standard Edition edition supports only " + TDSMAN.T_MaxDeducteeDetailsCountEditions + " records.";
                                    //TrialMessageBox.lblMessage2.Text = "This Enterprise (lite) Edition software of FY " + strFinancialYear + " supports only " + TDSMAN.T_MaxDeducteeDetailsCountEditions + " records.";
                                    TrialMessageBox.lblMessage2.Text = "It supports only upto " + TDSMAN.T_MaxDeducteeDetailsCountEditions + " records.";
                                }
                                else
                                {
                                    TrialMessageBox.lblMessage1.Text = "Import not Allowed";
                                    TrialMessageBox.lblMessage2.Text = "Enterprise (lite) Edition supports only " + TDSMAN.T_MaxDeducteeDetailsCountEditions + "  deductee records. Importing this file will exceed the allowed number of deductee records.";
                                }
                                TrialMessageBox.Show();
                                return false;
                            }
                        }
                        #endregion
                        //--
                        return true;
                    }
                    else
                    {
                        if (lngTotalRecords > TDSMAN.T_MaxDeducteeDetailsCountTrialEditions)
                        {
                            TrnTrialMessageBox TrialMessageBox = new TrnTrialMessageBox();
                            TrialMessageBox.StartPosition = FormStartPosition.CenterScreen;
                            TrialMessageBox.lnkOrderNow.Visible = false;
                            if (ManualEntry == true)
                            {
                                TrialMessageBox.lblMessage1.Text = TDSMAN.T_MaxDeducteeDetailsCountTrialEditions + " record limit reached!";
                                //TrialMessageBox.lblMessage2.Text = "No more deductee records can be added for FY 2014-15 as the Standard Edition edition supports only " + TDSMAN.T_MaxDeducteeDetailsCountEditions + " records.";
                                TrialMessageBox.lblMessage2.Text = "No more deductee records can be added for FY " + strFinancialYear + " as the Standard Edition (Trial) supports only " + TDSMAN.T_MaxDeducteeDetailsCountTrialEditions + " records.";
                            }
                            else if (GenerateReturn == true)
                            {
                                TrialMessageBox.lblMessage1.Text = TDSMAN.T_MaxDeducteeDetailsCountTrialEditions + " record limit reached!";
                                //TrialMessageBox.lblMessage2.Text = "No more deductee records can be added for FY 2014-15 as the Standard Edition edition supports only " + TDSMAN.T_MaxDeducteeDetailsCountEditions + " records.";
                                //TrialMessageBox.lblMessage2.Text = "No more deductee records can be added for FY " + strFinancialYear + " as the Standard Edition edition supports only " + TDSMAN.T_MaxDeducteeDetailsCountEditions + " records.";
                                TrialMessageBox.lblMessage2.Text = "This Standard Edition (Trial) software of FY " + strFinancialYear + " supports only " + TDSMAN.T_MaxDeducteeDetailsCountTrialEditions + " records.";
                            }
                            else
                            {
                                TrialMessageBox.lblMessage1.Text = "Import not Allowed";
                                TrialMessageBox.lblMessage2.Text = "Standard Edition (Trial) supports only " + TDSMAN.T_MaxDeducteeDetailsCountTrialEditions + "  deductee records. Importing this file will exceed the allowed number of deductee records.";
                            }
                            TrialMessageBox.Show();
                            return false;
                        }
                    }
                    return true;
                }
                return true;
            }
            catch
            {
                return false;
            }
        }
