        #region AutoBackupData
        public bool AutoBackupData(string strRemarks)
        {
            /// Function to take the backup of the data in the fixed folder

            // Added by Shrey Kejriwal on 12/02/2014
            try
            {
                //Backup folder path
                string strBackupFolder = Path.Combine(Application.StartupPath, "Database Backup");

                //Create Folder if it does not exists
                cmnService.J_CreateDirectory(strBackupFolder);

                //Backup file name with date & time
                string strBkUpFileName = J_Var.J_pMsAccessDatabaseName.Substring(0, 6) + "-" + string.Format("{0:yyyyMMdd}", System.DateTime.Now.Date) + "-" + string.Format("{0:HHmmss}", System.DateTime.Now) + ".mdb";

                //copy the database to the backup folder...
                File.Copy(Path.Combine(Application.StartupPath, J_Var.J_pMsAccessDatabaseName), Path.Combine(strBackupFolder, strBkUpFileName), true);

                //Saving log of database backup
                string strSQL = "INSERT INTO TRN_BACKUP (" +
                " BACKUP_DATE," +
                " BACKUP_TIME," +
                " BACKUP_PATH," +
                " BACKUP_FILE_NAME," +
                " BACKUP_NOTES) " +
                "VALUES (" +
                //" " + cmnService.J_DateOperator() + string.Format("{0:dd/MM/yyyy}", System.DateTime.Now.Date) + cmnService.J_DateOperator() + "," +
                //-- ANIK @ 2015/09/18 
                " " + cmnService.J_DateOperator() + string.Format("{0:MM/dd/yyyy}", System.DateTime.Now.Date) + cmnService.J_DateOperator() + "," +
                //-- COMMENTED BY ANIK ON 2017/01/06 FOR VS 2010
                //" '" + string.Format("{0:hh:mm:ss}", System.DateTime.Now.TimeOfDay) + "'," +
                " '" + string.Format("{0:hh:mm:ss}", System.DateTime.Now) + "'," +
                " '" + Application.StartupPath + "'," +
                " '" + strBkUpFileName + "'," +
                " '" + strRemarks + "')";

                if (dmlService.J_ExecSql(dmlService.J_pCommand, strSQL) == false)
                    return false;
                //

                return true;
            }
            catch
            {
                return false;
            }
        }
        #endregion

        #region CloseChildForm
        public void CloseChildForm(Form Child, Form Parent)
        {
            foreach (Form frmChild in Parent.MdiChildren)
            {
                if (string.Compare(Child.Name, frmChild.Name, true) == 0)
                {
                    frmChild.Close();
                    return;
                }
            }
        }
        #endregion

        //-- 2014-06-16 ; ANIK GHOSH ; for config no. variations
        #region AllowInstallation
        private bool AllowInstallation(string SerialNo, string PackageFAYear, int EditionType, string ConfigurationNo)
        {
            try
            {
                string strDiffHDD = cmnService.J_GetRegistryKeyValue(T_pCompanyName + "\\" + this.GetRegistryFolder(), T_RegistrationInfo.Diff_HDD.ToString());
                //
                if (strDiffHDD.ToUpper() == "TRUE")
                    return true;
                //--
                if (T_CheckInternetConnectivty() == true && strDiffHDD.ToUpper() != "TRUE")// strDiffHDD == "")
                {
                    bool Diff_HDD = false;
                    Diff_HDD = Registration.AllowInstallation(SerialNo, PackageFAYear, EditionType, ConfigurationNo);
                    // SET DIFFERENT HDD TAG
                    cmnService.J_CreateRegistryKey(T_pCompanyName, GetRegistryFolder(),
                                                         T_RegistrationInfo.Diff_HDD.ToString(), Diff_HDD.ToString());
                    //
                    return Diff_HDD;
                }
                return false;
            }
            catch
            {
                return false;
            }
        }
        #endregion

