        #region AUTOMATIC REFERENCE NO ALLOTMENT
        public bool AutoReferenceNoAllotment(string FormNo, string Qtr, string FromModule)
        {
            try
            {
                if (FromModule == T_OTHERMODULENAME.REGULAR_FORM)
                {
                    #region REGULAR_FORM
                    if (FormNo == T_FormNo.F26Q)
                    {
                        strSQL = @"UPDATE MST_DEDUCTEE 
                                   SET    DEDUCTEE_REF = ''
                                   WHERE  DEDUCTEE_REF IS NULL";
                        if (dmlService.J_ExecSql(dmlService.J_pCommand, strSQL) == false)
                            return false;
                        //--

                        strSQL = @"UPDATE MST_DEDUCTEE";
                        if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                            strSQL = strSQL + " SET DEDUCTEE_REF = 'TMX' +  FORMAT(DEDUCTEE_ID,'0000000')";
                        else if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                            //strSQL = strSQL + " SET DEDUCTEE_REF = 'TMX' + RIGHT('000000' + CAST(DEDUCTEE_ID AS VARCHAR),6)";
                            strSQL = strSQL + " SET DEDUCTEE_REF = 'TMX' + RIGHT('0000000' + CAST(DEDUCTEE_ID AS VARCHAR),7)";
                        strSQL = strSQL + @" WHERE  DEDUCTEE_REF = ''
                                   AND    DEDUCTEE_PAN IN('PANNOTAVBL','PANINVALID','PANAPPLIED')"; //-- 2015/12/01
                        if (dmlService.J_ExecSql(dmlService.J_pCommand, strSQL) == false)
                            return false;
                    }
                    else if (FormNo == T_FormNo.F24Q)
                    {
                        strSQL = @"UPDATE MST_EMPLOYEE 
                                   SET    EMPLOYEE_REF = ''
                                   WHERE  EMPLOYEE_REF IS NULL";
                        if (dmlService.J_ExecSql(dmlService.J_pCommand, strSQL) == false)
                            return false;
                        //--
                        strSQL = @"UPDATE MST_EMPLOYEE";
                        if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                            strSQL = strSQL + " SET EMPLOYEE_REF = 'TMX' +  FORMAT(EMPLOYEE_ID,'0000000')";
                        else if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                            //strSQL = strSQL + " SET EMPLOYEE_REF = 'TMX' + RIGHT('000000' + CAST(EMPLOYEE_ID AS VARCHAR),6) ";
                            strSQL = strSQL + " SET EMPLOYEE_REF = 'TMX' + RIGHT('0000000' + CAST(EMPLOYEE_ID AS VARCHAR),7)";
                        strSQL = strSQL + @" WHERE  EMPLOYEE_REF = ''
                                   AND    EMPLOYEE_PAN IN('PANNOTAVBL','PANINVALID','PANAPPLIED')";//-- 2015/12/01
                        if (dmlService.J_ExecSql(dmlService.J_pCommand, strSQL) == false)
                            return false;
                    }
                    #endregion
                }
                else if (FormNo == T_FormNo.F26Q || FormNo == T_FormNo.F24Q)
                {
                    strSQL = @"UPDATE COR_TRN_DEDUCTEE_DETAILS ";
                    if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                        strSQL = strSQL + " SET DEDUCTEE_REF = 'TMX' +  FORMAT(TRN_DEDUCTEE_DETAIL_ID,'0000000')";
                    else if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                        //strSQL = strSQL + " SET DEDUCTEE_REF = 'TMX' + RIGHT('000000' + CAST(TRN_DEDUCTEE_DETAIL_ID AS VARCHAR),6) ";
                        //strSQL = strSQL + " SET DEDUCTEE_REF = 'TMX' + RIGHT('000000' + CAST(TRN_DEDUCTEE_DETAIL_ID AS VARCHAR),6) ";
                        strSQL = strSQL + " SET DEDUCTEE_REF = 'TMX' + RIGHT('0000000' + CAST(TRN_DEDUCTEE_DETAIL_ID AS VARCHAR),7) "; //-- ANIK @ 2018/04/13
                    strSQL = strSQL + @" WHERE  DEDUCTEE_REF = ''
                               AND    DEDUCTEE_PAN  IN('PANNOTAVBL','PANINVALID','PANAPPLIED')";//-- 2015/12/01
                    if (dmlService.J_ExecSql(dmlService.J_pCommand, strSQL) == false)
                        return false;
                }
                return true;
            }
            catch
            {
                return false;
            }
        }
        #endregion

        //-- ADDED BY DHRUB ON 2015-10-03 
        #region T_WriteToRegistryFileCreationPath
        public bool T_WriteToRegistryFileCreationPath(string FvuFileCreationPath)
        {
            try
            {
                string strFileCreationPath = cmnService.J_GetRegistryKeyValue(T_pCompanyName + "\\" + this.GetRegistryFolder(),
                                                                              T_RegistrationInfo.File_Creation_Path.ToString());
                if (strFileCreationPath == "")
                {
                    // CREATE REGISTRY
                    cmnService.J_CreateRegistryKey(TDSMAN.T_pCompanyName);
                    cmnService.J_CreateRegistryKey(TDSMAN.T_pCompanyName, this.GetRegistryFolder());
                    // SET SERIAL NO
                    cmnService.J_CreateRegistryKey(TDSMAN.T_pCompanyName, this.GetRegistryFolder(),
                                                    T_RegistrationInfo.File_Creation_Path.ToString(), FvuFileCreationPath);
                    return true;
                }
                else
                {
                    //TDSMAN.T_TempFileCreationPath = cmnService.J_GetRegistryKeyValue(T_pCompanyName + "\\" + this.GetRegistryFolder(),
                    //                                                          T_RegistrationInfo.File_Creation_Path.ToString());
                    return true;
                }
            }
            catch (Exception err)
            {
                cmnService.J_UserMessage(err.Message);
                return false;
            }
        }
        #endregion

        //-- ADDED BY ANIK ON 2015-11-20 
        #region T_GetFileCreationPathFromRegistry
        public string T_GetFileCreationPathFromRegistry()
        {
            try
            {
                string strFileCreationPath = "";
                //
                if (TDSMAN.T_pVersionType == T_VERSION_TYPE.TRIAL_VERSION)
                {
                    strFileCreationPath = cmnService.J_GetRegistryKeyValue(T_pCompanyName + "\\" + this.GetRegistryFolder() + "(Trial)",
                                                                                 T_RegistrationInfo.File_Creation_Path.ToString());
                    if (strFileCreationPath == "")
                    {
                        // CREATE REGISTRY
                        cmnService.J_CreateRegistryKey(T_pCompanyName);
                        cmnService.J_CreateRegistryKey(T_pCompanyName, this.GetRegistryFolder() + "(Trial)");
                        // SET SERIAL NO
                        cmnService.J_CreateRegistryKey(T_pCompanyName, this.GetRegistryFolder() + "(Trial)",
                                                        T_RegistrationInfo.File_Creation_Path.ToString(), System.Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments));

                    }
                    //--
                    return cmnService.J_GetRegistryKeyValue(T_pCompanyName + "\\" + this.GetRegistryFolder() + "(Trial)",
                                                                              T_RegistrationInfo.File_Creation_Path.ToString());
                }
                else
                {
                    strFileCreationPath = cmnService.J_GetRegistryKeyValue(T_pCompanyName + "\\" + this.GetRegistryFolder(),
                                                                                 T_RegistrationInfo.File_Creation_Path.ToString());
                    if (strFileCreationPath == "")
                    {
                        // CREATE REGISTRY
                        cmnService.J_CreateRegistryKey(T_pCompanyName);
                        cmnService.J_CreateRegistryKey(T_pCompanyName, this.GetRegistryFolder());
                        // SET SERIAL NO
                        cmnService.J_CreateRegistryKey(T_pCompanyName, this.GetRegistryFolder(),
                                                        T_RegistrationInfo.File_Creation_Path.ToString(), Application.StartupPath);

                    }
                    //--
                    return cmnService.J_GetRegistryKeyValue(T_pCompanyName + "\\" + this.GetRegistryFolder(),
                                                                              T_RegistrationInfo.File_Creation_Path.ToString());
                }
            }
            catch (Exception err)
            {
                cmnService.J_UserMessage(err.Message);
                return "";
                //return false;
            }
        }
        #endregion

        //-- ADDED BY DHRUB ON 2016-01-12
        #region T_GetRegistryTrialReturn
        public bool T_GetRegistryTrialReturn()
        {
            try
            {
                if (TDSMAN.T_pPackageFAYear == (int)Software_Version.FY2014_15)
                {
                    if (cmnService.J_ReturnInt32Value(cmnService.J_GetRegistryKeyValue("Software" + "\\" + "TMT", "R")) > 0)
                        return true;
                    else
                        return false;
                }
                else if (TDSMAN.T_pPackageFAYear == (int)Software_Version.FY2015_16)
                {
                    if (cmnService.J_ReturnInt32Value(cmnService.J_GetRegistryKeyValue("Software" + "\\" + "TMT", "R1516")) > 0)
                        return true;
                    else
                        return false;
                }
                else if (TDSMAN.T_pPackageFAYear == (int)Software_Version.FY2016_17) //-- 2016/01/12
                {
                    if (cmnService.J_ReturnInt32Value(cmnService.J_GetRegistryKeyValue("Software" + "\\" + "TMT", "R1617")) > 0)
                        return true;
                    else
                        return false;
                }
                else if (TDSMAN.T_pPackageFAYear == (int)Software_Version.FY2017_18)
                {
                    if (cmnService.J_ReturnInt32Value(cmnService.J_GetRegistryKeyValue("Software" + "\\" + "TMT", "R1718")) > 0)
                        return true;
                    else
                        return false;
                }
