        #region GetOSVersion
        public string GetOSVersion()
        {
            int _MajorVersion = Environment.OSVersion.Version.Major;

            switch (_MajorVersion)
            {
                case 5:
                    return "XP";
                case 6:
                    switch (Environment.OSVersion.Version.Minor)
                    {
                        case 0:
                            return "Windows Vista";
                        case 1:
                            return "Windows 7";
                        default:
                            return "Windows Vista & above";
                    }
                    break;
                default:
                    return "Unknown";
            }
        }
        #endregion

        #region GetSystemDefaultBrowserXP
        public string GetSystemDefaultBrowserXP()
        {
            //--
            string name = string.Empty;
            RegistryKey regKey = null;
            //--
            try
            {
                //-- set the registry key we want to open
                regKey = Registry.ClassesRoot.OpenSubKey("HTTP\\shell\\open\\command", false);
                //-- get rid of the enclosing quotes
                name = regKey.GetValue(null).ToString().ToLower().Replace("" + (char)34, "");
                ////-- check to see if the value ends with .exe (this way we can remove any command line arguments)
                if (!name.EndsWith("exe"))
                    //-- get rid of all command line arguments (anything after the .exe must go)
                    name = name.Substring(0, name.LastIndexOf(".exe") + 4);
                //--
            }
            catch (Exception ex)
            {
                name = string.Format("ERROR: An exception of type: {0} occurred in method: {1} in the following module: {2}", ex.GetType(), ex.TargetSite, this.GetType());
            }
            finally
            {
                //-- check and see if the key is still open, if so
                //-- then close it
                if (regKey != null)
                    regKey.Close();
            }
            //-- return the value
            return name;

        }
        #endregion

        #region GetSystemDefaultBrowser
        public string GetSystemDefaultBrowser()
        {
            const string userChoice = @"Software\Microsoft\Windows\Shell\Associations\UrlAssociations\http\UserChoice";
            string progId;
            string browser;
            //BrowserApplication browser;
            using (RegistryKey userChoiceKey = Registry.CurrentUser.OpenSubKey(userChoice))
            {
                if (userChoiceKey == null)
                {
                    browser = "";
                }
                object progIdValue = userChoiceKey.GetValue("Progid");
                if (progIdValue == null)
                {
                    browser = "";
                }
                progId = progIdValue.ToString();
                //--
                if (progId.Contains("Firefox"))
                    progId = "Firefox";
                else if (progId.Contains("Edge"))
                    progId = "MSEdgeHTM";
                switch (progId)
                {
                    case "IE.HTTP":
                        browser = "IE";
                        break;
                    //case "FirefoxURL":
                    //    browser = BrowserApplication.Firefox;
                    //    break;
                    case "ChromeHTML":
                        browser = "chrome";
                        break;
                    case "Firefox":
                        browser = "Firefox";
                        break;
                    case "MSEdgeHTM":
                        browser = "MSEdge";
                        break;
                    //case "OperaStable":
                    //    browser = BrowserApplication.Opera;
                    //    break;
                    //case "SafariHTML":
                    //    browser = BrowserApplication.Safari;
                    //    break;
                    //case "AppXq0fevzme2pys62n3e0fbqa7peapykr8v":
                    //    browser = BrowserApplication.Edge;
                    //    break;
                    default:
                        browser = "";
                        break;
                }
                return browser;
            }
            return browser;
        }
        #endregion

