        #region ExtractCertificates
        public bool ExtractCertificates(string BatFile, string JavaFile, string FolderPath,
                                        string InputZipFilePath, string PasswordZip, string OutputFolder)
        {
            try
            {
                // DELETION OF BAT FILE IF EXISTS
                if (File.Exists(BatFile) == true)
                    File.Delete(BatFile);
                //
                bool exists = System.IO.Directory.Exists(OutputFolder);
                if (!exists)
                    System.IO.Directory.CreateDirectory(OutputFolder);
                // CREATION OF BAT FILE
                File.AppendAllText(BatFile, "");
                //
                StreamWriter StreamWriter = cmnService.J_ReturnStreamWriter(BatFile);
                cmnService.J_WriteLine(ref StreamWriter, "@echo off");
                cmnService.J_WriteLine(ref StreamWriter, "java -cp " + (Char)34 + ".;lib/*" + (Char)34 + JavaFile + (Char)34 + InputZipFilePath + (Char)34 + " " + (Char)34 + PasswordZip + (Char)34 + " " + (Char)34 + OutputFolder + (Char)34);
                //
                StreamWriter.Flush();
                StreamWriter.Close();
                //
                int ExitCode;
                //
                ProcessStartInfo ProcessInfo = new ProcessStartInfo
                {
                    FileName = BatFile,
                    CreateNoWindow = true,
                    UseShellExecute = false,
                    RedirectStandardOutput = true,
                    RedirectStandardError = true,
                    WorkingDirectory = Path.Combine(Application.StartupPath, FolderPath)

                };
                //this.Cursor = Cursors.WaitCursor;
                using (Process processBatchFile = Process.Start(ProcessInfo))
                {
                    string output = processBatchFile.StandardOutput.ReadToEnd();
                    string error = processBatchFile.StandardError.ReadToEnd();
                    processBatchFile.WaitForExit();
                    //
                    if (Directory.Exists(Path.Combine(OutputFolder, "resources")))
                        Directory.Delete(Path.Combine(OutputFolder, "resources"), true);
                    if (Directory.Exists(Path.Combine(OutputFolder, "temp")))
                        Directory.Delete(Path.Combine(OutputFolder, "temp"), true);
                    //Console.WriteLine("Output: " + output);
                    if (!string.IsNullOrWhiteSpace(error))
                    {
                        //this.Cursor = Cursors.Default;
                        if (error.ToUpper().Contains("WRONG PASSWORD"))
                            cmnService.J_UserMessage("Check the password !!");
                        else if (error.ToUpper().Contains("JAVA.LANG.ARRAYINDEXOUTOFBOUNDSEXCEPTION"))
                            cmnService.J_UserMessage("Wrong input file selected !!");
                        else
                            cmnService.J_UserMessage(error);
                    }
                    else if (error.ToUpper().Contains("PDF FILES CREATED"))
                    {
                        //this.Cursor = Cursors.Default;
                        return true;
                    }
                    else if (output.ToUpper().Contains("NO PDF FILES GENERATED"))
                    {
                        //this.Cursor = Cursors.Default;
                        cmnService.J_UserMessage("No PDF files generated or an error occurred.");
                        return false;
                    }
                    else
                    {
                        //this.Cursor = Cursors.Default;
                        return true;
                    }
                }
                //this.Cursor = Cursors.Default;
                //if (Directory.Exists(Path.Combine(OutputFolder, "resources")))
                //    Directory.Delete(Path.Combine(OutputFolder, "resources"), true);
                //if (Directory.Exists(Path.Combine(OutputFolder, "temp")))
                //    Directory.Delete(Path.Combine(OutputFolder, "temp"), true);
                return true;
            }
            catch (Exception err)
            {
                return false;
            }
        }
        #endregion

        #region ExtractCertificatesSignedDigitally_
        public bool ExtractCertificatesSignedDigitally_(string BatFile, string JavaFile, string FolderPath,
                                        string InputZipFilePath, string PasswordZip, string OutputFolder, bool Signed)
        {
            try
            {
                // DELETION OF BAT FILE IF EXISTS
                if (File.Exists(BatFile) == true)
                    File.Delete(BatFile);
                //
                bool exists = System.IO.Directory.Exists(OutputFolder);
                if (!exists)
                    System.IO.Directory.CreateDirectory(OutputFolder);
                // CREATION OF BAT FILE
                File.AppendAllText(BatFile, "");
                //
                StreamWriter StreamWriter = cmnService.J_ReturnStreamWriter(BatFile);
                cmnService.J_WriteLine(ref StreamWriter, "@echo off");
                if(Signed == true)
                    cmnService.J_WriteLine(ref StreamWriter, "java -cp " + (Char)34 + ".;lib/*" + (Char)34 + JavaFile + (Char)34 + InputZipFilePath + (Char)34 + " " + (Char)34 + PasswordZip + (Char)34 + " " + (Char)34 + OutputFolder + (Char)34 + " SIGN");
                else
                    cmnService.J_WriteLine(ref StreamWriter, "java -cp " + (Char)34 + ".;lib/*" + (Char)34 + JavaFile + (Char)34 + InputZipFilePath + (Char)34 + " " + (Char)34 + PasswordZip + (Char)34 + " " + (Char)34 + OutputFolder + (Char)34);
                //
                StreamWriter.Flush();
                StreamWriter.Close();
                //
                int ExitCode;
                //
                ProcessStartInfo ProcessInfo = new ProcessStartInfo
                {
                    FileName = BatFile,
                    CreateNoWindow = true,
                    UseShellExecute = false,
                    RedirectStandardOutput = true,
                    RedirectStandardError = true,
                    //
                    RedirectStandardInput = true,
                    //
                    WorkingDirectory = Path.Combine(Application.StartupPath, FolderPath)

                };
                //this.Cursor = Cursors.WaitCursor;
                using (Process processBatchFile = Process.Start(ProcessInfo))
                {
                    // Variables to store output and error
                    string output = string.Empty;
                    string error = string.Empty;
                    int exitCode = -1;

                    // Handle output and error asynchronously to avoid deadlocks
                    processBatchFile.OutputDataReceived += (sender, args) =>
                    {
                        if (!string.IsNullOrEmpty(args.Data))
                            output += args.Data + Environment.NewLine;
                    };
                    processBatchFile.ErrorDataReceived += (sender, args) =>
                    {
                        if (!string.IsNullOrEmpty(args.Data))
                            error += args.Data + Environment.NewLine;
                    };

                    // Start the process
                    processBatchFile.Start();

                    // Begin asynchronous reading of output and error streams
                    processBatchFile.BeginOutputReadLine();
                    processBatchFile.BeginErrorReadLine();

                    // Send ENTER to skip PIN entry
                    processBatchFile.StandardInput.WriteLine();
                    processBatchFile.StandardInput.Flush();
                    processBatchFile.StandardInput.Close(); // Close input to signal no more input
                    //
                    processBatchFile.WaitForExit();
                    //
                    if (output == "PDFs have been digitally signed via optimized method")
                    {
                        processBatchFile.Kill();
                    }
                    //
                    if (Directory.Exists(Path.Combine(OutputFolder, "resources")))
                        Directory.Delete(Path.Combine(OutputFolder, "resources"), true);
                    //
                    if (Directory.Exists(Path.Combine(OutputFolder, "temp")))
                        Directory.Delete(Path.Combine(OutputFolder, "temp"), true);
                    //--
                    if (!string.IsNullOrWhiteSpace(error))
                    {
                        //this.Cursor = Cursors.Default;
                        if (error.ToUpper().Contains("WRONG PASSWORD"))
                            cmnService.J_UserMessage("Check the password !!");
                        else if (error.ToUpper().Contains("JAVA.LANG.ARRAYINDEXOUTOFBOUNDSEXCEPTION"))
                            cmnService.J_UserMessage("Wrong input file selected !!");
                        else
                            cmnService.J_UserMessage(error);
                    }
                    else if (error.ToUpper().Contains("PDF FILES CREATED"))
                    {
                        //this.Cursor = Cursors.Default;
                        return true;
                    }
                    else if (output.ToUpper().Contains("NO PDF FILES GENERATED"))
                    {
                        //this.Cursor = Cursors.Default;
                        cmnService.J_UserMessage("No PDF files generated or an error occurred.");
                        return false;
                    }
                    else
                    {
                        //this.Cursor = Cursors.Default;
                        return true;
                    }
                }
                //this.Cursor = Cursors.Default;
                //if (Directory.Exists(Path.Combine(OutputFolder, "resources")))
                //    Directory.Delete(Path.Combine(OutputFolder, "resources"), true);
                //if (Directory.Exists(Path.Combine(OutputFolder, "temp")))
                //    Directory.Delete(Path.Combine(OutputFolder, "temp"), true);
                return true;
            }
            catch (Exception err)
            {
                return false;
            }
        }
