        #region ExtractCertificatesDSC

        public bool ExtractCertificatesDSC(string BatFile, string JavaFile, string FolderPath,

                                        string InputZipFilePath, string PasswordZip, string OutputFolder,

                                        bool GenerateSignedPDF = false)

        {

            try

            {

                // DELETION OF BAT FILE IF EXISTS

                if (File.Exists(BatFile) == true)

                    File.Delete(BatFile);



                bool exists = System.IO.Directory.Exists(OutputFolder);

                if (!exists)

                    System.IO.Directory.CreateDirectory(OutputFolder);



                // CREATION OF BAT FILE

                File.AppendAllText(BatFile, "");



                StreamWriter StreamWriter = cmnService.J_ReturnStreamWriter(BatFile);

                cmnService.J_WriteLine(ref StreamWriter, "@echo off");



                // Build the command with optional signing parameter

                string javaCommand = "java -cp " + (Char)34 + ".;lib/*" + (Char)34 + " " + JavaFile + " " +

                                   (Char)34 + InputZipFilePath + (Char)34 + " " +

                                   (Char)34 + PasswordZip + (Char)34 + " " +

                                   (Char)34 + OutputFolder + (Char)34;



                // Add signing parameter if required

                if (GenerateSignedPDF)

                {

                    javaCommand += " SIGN";

                }



                cmnService.J_WriteLine(ref StreamWriter, javaCommand);



                StreamWriter.Flush();

                StreamWriter.Close();



                int ExitCode;



                ProcessStartInfo ProcessInfo = new ProcessStartInfo

                {

                    FileName = BatFile,

                    CreateNoWindow = true,

                    UseShellExecute = false,

                    RedirectStandardOutput = true,

                    RedirectStandardError = true,

                    RedirectStandardInput = true,  // Added for DSC PIN input

                    WorkingDirectory = Path.Combine(Application.StartupPath, FolderPath)

                };



                using (Process processBatchFile = Process.Start(ProcessInfo))

                {

                    // Handle DSC PIN input if signing is enabled

                    if (GenerateSignedPDF)

                    {

                        // The utility will prompt for DSC PIN - we can automate this if needed

                        // For now, let it handle the PIN prompt internally

                    }



                    string output = processBatchFile.StandardOutput.ReadToEnd();

                    string error = processBatchFile.StandardError.ReadToEnd();

                    processBatchFile.WaitForExit();



                    // Cleanup temp directories

                    if (Directory.Exists(Path.Combine(OutputFolder, "resources")))

                        Directory.Delete(Path.Combine(OutputFolder, "resources"), true);

                    if (Directory.Exists(Path.Combine(OutputFolder, "temp")))

                        Directory.Delete(Path.Combine(OutputFolder, "temp"), true);



                    // Error handling

                    if (!string.IsNullOrWhiteSpace(error))

                    {

                        if (error.ToUpper().Contains("WRONG PASSWORD"))

                            cmnService.J_UserMessage("Check the password !!");

                        else if (error.ToUpper().Contains("JAVA.LANG.ARRAYINDEXOUTOFBOUNDSEXCEPTION"))

                            cmnService.J_UserMessage("Wrong input file selected !!");

                        else if (error.ToUpper().Contains("DSC") || error.ToUpper().Contains("CERTIFICATE"))

                            cmnService.J_UserMessage("DSC Certificate error: " + error);

                        else

                            cmnService.J_UserMessage(error);

                        return false;

                    }

                    else if (output.ToUpper().Contains("PDF FILES CREATED") || error.ToUpper().Contains("PDF FILES CREATED"))

                    {

                        return true;

                    }

                    else if (output.ToUpper().Contains("NO PDF FILES GENERATED"))

                    {

                        cmnService.J_UserMessage("No PDF files generated or an error occurred.");

                        return false;

                    }

                    else

                    {

                        return true;

                    }

                }



                return true;

            }

            catch (Exception err)

            {

                cmnService.J_UserMessage("Error: " + err.Message);

                return false;

            }

        }

