        #region ExtractCertificatesSignedDigitally
        public bool ExtractCertificatesSignedDigitally(string BatFile, string JavaFile, string FolderPath,
                                                       string InputZipFilePath, string PasswordZip, string OutputFolder, 
                                                       int NoOfCertificates, int intTimeInterval, bool Signed)
        {
            try
            {
                // Estimate extraction time before starting process
                double timePerCertificate = Signed ? 1.15 : 0.29; // seconds per certificate from your observation
                int intEstimatedTimeMilliseconds = (int)Math.Ceiling(NoOfCertificates * timePerCertificate * 1000);

                // DELETION OF BAT FILE IF EXISTS
                if (File.Exists(BatFile))
                    File.Delete(BatFile);

                // CREATE OUTPUT FOLDER IF NOT EXISTS
                if (!Directory.Exists(OutputFolder))
                    Directory.CreateDirectory(OutputFolder);

                // CREATION OF BAT FILE
                File.AppendAllText(BatFile, "");
                StreamWriter streamWriter = null;
                using (streamWriter = cmnService.J_ReturnStreamWriter(BatFile))
                {
                    cmnService.J_WriteLine(ref streamWriter, "@echo off");
                    if (Signed)
                    {
                        cmnService.J_WriteLine(ref streamWriter,
                            $"java -cp \".;lib/*\" PDFGeneratorCLI \"{InputZipFilePath}\" \"{PasswordZip}\" \"{OutputFolder}\" SIGN");
                    }
                    else
                    {
                        cmnService.J_WriteLine(ref streamWriter,
                            $"java -cp \".;lib/*\" PDFGeneratorCLI \"{InputZipFilePath}\" \"{PasswordZip}\" \"{OutputFolder}\"");
                    }
                }

                // EXECUTE BAT FILE
                ProcessStartInfo processInfo = new ProcessStartInfo
                {
                    FileName = BatFile,
                    CreateNoWindow = true,
                    UseShellExecute = false,
                    RedirectStandardInput = Signed, // Enable input redirection only for signed PDFs
                    WorkingDirectory = Path.Combine(Application.StartupPath, FolderPath)
                };

                using (Process process = Process.Start(processInfo))
                {
                    if (process == null)
                    {
                        cmnService.J_UserMessage("Failed to start process");
                        return false;
                    }

                    if (Signed)
                    {
                        // Send ENTER to handle PIN prompt
                        try
                        {
                            process.StandardInput.WriteLine();
                            process.StandardInput.Flush();
                            process.StandardInput.Close();
                        }
                        catch (Exception inputEx)
                        {
                            cmnService.J_UserMessage($"Input handling error: {inputEx.Message}");
                        }
                    }

                    //process.WaitForExit(NoOfCertificates * intTimeInterval); // 
                    process.WaitForExit(intEstimatedTimeMilliseconds); // 

                    // CHECK FOR PDF OUTPUT
                    string[] pdfFiles = Directory.GetFiles(OutputFolder, "*.pdf");
                    if (pdfFiles.Length > 0)
                    {
                        //cmnService.J_UserMessage($"{pdfFiles.Length} PDFs generated successfully.");
                        return true;
                    }
                    else
                    {
                        //cmnService.J_UserMessage("No PDF files were generated.");
                        return false;
                    }
                }
            }
            catch (Exception err)
            {
                cmnService.J_UserMessage("Error in PDF generation process: " + err.Message);
                return false;
            }
        }
