        #region CountBatchesGroupedByPAN
        public Dictionary<string, int> CountBatchesfromExtractedTextFile(string filePath, string Part )
        {
            if (!File.Exists(filePath))
                throw new FileNotFoundException("File not found.", filePath);

            string[] lines = File.ReadAllLines(filePath);

            // Dictionary to hold PAN → Count
            Dictionary<string, int> panCounts = new Dictionary<string, int>();
            //
            string strSearch = "";
            if (Part.Contains("PartB"))
                strSearch = "PB^";
            else
                strSearch = "SP^";
            //
            foreach (var line in lines)
            {
                if (line.StartsWith(strSearch))
                {
                    var parts = line.Split('^');

                    if (parts.Length >= 2)
                    {
                        string pan = parts[1];

                        if (panCounts.ContainsKey(pan))
                            panCounts[pan]++;
                        else
                            panCounts[pan] = 1;
                    }
                }
            }

            return panCounts;
        }
        #endregion

        #region SignCertificates
        public bool SignCertificates(string OutputFolder)
        {
            try
            {
                //this.Cursor = Cursors.WaitCursor;
                DirectorySecurity securityRules = new DirectorySecurity();
                securityRules.AddAccessRule(new System.Security.AccessControl.FileSystemAccessRule("Everyone", System.Security.AccessControl.FileSystemRights.FullControl, System.Security.AccessControl.InheritanceFlags.ContainerInherit | System.Security.AccessControl.InheritanceFlags.ObjectInherit, System.Security.AccessControl.PropagationFlags.None, System.Security.AccessControl.AccessControlType.Allow));
                //
                global2.PDFSign PDFSign;
                //
                PDFSign = ReturnDSC("", "");
                //--
                if (PDFSign == null)
                {
                    //this.Cursor = Cursors.Default;
                    //System.Diagnostics.Process.Start(txtOutputFolder.Text);
                    return false;
                }
                //--
                DirectoryInfo diPath = new DirectoryInfo(OutputFolder);
                foreach (var file in diPath.GetFiles("*.pdf"))
                {
                    string strPan = string.Empty;
                    //--
                    if (file.Name.Length >= 10)
                        strPan = cmnService.J_Left(file.Name, 10);
                    //--
                    //string[] files = System.IO.Directory.GetFiles(txtOutputFolder.Text, strPan + "*.pdf", System.IO.SearchOption.TopDirectoryOnly);
                    string[] files = System.IO.Directory.GetFiles(OutputFolder, file.ToString(), System.IO.SearchOption.TopDirectoryOnly);
                    //PdfReader pdfReader = new PdfReader(Path.Combine(txtOutputFolder.Text.Trim(), strPan + ".pdf"));
                    PdfReader pdfReader = new PdfReader(Path.Combine(OutputFolder.Trim(), file.ToString()));
                    int numberOfPages = pdfReader.NumberOfPages;
                    //-------------------------------------------------------------------------------------------
                    if (Create_Signature(PDFSign,
                                            Path.Combine(OutputFolder.Trim(), file.ToString()),
                                            Path.Combine(OutputFolder.Trim(), file.ToString()),
                                            "",
                                            400,
                                            10,
                                            100,
                                            50,
                                            numberOfPages) == false)
                    {
                        File.Delete(Path.Combine(OutputFolder.Trim(), file.ToString()));
                        //this.Cursor = Cursors.Default;
                        //txtOutputFolder.Select();
                        return false;
                    }
                    //lblWait.Visible = true;
                    //this.Cursor = Cursors.WaitCursor;
                }
                //this.Cursor = Cursors.Default;
                //lblWait.Visible = false;
                //System.Diagnostics.Process.Start(txtOutputFolder.Text);
                return true;
            }
            catch (Exception ERR)
            {
                return false;
            }
        }

