        public static List<string> GetConnectedExternalDrives()
        {
            List<string> externalDrives = new List<string>();
            try
            {
                // Map USB disk DeviceIDs to drive letters
                var usbDrives = new Dictionary<string, string>(); // [DeviceID] -> [DriveLetter]
                using (var searcher = new ManagementObjectSearcher(
                    "SELECT * FROM Win32_DiskDrive WHERE InterfaceType='USB'"))
                {
                    foreach (ManagementObject usbDrive in searcher.Get())
                    {
                        string deviceId = usbDrive["DeviceID"]?.ToString();
                        string model = usbDrive["Model"]?.ToString();
                        // Now find associated drive letters
                        using (var partitionSearcher = new ManagementObjectSearcher(
                            "ASSOCIATORS OF {Win32_DiskDrive.DeviceID='" + deviceId.Replace("\\", "\\\\") + "'} " +
                            "WHERE AssocClass = Win32_DiskDriveToDiskPartition"))
                        {
                            foreach (ManagementObject partition in partitionSearcher.Get())
                            {
                                using (var logicalSearcher = new ManagementObjectSearcher(
                                    "ASSOCIATORS OF {Win32_DiskPartition.DeviceID='" + partition["DeviceID"] + "'} " +
                                    "WHERE AssocClass = Win32_LogicalDiskToPartition"))
                                {
                                    foreach (ManagementObject logical in logicalSearcher.Get())
                                    {
                                        string driveLetter = logical["DeviceID"]?.ToString();
                                        if (!string.IsNullOrEmpty(driveLetter))
                                        {
                                            DriveInfo di = new DriveInfo(driveLetter);
                                            if (di.IsReady && di.TotalSize > 0)
                                            {
                                                externalDrives.Add($"USB Drive: {model} ({driveLetter})");
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("WMI error: " + ex.Message);
                // Log error if needed
            }

            return externalDrives;
        }
        //--
        private List<string> GetFilteredExternalDrives()
        {
            List<string> drives = new List<string>();

            foreach (DriveInfo drive in DriveInfo.GetDrives())
            {
                try
                {
                    if (drive.DriveType == DriveType.Removable &&
                        drive.IsReady &&
                        drive.TotalSize > 0) // Prevents empty card readers or ghost drives
                    {
                        drives.Add(drive.Name);
                    }
                }
                catch
                {
                    // Skip unreadable or uninitialized drives
                }
            }

            return drives;
        }
