        public void DeleteAllFilesInFolder(string folderPath)
        {
            try
            {
                if (Directory.Exists(folderPath))
                {
                    string[] files = Directory.GetFiles(folderPath);
                    foreach (string file in files)
                    {
                        File.Delete(file);
                    }
                }
                else
                {
                    // Folder doesn't exist, do nothing or optionally inform
                    // cmnService.J_UserMessage($"Folder does not exist: {folderPath}");
                }
            }
            catch (Exception ex)
            {
                cmnService.J_UserMessage("Error deleting files: " + ex.Message);
            }
        }
