            //
            long lngRegDeducteeCount = 0, lngRegSalaryCount = 0, lngReg194PCount = 0;
            RegDeducteeCount = 0; RegSalaryCount = 0; Reg194PCount = 0;
            long lngCorrDeducteeAddCount = 0, lngCorrDeducteeModifyNullifyCount = 0, lngCorrDeducteePANChangeCount = 0, lngCorrSalaryChangeCount = 0, lngCorrSalaryPANChangeCount = 0, lngCorr194PChangeCount = 0, lngCorr194PPANChangeCount = 0;
            CorrDeducteeAddCount = 0; CorrDeducteeModifyNullifyCount = 0; CorrDeducteePANChangeCount = 0; CorrSalaryChangeCount = 0; CorrSalaryPANChangeCount = 0; Corr194PChangeCount = 0; Corr194PPANChangeCount = 0;
            try
            {
                //### GETTING THE BASIC INFO(s) FOR THIS 'SoftwareVersion' ###
                strSQL = "SELECT BASIC_INFO_ID FROM TRN_BASIC_INFO WHERE VERSION_NO = " + SoftwareVersion;
                drdGetBasicInfoIDs = dmlService.J_ExecSqlReturnReader(strSQL);
                if (drdGetBasicInfoIDs == null)
                    return false;
                //--
                while (drdGetBasicInfoIDs.Read())
                {
                    BasicInfoIds.Add(Convert.ToInt32(drdGetBasicInfoIDs["BASIC_INFO_ID"]));
                }
                drdGetBasicInfoIDs.Close();
                //################################
                //### REGULAR
                foreach (int BasicInfoId in BasicInfoIds)
                {
                    //-- DEDUCTEE DETAILS
                    lngRegDeducteeCount += dmlService.J_ReturnNoOfRows("SELECT COUNT(*) FROM TRN_DEDUCTEE_DETAILS WHERE BASIC_INFO_ID = " + BasicInfoId, J_QueryType.DirectQuery); // From TRN_DEDUCTEE_DETAILS
                    //-- SALARY DETAILS - ANNEXURE II
                    lngRegSalaryCount += dmlService.J_ReturnNoOfRows("SELECT COUNT(*) FROM TRN_SALARY_DETAILS WHERE BASIC_INFO_ID = " + BasicInfoId, J_QueryType.DirectQuery); // From TRN_SALARY_DETAILS
                    //-- SECTION 194P - ANNEXURE III
                    lngReg194PCount += dmlService.J_ReturnNoOfRows("SELECT COUNT(*) FROM TRN_SALARY_DETAILS_194P WHERE BASIC_INFO_ID = " + BasicInfoId, J_QueryType.DirectQuery);         // From TRN_SALARY_DETAILS_194P
                }
                //################################
                //--
                //### CORRECTION CONSUMPTION ###
                //### GETTING THE BATCH ID(s) FOR THIS 'SoftwareVersion' ###
                strSQL = "SELECT BATCH_HEADER_ID FROM COR_HDR_BATCH WHERE VERSION_NO = " + SoftwareVersion;
                drdGetBasicInfoIDs = dmlService.J_ExecSqlReturnReader(strSQL);
                if (drdGetBasicInfoIDs == null)
                    return false;
                //--
                while (drdGetBasicInfoIDs.Read())
                {
                    BatchHeaderIds.Add(Convert.ToInt32(drdGetBasicInfoIDs["BATCH_HEADER_ID"]));
                }
                drdGetBasicInfoIDs.Close();
                //################################
                //-- 
                //-- DEDUCTEE DETAILS

                foreach (int BatchHeaderId in BatchHeaderIds)
                {
                    //-- ADD
                    lngCorrDeducteeAddCount += dmlService.J_ReturnNoOfRows("SELECT COUNT(*) FROM COR_TRN_DEDUCTEE_DETAILS WHERE MODE = '" + T_CorrectionMode.Add + "' AND BATCH_HEADER_ID = " + BatchHeaderId, J_QueryType.DirectQuery);
                    //-- MODIFY
                    lngCorrDeducteeModifyNullifyCount += dmlService.J_ReturnNoOfRows("SELECT COUNT(*) FROM COR_TRN_DEDUCTEE_DETAILS WHERE MODE = '" + T_CorrectionMode.Modify + "' AND BATCH_HEADER_ID = " + BatchHeaderId, J_QueryType.DirectQuery);
                    //-- PAN_CHANGE
                    lngCorrDeducteePANChangeCount += dmlService.J_ReturnNoOfRows("SELECT COUNT(*) FROM COR_TRN_DEDUCTEE_DETAILS WHERE PAN_UPDATION_INDICATOR = " + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + BatchHeaderId, J_QueryType.DirectQuery);
                    //-- SALARY DETAILS - ANNEXURE II
                    //-- ADD/MODIFY 
                    lngCorrSalaryChangeCount += dmlService.J_ReturnNoOfRows("SELECT COUNT(*) FROM COR_TRN_SALARY_DETAILS WHERE (MODE = '" + T_CorrectionMode.Add + "' OR MODE = '" + T_CorrectionMode.Delete + "') AND BATCH_HEADER_ID = " + BatchHeaderId, J_QueryType.DirectQuery);
                    //-- PAN CHANGE
                    lngCorrSalaryPANChangeCount += dmlService.J_ReturnNoOfRows("SELECT COUNT(*) FROM COR_TRN_SALARY_DETAILS WHERE PAN_UPDATION_INDICATOR = " + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + BatchHeaderId, J_QueryType.DirectQuery);
                    //-- SALARY DETAILS - ANNEXURE III
                    //-- ADD/MODIFY 
                    lngCorr194PChangeCount += dmlService.J_ReturnNoOfRows("SELECT COUNT(*) FROM COR_TRN_SALARY_DETAILS_194P WHERE (MODE = '" + T_CorrectionMode.Add + "' OR MODE = '" + T_CorrectionMode.Delete + "') AND BATCH_HEADER_ID = " + BatchHeaderId, J_QueryType.DirectQuery);
                    //-- PAN CHANGE
                    lngCorr194PPANChangeCount += dmlService.J_ReturnNoOfRows("SELECT COUNT(*) FROM COR_TRN_SALARY_DETAILS_194P WHERE PAN_UPDATION_INDICATOR = " + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + BatchHeaderId, J_QueryType.DirectQuery);
                    //
                }
                //################################
                RegDeducteeCount = lngRegDeducteeCount;
                RegSalaryCount = lngRegSalaryCount;
                Reg194PCount = lngReg194PCount;
                //
                CorrDeducteeAddCount = lngCorrDeducteeAddCount;
                CorrDeducteeModifyNullifyCount = lngCorrDeducteeModifyNullifyCount;
                CorrDeducteePANChangeCount = lngCorrDeducteePANChangeCount;
                //
                CorrSalaryChangeCount = lngCorrSalaryChangeCount;
                CorrSalaryPANChangeCount = lngCorrSalaryPANChangeCount;
                //
                Corr194PChangeCount = lngCorr194PChangeCount;
                Corr194PPANChangeCount = lngCorr194PPANChangeCount;
                //
                return true;
            }
            catch (Exception err)
            {
                cmnService.J_UserMessage(err.Message);
                return false;
            }
        }
        #endregion

        #region Total_Consumption_Count
        //-- 2025/07/17 (Corrected Safe Version)
        public bool Total_Consumption_Count(double SoftwareVersion,
                                             out long RegDeducteeCount,
                                             out long RegSalaryCount,
                                             out long Reg194PCount,
                                             out long CorrDeducteeAddCount,
                                             out long CorrDeducteeModifyNullifyCount,
                                             out long CorrDeducteePANChangeCount,
                                             out long CorrSalaryChangeCount,
                                             out long CorrSalaryPANChangeCount,
                                             out long Corr194PChangeCount,
                                             out long Corr194PPANChangeCount)
        {
            RegDeducteeCount = 0;
            RegSalaryCount = 0;
            Reg194PCount = 0;

            CorrDeducteeAddCount = 0;
            CorrDeducteeModifyNullifyCount = 0;
            CorrDeducteePANChangeCount = 0;
            CorrSalaryChangeCount = 0;
            CorrSalaryPANChangeCount = 0;
            Corr194PChangeCount = 0;
            Corr194PPANChangeCount = 0;
            //
            try
            {
                List<int> BasicInfoIds = new List<int>();
                List<int> BatchHeaderIds = new List<int>();

                //------------------------------------------------------
                // GET BASIC_INFO_IDs
                //------------------------------------------------------
                string strSQL = "SELECT BASIC_INFO_ID FROM TRN_BASIC_INFO WHERE VERSION_NO = " + SoftwareVersion;

                using (IDataReader dr = dmlService.J_ExecSqlReturnReader(strSQL))
                {
                    if (dr == null)
                        return false;

                    while (dr.Read())
                    {
                        BasicInfoIds.Add(Convert.ToInt32(dr["BASIC_INFO_ID"]));
                    }
                }

                //------------------------------------------------------
                // REGULAR COUNTS
                //------------------------------------------------------
                foreach (int BasicInfoId in BasicInfoIds)
                {
                    RegDeducteeCount += dmlService.J_ReturnNoOfRows(
                        "SELECT COUNT(*) FROM TRN_DEDUCTEE_DETAILS WHERE BASIC_INFO_ID = " + BasicInfoId,
                        J_QueryType.DirectQuery);

                    RegSalaryCount += dmlService.J_ReturnNoOfRows(
                        "SELECT COUNT(*) FROM TRN_SALARY_DETAILS WHERE BASIC_INFO_ID = " + BasicInfoId,
                        J_QueryType.DirectQuery);

                    Reg194PCount += dmlService.J_ReturnNoOfRows(
                        "SELECT COUNT(*) FROM TRN_SALARY_DETAILS_194P WHERE BASIC_INFO_ID = " + BasicInfoId,
                        J_QueryType.DirectQuery);
                }

                //------------------------------------------------------
                // GET BATCH_HEADER_IDs
                //------------------------------------------------------
                strSQL = "SELECT BATCH_HEADER_ID FROM COR_HDR_BATCH WHERE VERSION_NO = " + SoftwareVersion;

                using (IDataReader dr = dmlService.J_ExecSqlReturnReader(strSQL))
                {
                    if (dr == null)
                        return false;

                    while (dr.Read())
                    {
                        BatchHeaderIds.Add(Convert.ToInt32(dr["BATCH_HEADER_ID"]));
                    }
                }

                //------------------------------------------------------
                // CORRECTION COUNTS
                //------------------------------------------------------
                foreach (int BatchHeaderId in BatchHeaderIds)
                {
                    CorrDeducteeAddCount += dmlService.J_ReturnNoOfRows(
                        "SELECT COUNT(*) FROM COR_TRN_DEDUCTEE_DETAILS WHERE MODE = '" + T_CorrectionMode.Add + "' AND BATCH_HEADER_ID = " + BatchHeaderId,
                        J_QueryType.DirectQuery);

                    CorrDeducteeModifyNullifyCount += dmlService.J_ReturnNoOfRows(
                        "SELECT COUNT(*) FROM COR_TRN_DEDUCTEE_DETAILS WHERE MODE = '" + T_CorrectionMode.Modify + "' AND BATCH_HEADER_ID = " + BatchHeaderId,
                        J_QueryType.DirectQuery);

                    CorrDeducteePANChangeCount += dmlService.J_ReturnNoOfRows(
                        "SELECT COUNT(*) FROM COR_TRN_DEDUCTEE_DETAILS WHERE PAN_UPDATION_INDICATOR = " + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + BatchHeaderId,
                        J_QueryType.DirectQuery);

                    CorrSalaryChangeCount += dmlService.J_ReturnNoOfRows(
                        "SELECT COUNT(*) FROM COR_TRN_SALARY_DETAILS WHERE (MODE = '" + T_CorrectionMode.Add + "' OR MODE = '" + T_CorrectionMode.Delete + "') AND BATCH_HEADER_ID = " + BatchHeaderId,
                        J_QueryType.DirectQuery);

                    CorrSalaryPANChangeCount += dmlService.J_ReturnNoOfRows(
                        "SELECT COUNT(*) FROM COR_TRN_SALARY_DETAILS WHERE PAN_UPDATION_INDICATOR = " + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + BatchHeaderId,
                        J_QueryType.DirectQuery);

                    Corr194PChangeCount += dmlService.J_ReturnNoOfRows(
                        "SELECT COUNT(*) FROM COR_TRN_SALARY_DETAILS_194P WHERE (MODE = '" + T_CorrectionMode.Add + "' OR MODE = '" + T_CorrectionMode.Delete + "') AND BATCH_HEADER_ID = " + BatchHeaderId,
                        J_QueryType.DirectQuery);

                    Corr194PPANChangeCount += dmlService.J_ReturnNoOfRows(
                        "SELECT COUNT(*) FROM COR_TRN_SALARY_DETAILS_194P WHERE PAN_UPDATION_INDICATOR = " + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + BatchHeaderId,
                        J_QueryType.DirectQuery);
                }

                return true;
            }
            catch (Exception err)
            {
                cmnService.J_UserMessage(err.Message);
                return false;
            }
        }
        #endregion

        #region GetFormNoIT2025

        public string GetFormNoIT2025(
            string formType)
        {
            if (string.IsNullOrWhiteSpace(formType))
                return "";

            string strFormType =
                formType.Trim().ToUpper();

            //---------------------------------------------------------
            // Already in new API form-code format
            //---------------------------------------------------------
            if (strFormType == "138" ||
                strFormType == "140" ||
                strFormType == "143" ||
                strFormType == "144")
            {
                return strFormType;
            }

            //---------------------------------------------------------
            // Existing TDSMAN form numbers
            //---------------------------------------------------------
            switch (strFormType)
            {
                case "24Q":
                    return "138";

                case "26Q":
                    return "140";

                case "27EQ":
                    return "143";

                case "27Q":
                    return "144";

                default:
                    return "";
            }
        }

        #endregion

