            //---------------------------------------------------------
            if (strFormType == "24Q" ||
                strFormType == "26Q" ||
                strFormType == "27EQ" ||
                strFormType == "27Q")
            {
                return strFormType;
            }

            //---------------------------------------------------------
            // Existing TDSMAN form numbers
            //---------------------------------------------------------
            switch (strFormType)
            {
                case "138":
                    return "24Q";

                case "140":
                    return "26Q";

                case "143":
                    return "27EQ";

                case "144":
                    return "27Q";

                default:
                    return "";
            }
        }

